1	//! Dynamic Row Reader
2	//!
3	//! Schema-agnostic Parquet reader that reads files into dynamic Value/Row types
4	//! without requiring compile-time type information.
5	//!
6	//! This is inspired by parquet-go's Row/Value API and enables:
7	//! - Reading files without knowing the schema at compile time
8	//! - Generic validation tools (like `pq validate`)
9	//! - Schema evolution and migration utilities
10	//!
11	//! ## Example
12	//! ```zig
13	//! var reader = try DynamicReader.init(allocator, file);
14	//! defer reader.deinit();
15	//!
16	//! for (0..reader.getNumRowGroups()) |rg_idx| {
17	//!     const rows = try reader.readAllRows(rg_idx);
18	//!     defer for (rows) |row| row.deinit();
19	//!
20	//!     for (rows) |row| {
21	//!         // row.values[i] contains Value for column i
22	//!     }
23	//! }
24	//! ```
25	
26	const std = @import("std");
27	const safe = @import("safe.zig");
28	const format = @import("format.zig");
29	const thrift = @import("thrift/mod.zig");
30	const compress = @import("compress/mod.zig");
31	const dictionary = @import("encoding/dictionary.zig");
32	const column_decoder = @import("column_decoder.zig");
33	const value_mod = @import("value.zig");
34	const seekable_reader = @import("seekable_reader.zig");
35	const parquet_reader = @import("parquet_reader.zig");
36	const errors_mod = @import("errors.zig");
37	const schema_mod = @import("schema.zig");
38	const nested_mod = @import("nested.zig");
39	const row_ranges_mod = @import("row_ranges.zig");
40	const page_filter_mod = @import("page_filter.zig");
41	const page_index_reader_mod = @import("page_index_reader.zig");
42	const page_range_reader_mod = @import("page_range_reader.zig");
43	
44	pub const Value = value_mod.Value;
45	pub const Row = value_mod.Row;
46	pub const SeekableReader = seekable_reader.SeekableReader;
47	pub const BackendCleanup = parquet_reader.BackendCleanup;
48	pub const ChecksumOptions = parquet_reader.ChecksumOptions;
49	pub const RowRanges = row_ranges_mod.RowRanges;
50	pub const ColumnFilter = page_filter_mod.ColumnFilter;
51	
52	/// Options for DynamicReader initialization
53	pub const DynamicReaderOptions = struct {
54	    /// Checksum validation options
55	    checksum: ChecksumOptions = .{},
56	};
57	
58	/// Error type for dynamic reader operations.
59	/// Composed from categorized error sets — no more `SchemaParseError` coalescing.
60	pub const DynamicReaderError = errors_mod.DynamicReaderError;
61	
62	const crc = std.hash.crc;
63	
64	/// Compute CRC32 checksum for page data (per Parquet spec, covers compressed data)
65	fn computePageCrc(data: []const u8) i32 {
66	    return @bitCast(crc.Crc32.hash(data));
67	}
68	
69	/// Safely cast i32 page size/count to usize, validating non-negative.
70	fn safePageSize(size: i32) error{InvalidPageSize}!usize {
71	    return safe.cast(size) catch return error.InvalidPageSize;
72	}
73	
74	/// Safely cast i64 row count to usize, validating non-negative.
75	fn safeRowCount(count: i64) error{InvalidRowCount}!usize {
76	    return safe.cast(count) catch return error.InvalidRowCount;
77	}
78	
79	const safeTypeLength = column_decoder.safeTypeLength;
80	
81	/// Schema-agnostic Parquet reader
82	pub const DynamicReader = struct {
83	    allocator: std.mem.Allocator,
84	    source: SeekableReader,
85	    metadata: format.FileMetaData,
86	    footer_data: []u8,
87	    checksum_options: ChecksumOptions,
88	    _backend_cleanup: ?BackendCleanup = null,
89	    /// Arena for `bytes_val` / `fixed_bytes_val` payloads decoded into rows.
90	    /// Lives as long as the reader — caller must deinit rows before the reader.
91	    /// Rows produced by the reader set `bytes_borrowed = true` so their byte
92	    /// payloads are not freed per-value; the arena is freed en masse in deinit.
93	    bytes_arena: std.heap.ArenaAllocator,
94	
95	    const Self = @This();
96	
97	    const TopColInfo = struct {
98	        leaf_start: usize,
99	        leaf_count: usize,
100	        is_nested: bool,
101	        schema_node: *const schema_mod.SchemaNode,
102	    };
103	
104	    /// Get the SeekableReader interface.
105	    pub fn getSource(self: *const Self) SeekableReader {
106	        return self.source;
107	    }
108	
109	    /// Initialize from a SeekableReader. The caller manages backend lifetime
110	    /// unless _backend_cleanup is set (by convenience constructors in api/zig/).
111	    pub fn initFromSeekable(allocator: std.mem.Allocator, source: SeekableReader, options: DynamicReaderOptions) DynamicReaderError!Self {
112	        const info = try parquet_reader.parseFooter(allocator, source);
113	        return Self{
114	            .allocator = allocator,
115	            .source = source,
116	            .metadata = info.metadata,
117	            .footer_data = info.footer_data,
118	            .checksum_options = options.checksum,
119	            .bytes_arena = std.heap.ArenaAllocator.init(allocator),
120	        };
121	    }
122	
123	    pub fn deinit(self: *Self) void {
124	        // Free schema element names
125	        for (self.metadata.schema) |elem| {
126	            if (elem.name.len > 0) {
127	                self.allocator.free(elem.name);
128	            }
129	        }
130	        self.allocator.free(self.metadata.schema);
131	
132	        // Free row groups
133	        for (self.metadata.row_groups) |rg| {
134	            for (rg.columns) |col| {
135	                if (col.file_path) |fp| self.allocator.free(fp);
136	                if (col.meta_data) |meta| {
137	                    self.allocator.free(meta.encodings);
138	                    for (meta.path_in_schema) |path| {
139	                        self.allocator.free(path);
140	                    }
141	                    self.allocator.free(meta.path_in_schema);
142	                    if (meta.statistics) |stats| {
143	                        if (stats.max) |m| self.allocator.free(m);
144	                        if (stats.min) |m| self.allocator.free(m);
145	                        if (stats.max_value) |m| self.allocator.free(m);
146	                        if (stats.min_value) |m| self.allocator.free(m);
147	                    }
148	                    // Free geospatial statistics if present
149	                    if (meta.geospatial_statistics) |geo_stats| {
150	                        if (geo_stats.geospatial_types) |gt| self.allocator.free(gt);
151	                    }
152	                }
153	            }
154	            if (rg.sorting_columns) |sc| self.allocator.free(sc);
155	            self.allocator.free(rg.columns);
156	        }
157	        self.allocator.free(self.metadata.row_groups);
158	
159	        // Free key-value metadata
160	        if (self.metadata.key_value_metadata) |kvs| {
161	            for (kvs) |kv| {
162	                self.allocator.free(kv.key);
163	                if (kv.value) |v| self.allocator.free(v);
164	            }
165	            self.allocator.free(kvs);
166	        }
167	
168	        // Free created_by
169	        if (self.metadata.created_by) |cb| {
170	            self.allocator.free(cb);
171	        }
172	
173	        self.allocator.free(self.footer_data);
174	
175	        self.bytes_arena.deinit();
176	
177	        if (self._backend_cleanup) |cleanup| {
178	            cleanup.deinit_fn(cleanup.ptr, self.allocator);
179	        }
180	    }
181	
182	    /// Get the schema
183	    pub fn getSchema(self: *const Self) []const format.SchemaElement {
184	        return self.metadata.schema;
185	    }
186	
187	    /// Get the number of row groups
188	    pub fn getNumRowGroups(self: *const Self) usize {
189	        return self.metadata.row_groups.len;
190	    }
191	
192	    /// Get the number of rows in a specific row group
193	    pub fn getRowGroupNumRows(self: *const Self, row_group_index: usize) i64 {
194	        if (row_group_index >= self.metadata.row_groups.len) return 0;
195	        return self.metadata.row_groups[row_group_index].num_rows;
196	    }
197	
198	    /// Get total number of rows across all row groups
199	    pub fn getTotalNumRows(self: *const Self) i64 {
200	        return self.metadata.num_rows;
201	    }
202	
203	    /// Get the number of leaf columns
204	    pub fn getNumColumns(self: *const Self) usize {
205	        var count: usize = 0;
206	        for (self.metadata.schema) |elem| {
207	            if (elem.type_ != null and elem.num_children == null) {
208	                count += 1;
209	            }
210	        }
211	        return count;
212	    }
213	
214	    /// Get the schema element for a leaf column by column index
215	    pub fn getLeafSchemaElement(self: *const Self, col_idx: usize) ?format.SchemaElement {
216	        var count: usize = 0;
217	        for (self.metadata.schema) |elem| {
218	            if (elem.type_ != null and elem.num_children == null) {
219	                if (count == col_idx) {
220	                    return elem;
221	                }
222	                count += 1;
223	            }
224	        }
225	        return null;
226	    }
227	
228	    /// Get the logical type for a column, if any
229	    pub fn getColumnLogicalType(self: *const Self, col_idx: usize) ?format.LogicalType {
230	        const elem = self.getLeafSchemaElement(col_idx) orelse return null;
231	        return elem.logical_type;
232	    }
233	
234	    /// Check if a column has a specific logical type
235	    pub fn isColumnType(self: *const Self, col_idx: usize, logical: format.LogicalType) bool {
236	        const lt = self.getColumnLogicalType(col_idx) orelse return false;
237	        return std.meta.eql(lt, logical);
238	    }
239	
240	    /// Get statistics for a column in a specific row group.
241	    /// Returns null if the column or row group doesn't exist, or if no statistics are available.
242	    pub fn getColumnStatistics(
243	        self: *const Self,
244	        column_index: usize,
245	        row_group_index: usize,
246	    ) ?format.Statistics {
247	        if (row_group_index >= self.metadata.row_groups.len) return null;
248	        const rg = self.metadata.row_groups[row_group_index];
249	        if (column_index >= rg.columns.len) return null;
250	        const col = rg.columns[column_index];
251	        const meta = col.meta_data orelse return null;
252	        return meta.statistics;
253	    }
254	
255	    /// Get column metadata for a specific column in a row group.
256	    /// Returns null if the column or row group doesn't exist.
257	    pub fn getColumnMetaData(
258	        self: *const Self,
259	        column_index: usize,
260	        row_group_index: usize,
261	    ) ?format.ColumnMetaData {
262	        if (row_group_index >= self.metadata.row_groups.len) return null;
263	        const rg = self.metadata.row_groups[row_group_index];
264	        if (column_index >= rg.columns.len) return null;
265	        return rg.columns[column_index].meta_data;
266	    }
267	
268	    /// Streaming row iterator that advances through row groups automatically.
269	    /// Holds at most one row group's worth of rows in memory at a time.
270	    pub const RowIterator = struct {
271	        reader: *Self,
272	        current_rows: ?[]Row,
273	        cursor: usize,
274	        current_rg: usize,
275	        num_rgs: usize,
276	        col_indices: ?[]const usize,
277	
278	        /// Advance to the next row. Returns a pointer to the current row,
279	        /// or null when all row groups have been exhausted.
280	        /// The returned pointer is valid until the next call to `next()` that
281	        /// crosses a row group boundary, or until `deinit()` is called.
282	        pub fn next(self: *RowIterator) !?*const Row {
283	            while (true) {
284	                if (self.current_rows) |rows| {
285	                    if (self.cursor < rows.len) {
286	                        const row = &rows[self.cursor];
287	                        self.cursor += 1;
288	                        return row;
289	                    }
290	                    self.freeCurrentRows();
291	                }
292	
293	                if (self.current_rg >= self.num_rgs) return null;
294	
295	                const rows = try self.reader.readRowsInternal(self.current_rg, self.col_indices);
296	                self.current_rg += 1;
297	
298	                if (rows.len > 0) {
299	                    self.current_rows = rows;
300	                    self.cursor = 1;
301	                    return &rows[0];
302	                }
303	                self.reader.allocator.free(rows);
304	            }
305	        }
306	
307	        /// Free any currently held rows.
308	        pub fn deinit(self: *RowIterator) void {
309	            self.freeCurrentRows();
310	        }
311	
312	        fn freeCurrentRows(self: *RowIterator) void {
313	            if (self.current_rows) |rows| {
314	                for (rows) |row| row.deinit();
315	                self.reader.allocator.free(rows);
316	                self.current_rows = null;
317	            }
318	        }
319	    };
320	
321	    /// Create a row iterator that streams through all row groups.
322	    /// No I/O occurs until the first call to `next()`.
323	    pub fn rowIterator(self: *Self) RowIterator {
324	        return .{
325	            .reader = self,
326	            .current_rows = null,
327	            .cursor = 0,
328	            .current_rg = 0,
329	            .num_rgs = self.metadata.row_groups.len,
330	            .col_indices = null,
331	        };
332	    }
333	
334	    /// Create a row iterator with column projection.
335	    /// Only the specified top-level columns are read and returned.
336	    pub fn rowIteratorProjected(self: *Self, col_indices: []const usize) RowIterator {
337	        return .{
338	            .reader = self,
339	            .current_rows = null,
340	            .cursor = 0,
341	            .current_rg = 0,
342	            .num_rgs = self.metadata.row_groups.len,
343	            .col_indices = col_indices,
344	        };
345	    }
346	
347	    /// Read all rows from a row group as dynamic Value types
348	    pub fn readAllRows(self: *Self, row_group_index: usize) ![]Row {
349	        return self.readRowsInternal(row_group_index, null);
350	    }
351	
352	    /// Read rows from a row group, returning only the specified top-level columns.
353	    /// Column indices refer to top-level schema columns (not leaf columns).
354	    /// Returned rows contain values in dense order matching the projection list.
355	    pub fn readRowsProjected(self: *Self, row_group_index: usize, col_indices: []const usize) ![]Row {
356	        return self.readRowsInternal(row_group_index, col_indices);
357	    }
358	
359	    /// Read rows from a row group, applying page-index-driven filters to skip
360	    /// pages whose min/max ranges cannot match the predicates.
361	    ///
362	    /// Behavior:
363	    ///   - Every leaf column in the row group must advertise an `OffsetIndex`;
364	    ///     otherwise `error.PageIndexMissing` is returned (use `readAllRows`
365	    ///     for unindexed files).
366	    ///   - Only flat schemas are supported; `error.NestedNotSupported` is
367	    ///     returned for nested / list / map / struct columns.
368	    ///   - `filters` target leaf column indices. Columns without a filter are
369	    ///     treated as wildcards (`full(rg_num_rows)`).
370	    ///   - Pages whose row ranges don't intersect the final (intersected)
371	    ///     `RowRanges` are never read or decompressed.
372	    ///
373	    /// The returned rows are in row-group order, restricted to the final
374	    /// `RowRanges`. A stats-level predicate pushdown may still leave rows that
375	    /// don't actually match — apply value-level predicates post-decode.
376	    pub fn readRowsFiltered(
377	        self: *Self,
378	        row_group_index: usize,
379	        filters: []const ColumnFilter,
380	    ) ![]Row {
381	        if (row_group_index >= self.metadata.row_groups.len) {
382	            return try self.allocator.alloc(Row, 0);
383	        }
384	
385	        // Route bytes through reader-owned arena, mirroring readRowsInternal.
386	        const prev_bytes_alloc = value_mod.bytes_arena_allocator;
387	        value_mod.bytes_arena_allocator = self.bytes_arena.allocator();
388	        defer value_mod.bytes_arena_allocator = prev_bytes_alloc;
389	
390	        const rg = &self.metadata.row_groups[row_group_index];
391	        const num_rows = try safeRowCount(rg.num_rows);
392	        const num_leaf_columns = rg.columns.len;
393	        if (num_rows == 0 or num_leaf_columns == 0) {
394	            return try self.allocator.alloc(Row, 0);
395	        }
396	
397	        // Flat-schema-only in this first cut.
398	        const schema = self.metadata.schema;
399	        const num_top: usize = if (schema.len > 0)
400	            safe.castTo(usize, schema[0].num_children orelse 0) catch 0
401	        else
402	            0;
403	        if (num_top != 0 and num_top != num_leaf_columns) {
404	            return error.NestedNotSupported;
405	        }
406	
407	        // Validate filter column indices.
408	        for (filters) |f| {
409	            if (f.column >= num_leaf_columns) return error.InvalidArgument;
410	        }
411	
412	        // Load offset + column indexes for the whole row group.
413	        var pir = page_index_reader_mod.PageIndexReader.init(self.allocator, self.getSource());
414	        const offset_indexes = try pir.readOffsetIndexesForRowGroup(rg);
415	        defer page_index_reader_mod.freeOptionalIndexes(format.OffsetIndex, self.allocator, offset_indexes);
416	        for (offset_indexes) |oi| {
417	            if (oi == null) return error.PageIndexMissing;
418	        }
419	        const column_indexes = try pir.readColumnIndexesForRowGroup(rg);
420	        defer page_index_reader_mod.freeOptionalIndexes(format.ColumnIndex, self.allocator, column_indexes);
421	
422	        // Compute final_ranges by intersecting each filter's RowRanges.
423	        var final_ranges = try RowRanges.full(self.allocator, num_rows);
424	        defer final_ranges.deinit(self.allocator);
425	
426	        for (filters) |f| {
427	            const oi_ref = &offset_indexes[f.column].?;
428	            const ci_ref: ?*const format.ColumnIndex = if (column_indexes[f.column]) |*ci| ci else null;
429	
430	            var per_filter = try f.evaluate(ci_ref, oi_ref, num_rows, self.allocator);
431	            defer per_filter.deinit(self.allocator);
432	
433	            const next = try RowRanges.intersect(self.allocator, final_ranges, per_filter);
434	            final_ranges.deinit(self.allocator);
435	            final_ranges = next;
436	            // Early exit if the intersection is already empty — no column read needed.
437	            if (final_ranges.isEmpty()) break;
438	        }
439	
440	        if (final_ranges.isEmpty()) {
441	            return try self.allocator.alloc(Row, 0);
442	        }
443	
444	        // Per-column: fetch just the pages intersecting final_ranges and decode.
445	        const column_values = try self.allocator.alloc([]Value, num_leaf_columns);
446	        @memset(column_values, &.{});
447	        defer {
448	            for (column_values) |vals| {
449	                for (vals) |v| v.deinit(self.allocator);
450	                if (vals.len > 0) self.allocator.free(vals);
451	            }
452	            self.allocator.free(column_values);
453	        }
454	
455	        const column_rg_indices = try self.allocator.alloc([]u64, num_leaf_columns);
456	        @memset(column_rg_indices, &.{});
457	        defer {
458	            for (column_rg_indices) |idx| {
459	                if (idx.len > 0) self.allocator.free(idx);
460	            }
461	            self.allocator.free(column_rg_indices);
462	        }
463	
464	        for (0..num_leaf_columns) |col_idx| {
465	            const chunk = &rg.columns[col_idx];
466	            const oi = &offset_indexes[col_idx].?;
467	
468	            var page_result = try page_range_reader_mod.readSelectedPages(
469	                self.allocator,
470	                self.getSource(),
471	                chunk,
472	                oi,
473	                final_ranges,
474	                num_rows,
475	            );
476	            defer page_result.deinit(self.allocator);
477	
478	            if (page_result.data.len == 0) {
479	                // Nothing selected for this column → no decoded values.
480	                continue;
481	            }
482	
483	            // Decode using the substituted buffer.
484	            const decoded = try self.readColumnDynamicWithData(col_idx, row_group_index, page_result.data);
485	            // We don't use def/rep levels in the flat path; free them if present.
486	            if (decoded.def_levels) |dl| self.allocator.free(dl);
487	            if (decoded.rep_levels) |rl| self.allocator.free(rl);
488	
489	            // Build the decoded-row-idx → rg-local-row-idx mapping, constrained
490	            // to final_ranges. For flat columns, each decoded value is one row.
491	            const total = decoded.values.len;
492	            var kept_values = try std.ArrayList(Value).initCapacity(self.allocator, total);
493	            errdefer {
494	                for (kept_values.items) |v| v.deinit(self.allocator);
495	                kept_values.deinit(self.allocator);
496	            }
497	            var kept_indices = try std.ArrayList(u64).initCapacity(self.allocator, total);
498	            errdefer kept_indices.deinit(self.allocator);
499	
500	            for (decoded.values, 0..) |v, i| {
501	                const rg_row = page_result.mapDecodedRow(i) orelse {
502	                    // Shouldn't happen if the decoder produced the expected count.
503	                    return error.InvalidPageData;
504	                };
505	                if (final_ranges.contains(rg_row)) {
506	                    try kept_values.append(self.allocator, v);
507	                    try kept_indices.append(self.allocator, rg_row);
508	                } else {
509	                    v.deinit(self.allocator);
510	                }
511	            }
512	
513	            // Free the now-drained values slice (values themselves were moved or freed above).
514	            self.allocator.free(decoded.values);
515	
516	            column_values[col_idx] = try kept_values.toOwnedSlice(self.allocator);
517	            column_rg_indices[col_idx] = try kept_indices.toOwnedSlice(self.allocator);
518	        }
519	
520	        // Every column must agree on the kept row indices.
521	        const first_non_empty = blk: {
522	            for (column_rg_indices, 0..) |idx, i| {
523	                if (idx.len > 0) break :blk i;
524	            }
525	            break :blk null;
526	        };
527	        if (first_non_empty == null) {
528	            return try self.allocator.alloc(Row, 0);
529	        }
530	        const canonical = column_rg_indices[first_non_empty.?];
531	        for (column_rg_indices) |idx| {
532	            if (idx.len == 0) continue;
533	            if (idx.len != canonical.len) return error.InconsistentPageAlignment;
534	            for (idx, canonical) |a, b| {
535	                if (a != b) return error.InconsistentPageAlignment;
536	            }
537	        }
538	
539	        // Assemble flat rows from the kept per-column values.
540	        return self.assembleFlatRows(canonical.len, num_leaf_columns, column_values, null);
541	    }
542	
543	    fn readRowsInternal(self: *Self, row_group_index: usize, col_indices: ?[]const usize) ![]Row {
544	        if (row_group_index >= self.metadata.row_groups.len) {
545	            return try self.allocator.alloc(Row, 0);
546	        }
547	
548	        // Route byte payloads produced via `value_mod.dupeBytes` into the
549	        // reader-owned arena for the duration of this decode. The emitted
550	        // Rows below are marked `bytes_borrowed = true` so their byte
551	        // slices are not individually freed; the arena is released by
552	        // `DynamicReader.deinit`.
553	        const prev_bytes_alloc = value_mod.bytes_arena_allocator;
554	        value_mod.bytes_arena_allocator = self.bytes_arena.allocator();
555	        defer value_mod.bytes_arena_allocator = prev_bytes_alloc;
556	
557	        const rg = &self.metadata.row_groups[row_group_index];
558	        const num_rows = try safeRowCount(rg.num_rows);
559	        const num_leaf_columns = rg.columns.len;
560	
561	        if (num_rows == 0 or num_leaf_columns == 0) {
562	            return try self.allocator.alloc(Row, 0);
563	        }
564	
565	        const schema = self.metadata.schema;
566	        const num_top: usize = if (schema.len > 0)
567	            safe.castTo(usize, schema[0].num_children orelse 0) catch 0
568	        else
569	            0;
570	
571	        const is_flat = num_top == 0;
572	        const num_top_columns = if (is_flat) num_leaf_columns else num_top;
573	
574	        // Validate projection indices
575	        if (col_indices) |indices| {
576	            for (indices) |idx| {
577	                if (idx >= num_top_columns) return error.InvalidArgument;
578	            }
579	        }
580	
581	        // Compute top-level-to-leaf mapping for nested schemas
582	        var schema_arena = std.heap.ArenaAllocator.init(self.allocator);
583	        defer schema_arena.deinit();
584	        const sa = schema_arena.allocator();
585	
586	        const top_infos = if (!is_flat) blk: {
587	            const infos = try self.allocator.alloc(TopColInfo, num_top);
588	            errdefer self.allocator.free(infos);
589	
590	            var schema_idx: usize = 1;
591	            var leaf_offset: usize = 0;
592	            for (0..num_top) |top_idx| {
593	                if (schema_idx >= schema.len) return error.InvalidSchema;
594	                const build_result = try schema_mod.SchemaNode.buildFromElements(sa, schema, schema_idx);
595	                const lc = build_result.node.countLeafColumns();
596	                infos[top_idx] = .{
597	                    .leaf_start = leaf_offset,
598	                    .leaf_count = lc,
599	                    .is_nested = lc > 1 or !build_result.node.unwrapOptional().isPrimitive(),
600	                    .schema_node = build_result.node,
601	                };
602	                schema_idx = build_result.next_idx;
603	                leaf_offset += lc;
604	            }
605	            break :blk infos;
606	        } else null;
607	        defer if (top_infos) |ti| self.allocator.free(ti);
608	
609	        // Build set of leaf columns to read
610	        const leaf_needed = try self.allocator.alloc(bool, num_leaf_columns);
611	        defer self.allocator.free(leaf_needed);
612	
613	        if (col_indices) |indices| {
614	            @memset(leaf_needed, false);
615	            if (is_flat) {
616	                for (indices) |idx| leaf_needed[idx] = true;
617	            } else {
618	                for (indices) |top_idx| {
619	                    const info = top_infos.?[top_idx];
620	                    for (info.leaf_start..info.leaf_start + info.leaf_count) |leaf| {
621	                        if (leaf < num_leaf_columns) leaf_needed[leaf] = true;
622	                    }
623	                }
624	            }
625	        } else {
626	            @memset(leaf_needed, true);
627	        }
628	
629	        // Read needed leaf columns into fixed-size arrays
630	        const column_values = try self.allocator.alloc([]Value, num_leaf_columns);
631	        @memset(column_values, &.{});
632	        defer {
633	            for (column_values) |vals| {
634	                for (vals) |v| v.deinit(self.allocator);
635	                if (vals.len > 0) self.allocator.free(vals);
636	            }
637	            self.allocator.free(column_values);
638	        }
639	
640	        const column_def_levels = try self.allocator.alloc(?[]u32, num_leaf_columns);
641	        @memset(column_def_levels, null);
642	        defer {
643	            for (column_def_levels) |levels| {
644	                if (levels) |l| self.allocator.free(l);
645	            }
646	            self.allocator.free(column_def_levels);
647	        }
648	
649	        const column_rep_levels = try self.allocator.alloc(?[]u32, num_leaf_columns);
650	        @memset(column_rep_levels, null);
651	        defer {
652	            for (column_rep_levels) |levels| {
653	                if (levels) |l| self.allocator.free(l);
654	            }
655	            self.allocator.free(column_rep_levels);
656	        }
657	
658	        for (0..num_leaf_columns) |col_idx| {
659	            if (!leaf_needed[col_idx]) continue;
660	            const result = try self.readColumnDynamic(col_idx, row_group_index);
661	            column_values[col_idx] = result.values;
662	            column_def_levels[col_idx] = result.def_levels;
663	            column_rep_levels[col_idx] = result.rep_levels;
664	        }
665	
666	        // Assemble rows
667	        if (is_flat) {
668	            return self.assembleFlatRows(num_rows, num_leaf_columns, column_values, col_indices);
669	        }
670	        return self.assembleNestedRows(
671	            num_rows,
672	            num_leaf_columns,
673	            column_values,
674	            column_def_levels,
675	            column_rep_levels,
676	            top_infos.?,
677	            col_indices,
678	        );
679	    }
