681	    /// Read a single column dynamically
682	    fn readColumnDynamic(self: *Self, column_index: usize, row_group_index: usize) !column_decoder.DynamicDecodeResult {
683	        return self.readColumnDynamicWithData(column_index, row_group_index, null);
684	    }
685	
686	    /// Read a single column, optionally using caller-supplied page bytes.
687	    ///
688	    /// When `override_page_data` is non-null it must contain `[dict_page?]
689	    /// [data_pages...]` in the layout produced by `PageRangeReader`. This is
690	    /// the hook for filtered reads: the caller pre-reads just the data pages
691	    /// whose rows intersect the wanted `RowRanges`.
692	    fn readColumnDynamicWithData(
693	        self: *Self,
694	        column_index: usize,
695	        row_group_index: usize,
696	        override_page_data: ?[]const u8,
697	    ) !column_decoder.DynamicDecodeResult {
698	        const rg = &self.metadata.row_groups[row_group_index];
699	        if (column_index >= rg.columns.len) return error.InvalidArgument;
700	
701	        const chunk = &rg.columns[column_index];
702	        const meta = chunk.meta_data orelse return error.InvalidArgument;
703	
704	        // Read the raw page data (or use caller's buffer).
705	        const owned_page_data: ?[]u8 = if (override_page_data == null)
706	            try self.readColumnChunkData(chunk)
707	        else
708	            null;
709	        defer if (owned_page_data) |pd| self.allocator.free(pd);
710	        const page_data: []const u8 = owned_page_data orelse override_page_data.?;
711	
712	        var pos: usize = 0;
713	
714	        // Check if we have a dictionary page
715	        var string_dict: ?dictionary.StringDictionary = null;
716	        defer if (string_dict) |*d| d.deinit();
717	        var int32_dict: ?dictionary.Int32Dictionary = null;
718	        defer if (int32_dict) |*d| d.deinit();
719	        var int64_dict: ?dictionary.Int64Dictionary = null;
720	        defer if (int64_dict) |*d| d.deinit();
721	        var float32_dict: ?dictionary.Float32Dictionary = null;
722	        defer if (float32_dict) |*d| d.deinit();
723	        var float64_dict: ?dictionary.Float64Dictionary = null;
724	        defer if (float64_dict) |*d| d.deinit();
725	        var fixed_byte_array_dict: ?dictionary.FixedByteArrayDictionary = null;
726	        defer if (fixed_byte_array_dict) |*d| d.deinit();
727	        var int96_dict: ?dictionary.Int96Dictionary = null;
728	        defer if (int96_dict) |*d| d.deinit();
729	
730	        // Check for dictionary page - might be indicated by metadata OR by first page in stream
731	        // Some writers don't set dictionary_page_offset but still include dictionary pages
732	        {
733	            // Check if first page is a dictionary page (consumes header if so)
734	            var peek_thrift = thrift.CompactReader.init(page_data[pos..]);
735	            const first_header = try format.PageHeader.parse(self.allocator, &peek_thrift);
736	            defer self.freePageHeaderContents(&first_header);
737	
738	            if (first_header.dictionary_page_header) |dph| {
739	                // This is a dictionary page - consume it
740	                pos += peek_thrift.pos;
741	
742	                const dict_compressed_size = try safePageSize(first_header.compressed_page_size);
743	                const dict_uncompressed_size = try safePageSize(first_header.uncompressed_page_size);
744	                const dict_num_values = try safePageSize(dph.num_values);
745	
746	                const dict_compressed = try safe.slice(page_data, pos, dict_compressed_size);
747	                pos += dict_compressed_size;
748	
749	                // Validate CRC32 checksum if enabled
750	                if (self.checksum_options.validate_page_checksum) {
751	                    if (first_header.crc) |expected_crc| {
752	                        const actual_crc = computePageCrc(dict_compressed);
753	                        if (actual_crc != expected_crc) {
754	                            return error.PageChecksumMismatch;
755	                        }
756	                    } else if (self.checksum_options.strict_checksum) {
757	                        return error.MissingPageChecksum;
758	                    }
759	                }
760	
761	                // Decompress dictionary page if needed
762	                const dict_data = if (meta.codec != .uncompressed) blk: {
763	                    break :blk try self.decompressData(dict_compressed, meta.codec, dict_uncompressed_size);
764	                } else dict_compressed;
765	                defer if (meta.codec != .uncompressed) self.allocator.free(dict_data);
766	
767	                // Build dictionaries based on physical type
768	                const column_info_for_dict = format.getColumnInfo(self.metadata.schema, column_index);
769	                if (column_info_for_dict) |info| {
770	                    if (info.element.type_) |phys_type| {
771	                        switch (phys_type) {
772	                            .byte_array => {
773	                                string_dict = try dictionary.StringDictionary.fromPlain(self.allocator, dict_data, dict_num_values);
774	                            },
775	                            .int32 => {
776	                                int32_dict = try dictionary.Int32Dictionary.fromPlain(self.allocator, dict_data, dict_num_values);
777	                            },
778	                            .int64 => {
779	                                int64_dict = try dictionary.Int64Dictionary.fromPlain(self.allocator, dict_data, dict_num_values);
780	                            },
781	                            .float => {
782	                                float32_dict = try dictionary.Float32Dictionary.fromPlain(self.allocator, dict_data, dict_num_values);
783	                            },
784	                            .double => {
785	                                float64_dict = try dictionary.Float64Dictionary.fromPlain(self.allocator, dict_data, dict_num_values);
786	                            },
787	                            .fixed_len_byte_array => {
788	                                const fixed_len = try safeTypeLength(info.element.type_length);
789	                                if (fixed_len > 0) {
790	                                    fixed_byte_array_dict = try dictionary.FixedByteArrayDictionary.fromPlain(self.allocator, dict_data, dict_num_values, fixed_len);
791	                                }
792	                            },
793	                            .int96 => {
794	                                int96_dict = try dictionary.Int96Dictionary.fromPlain(self.allocator, dict_data, dict_num_values);
795	                            },
796	                            else => {},
797	                        }
798	                    }
799	                }
800	            }
801	            // If not a dictionary page, pos is unchanged and we'll process it as data
802	        }
803	
804	        // Get column info
805	        const column_info = format.getColumnInfo(self.metadata.schema, column_index) orelse
806	            return error.InvalidArgument;
807	
808	        // Accumulate values from all data pages
809	        var all_values: std.ArrayListUnmanaged(Value) = .empty;
810	        errdefer {
811	            for (all_values.items) |v| v.deinit(self.allocator);
812	            all_values.deinit(self.allocator);
813	        }
814	
815	        var all_def_levels: std.ArrayListUnmanaged(u32) = .empty;
816	        errdefer all_def_levels.deinit(self.allocator);
817	
818	        var all_rep_levels: std.ArrayListUnmanaged(u32) = .empty;
819	        errdefer all_rep_levels.deinit(self.allocator);
820	
821	        // Loop through all data pages
822	        while (pos < page_data.len) {
823	            // Parse data page header
824	            var thrift_reader = thrift.CompactReader.init(page_data[pos..]);
825	            const page_header = try format.PageHeader.parse(self.allocator, &thrift_reader);
826	            defer self.freePageHeaderContents(&page_header);
827	
828	            pos += thrift_reader.pos;
829	
830	            // Skip non-data pages (neither V1 nor V2)
831	            if (page_header.data_page_header == null and page_header.data_page_header_v2 == null) {
832	                const skip_size = try safePageSize(page_header.compressed_page_size);
833	                if (pos + skip_size > page_data.len) return error.EndOfData;
834	                pos += skip_size;
835	                continue;
836	            }
837	
838	            const compressed_size = try safePageSize(page_header.compressed_page_size);
839	            if (pos + compressed_size > page_data.len) return error.EndOfData;
840	            const compressed_body = try safe.slice(page_data, pos, compressed_size);
841	            pos += compressed_size;
842	
843	            // Validate CRC32 checksum if enabled
844	            if (self.checksum_options.validate_page_checksum) {
845	                if (page_header.crc) |expected_crc| {
846	                    const actual_crc = computePageCrc(compressed_body);
847	                    if (actual_crc != expected_crc) {
848	                        return error.PageChecksumMismatch;
849	                    }
850	                } else if (self.checksum_options.strict_checksum) {
851	                    return error.MissingPageChecksum;
852	                }
853	            }
854	
855	            // Handle V2 vs V1 page format differently
856	            if (page_header.data_page_header_v2) |v2| {
857	                // DataPageV2: levels are uncompressed, stored before values
858	                const rep_len = try safePageSize(v2.repetition_levels_byte_length);
859	                const def_len = try safePageSize(v2.definition_levels_byte_length);
860	                const num_values = try safePageSize(v2.num_values);
861	
862	                if (num_values == 0) continue;
863	
864	                // Extract level data (uncompressed, at start of page body)
865	                const rep_levels_data = try safe.slice(compressed_body, 0, rep_len);
866	                const def_levels_data = try safe.slice(compressed_body, rep_len, def_len);
867	                const levels_total = std.math.add(usize, rep_len, def_len) catch return error.EndOfData;
868	                if (levels_total > compressed_body.len) return error.EndOfData;
869	                const values_compressed = compressed_body[levels_total..];
870	
871	                // Decompress only the values section if needed
872	                // For V2, uncompressed_page_size is the size of the ENTIRE uncompressed page
873	                // But the levels are already uncompressed, so we need to calculate values size differently
874	                // The compressed_page_size in header is: rep_len + def_len + compressed_values_len
875	                // The uncompressed_page_size is: rep_len + def_len + uncompressed_values_len
876	                var values_data_allocated = false;
877	                const values_data = if (v2.is_compressed and meta.codec != .uncompressed) blk: {
878	                    const uncompressed_size = try safePageSize(page_header.uncompressed_page_size);
879	                    // Levels are uncompressed, so uncompressed values size = total - levels
880	                    if (uncompressed_size < levels_total) return error.EndOfData;
881	                    const values_uncompressed_size = uncompressed_size - levels_total;
882	                    // Handle empty values case - skip decompression for empty data pages
883	                    if (values_uncompressed_size == 0 or values_compressed.len == 0) {
884	                        break :blk values_compressed; // Return empty slice, no decompression needed
885	                    }
886	                    values_data_allocated = true;
887	                    break :blk try self.decompressData(values_compressed, meta.codec, values_uncompressed_size);
888	                } else values_compressed;
889	                defer if (values_data_allocated) self.allocator.free(values_data);
890	
891	                // Get value encoding from page header (used for delta encodings)
892	                const value_encoding = v2.encoding;
893	                const uses_dict = string_dict != null or int32_dict != null or int64_dict != null or float32_dict != null or float64_dict != null or int96_dict != null;
894	
895	                // Decode with V2 format (levels already extracted, no length prefix)
896	                var page_result = try column_decoder.decodeColumnDynamicV2(
897	                    self.allocator,
898	                    column_info.element,
899	                    rep_levels_data,
900	                    def_levels_data,
901	                    values_data,
902	                    num_values,
903	                    column_info.max_def_level,
904	                    column_info.max_rep_level,
905	                    uses_dict or fixed_byte_array_dict != null,
906	                    if (string_dict) |*d| d else null,
907	                    if (int32_dict) |*d| d else null,
908	                    if (int64_dict) |*d| d else null,
909	                    if (float32_dict) |*d| d else null,
910	                    if (float64_dict) |*d| d else null,
911	                    if (fixed_byte_array_dict) |*d| d else null,
912	                    if (int96_dict) |*d| d else null,
913	                    value_encoding,
914	                );
915	
916	                // Append values (transfer ownership)
917	                try all_values.appendSlice(self.allocator, page_result.values);
918	                self.allocator.free(page_result.values);
919	                page_result.values = &.{};
920	
921	                // Append levels
922	                if (page_result.def_levels) |dl| {
923	                    try all_def_levels.appendSlice(self.allocator, dl);
924	                    self.allocator.free(dl);
925	                }
926	                if (page_result.rep_levels) |rl| {
927	                    try all_rep_levels.appendSlice(self.allocator, rl);
928	                    self.allocator.free(rl);
929	                }
930	            } else if (page_header.data_page_header) |dph| {
931	                // DataPageV1: levels are inside compressed data with length prefixes
932	
933	                // Decompress entire page if needed
934	                const value_data = if (meta.codec != .uncompressed) blk: {
935	                    const uncompressed_size = try safePageSize(page_header.uncompressed_page_size);
936	                    break :blk try self.decompressData(compressed_body, meta.codec, uncompressed_size);
937	                } else compressed_body;
938	                defer if (meta.codec != .uncompressed) self.allocator.free(value_data);
939	
940	                const num_values = try safePageSize(dph.num_values);
941	                if (num_values == 0) continue;
942	
943	                // Get encodings from page header
944	                const uses_dict_v1 = string_dict != null or int32_dict != null or int64_dict != null or float32_dict != null or float64_dict != null or fixed_byte_array_dict != null or int96_dict != null;
945	                const def_level_encoding = dph.definition_level_encoding;
946	                const rep_level_encoding = dph.repetition_level_encoding;
947	                const value_encoding_v1 = dph.encoding;
948	
949	                // Decode dynamically with level and value encodings
950	                var page_result = try column_decoder.decodeColumnDynamicWithValueEncoding(
951	                    self.allocator,
952	                    column_info.element,
953	                    value_data,
954	                    num_values,
955	                    column_info.max_def_level,
956	                    column_info.max_rep_level,
957	                    uses_dict_v1,
958	                    if (string_dict) |*d| d else null,
959	                    if (int32_dict) |*d| d else null,
960	                    if (int64_dict) |*d| d else null,
961	                    if (float32_dict) |*d| d else null,
962	                    if (float64_dict) |*d| d else null,
963	                    if (fixed_byte_array_dict) |*d| d else null,
964	                    if (int96_dict) |*d| d else null,
965	                    def_level_encoding,
966	                    rep_level_encoding,
967	                    value_encoding_v1,
968	                );
969	
970	                // Append values (transfer ownership)
971	                try all_values.appendSlice(self.allocator, page_result.values);
972	                self.allocator.free(page_result.values);
973	                page_result.values = &.{};
974	
975	                // Append levels
976	                if (page_result.def_levels) |dl| {
977	                    try all_def_levels.appendSlice(self.allocator, dl);
978	                    self.allocator.free(dl);
979	                }
980	                if (page_result.rep_levels) |rl| {
981	                    try all_rep_levels.appendSlice(self.allocator, rl);
982	                    self.allocator.free(rl);
983	                }
984	            }
985	        }
986	
987	        return .{
988	            .values = try all_values.toOwnedSlice(self.allocator),
989	            .def_levels = if (all_def_levels.items.len > 0) try all_def_levels.toOwnedSlice(self.allocator) else null,
990	            .rep_levels = if (all_rep_levels.items.len > 0) try all_rep_levels.toOwnedSlice(self.allocator) else null,
991	        };
992	    }
