994	    /// Assemble rows from columnar data.
995	    /// Uses the file schema to reconstruct logical top-level columns, properly
996	    /// rebuilding nested types (structs, maps, nested lists) via assembleValues.
997	    fn assembleNestedRows(
998	        self: *Self,
999	        num_rows: usize,
1000	        num_leaf_columns: usize,
1001	        column_values: [][]Value,
1002	        column_def_levels: []?[]u32,
1003	        column_rep_levels: []?[]u32,
1004	        top_infos: []const TopColInfo,
1005	        projected_top_indices: ?[]const usize,
1006	    ) ![]Row {
1007	        const num_top = top_infos.len;
1008	
1009	        // Phase 1: For each nested top-level column, assemble all rows at once.
1010	        const assembled_cols = try self.allocator.alloc(?[]Value, num_top);
1011	        defer {
1012	            for (assembled_cols) |opt_vals| {
1013	                if (opt_vals) |vals| {
1014	                    for (vals) |v| v.deinit(self.allocator);
1015	                    self.allocator.free(vals);
1016	                }
1017	            }
1018	            self.allocator.free(assembled_cols);
1019	        }
1020	        @memset(assembled_cols, null);
1021	
1022	        for (0..num_top) |top_idx| {
1023	            const info = top_infos[top_idx];
1024	            if (!info.is_nested) continue;
1025	            if (projected_top_indices) |indices| {
1026	                var needed = false;
1027	                for (indices) |pi| {
1028	                    if (pi == top_idx) { needed = true; break; }
1029	                }
1030	                if (!needed) continue;
1031	            }
1032	
1033	            const slices = try self.allocator.alloc(nested_mod.FlatColumnSlice, info.leaf_count);
1034	            defer self.allocator.free(slices);
1035	
1036	            for (0..info.leaf_count) |li| {
1037	                const phys = info.leaf_start + li;
1038	                if (phys < num_leaf_columns) {
1039	                    slices[li] = .{
1040	                        .values = column_values[phys],
1041	                        .def_levels = column_def_levels[phys] orelse &.{},
1042	                        .rep_levels = column_rep_levels[phys] orelse &.{},
1043	                    };
1044	                } else {
1045	                    slices[li] = .{ .values = &.{}, .def_levels = &.{}, .rep_levels = &.{} };
1046	                }
1047	            }
1048	
1049	            assembled_cols[top_idx] = try nested_mod.assembleValues(
1050	                self.allocator,
1051	                info.schema_node,
1052	                slices,
1053	                num_rows,
1054	            );
1055	        }
1056	
1057	        // Phase 2: Build rows with only the projected columns
1058	        const output_indices = projected_top_indices orelse blk: {
1059	            const all = try self.allocator.alloc(usize, num_top);
1060	            for (0..num_top) |i| all[i] = i;
1061	            break :blk all;
1062	        };
1063	        defer if (projected_top_indices == null) self.allocator.free(output_indices);
1064	
1065	        const num_output_cols = output_indices.len;
1066	        const rows = try self.allocator.alloc(Row, num_rows);
1067	        errdefer self.allocator.free(rows);
1068	        var rows_initialized: usize = 0;
1069	        errdefer {
1070	            for (rows[0..rows_initialized]) |row| row.deinit();
1071	        }
1072	
1073	        for (0..num_rows) |row_idx| {
1074	            const values = try self.allocator.alloc(Value, num_output_cols);
1075	            errdefer self.allocator.free(values);
1076	            var vals_initialized: usize = 0;
1077	            errdefer {
1078	                for (values[0..vals_initialized]) |v| v.deinit(self.allocator);
1079	            }
1080	
1081	            for (output_indices, 0..) |top_idx, out_idx| {
1082	                const info = top_infos[top_idx];
1083	                if (assembled_cols[top_idx]) |assembled| {
1084	                    values[out_idx] = try cloneValue(self.allocator, assembled[row_idx]);
1085	                } else {
1086	                    const phys = info.leaf_start;
1087	                    if (phys < num_leaf_columns and row_idx < column_values[phys].len) {
1088	                        values[out_idx] = try cloneValue(self.allocator, column_values[phys][row_idx]);
1089	                    } else {
1090	                        values[out_idx] = .{ .null_val = {} };
1091	                    }
1092	                }
1093	                vals_initialized += 1;
1094	            }
1095	
1096	            rows[row_idx] = .{ .values = values, .allocator = self.allocator, .bytes_borrowed = true };
1097	            rows_initialized += 1;
1098	        }
1099	
1100	        // Free assembled_cols now (will be freed by defer, setting to null avoids double-free)
1101	        for (0..num_top) |top_idx| {
1102	            if (assembled_cols[top_idx]) |vals| {
1103	                for (vals) |v| v.deinit(self.allocator);
1104	                self.allocator.free(vals);
1105	                assembled_cols[top_idx] = null;
1106	            }
1107	        }
1108	
1109	        return rows;
1110	    }
1111	
1112	    fn assembleFlatRows(
1113	        self: *Self,
1114	        num_rows: usize,
1115	        num_columns: usize,
1116	        column_values: [][]Value,
1117	        projected_col_indices: ?[]const usize,
1118	    ) ![]Row {
1119	        const output_indices = projected_col_indices orelse blk: {
1120	            const all = try self.allocator.alloc(usize, num_columns);
1121	            for (0..num_columns) |i| all[i] = i;
1122	            break :blk all;
1123	        };
1124	        defer if (projected_col_indices == null) self.allocator.free(output_indices);
1125	
1126	        const num_output_cols = output_indices.len;
1127	        const rows = try self.allocator.alloc(Row, num_rows);
1128	        var rows_initialized: usize = 0;
1129	        errdefer {
1130	            for (rows[0..rows_initialized]) |row| row.deinit();
1131	            self.allocator.free(rows);
1132	        }
1133	
1134	        for (0..num_rows) |row_idx| {
1135	            const values = try self.allocator.alloc(Value, num_output_cols);
1136	            var vals_initialized: usize = 0;
1137	            errdefer {
1138	                for (values[0..vals_initialized]) |val| val.deinit(self.allocator);
1139	                self.allocator.free(values);
1140	            }
1141	
1142	            for (output_indices, 0..) |col_idx, out_idx| {
1143	                if (row_idx < column_values[col_idx].len) {
1144	                    values[out_idx] = try cloneValue(self.allocator, column_values[col_idx][row_idx]);
1145	                } else {
1146	                    values[out_idx] = .{ .null_val = {} };
1147	                }
1148	                vals_initialized += 1;
1149	            }
1150	
1151	            rows[row_idx] = .{ .values = values, .allocator = self.allocator, .bytes_borrowed = true };
1152	            rows_initialized += 1;
1153	        }
1154	        return rows;
1155	    }
1156	
1157	    /// Read raw page data for a column chunk
1158	    fn readColumnChunkData(self: *Self, chunk: *const format.ColumnChunk) ![]u8 {
1159	        return parquet_reader.readColumnChunkData(self.allocator, self.getSource(), chunk) catch |e| {
1160	            return switch (e) {
1161	                error.InvalidArgument => error.InvalidArgument,
1162	                error.OutOfMemory => error.OutOfMemory,
1163	                error.InputOutput => error.InputOutput,
1164	                else => error.InputOutput,
1165	            };
1166	        };
1167	    }
1168	
1169	    /// Decompress page data
1170	    fn decompressData(self: *Self, compressed: []const u8, codec: format.CompressionCodec, uncompressed_size: usize) ![]u8 {
1171	        return compress.decompress(self.allocator, compressed, codec, uncompressed_size) catch |err| switch (err) {
1172	            error.OutOfMemory => return error.OutOfMemory,
1173	            error.DecompressionError => return error.DecompressionError,
1174	            error.UnsupportedCompression => return error.UnsupportedCompression,
1175	        };
1176	    }
1177	
1178	    /// Free the allocated contents within a PageHeader (statistics min/max values).
1179	    /// Does NOT free the PageHeader struct itself.
1180	    fn freePageHeaderContents(self: *Self, header: *const format.PageHeader) void {
1181	        // Use mutable copy to call deinit
1182	        var mutable_header = header.*;
1183	        mutable_header.deinit(self.allocator);
1184	    }
1185	};
1186	
1187	/// Clone a Value, allocating new memory for any heap data
1188	fn cloneValue(allocator: std.mem.Allocator, v: Value) !Value {
1189	    return switch (v) {
1190	        .null_val => .{ .null_val = {} },
1191	        .bool_val => |b| .{ .bool_val = b },
1192	        .int32_val => |i| .{ .int32_val = i },
1193	        .int64_val => |i| .{ .int64_val = i },
1194	        .float_val => |f| .{ .float_val = f },
1195	        .double_val => |d| .{ .double_val = d },
1196	        .bytes_val => |b| .{ .bytes_val = try value_mod.dupeBytes(allocator, b) },
1197	        .fixed_bytes_val => |b| .{ .fixed_bytes_val = try value_mod.dupeBytes(allocator, b) },
1198	        .list_val => |items| blk: {
1199	            const cloned = try allocator.alloc(Value, items.len);
1200	            var cloned_count: usize = 0;
1201	            errdefer {
1202	                for (cloned[0..cloned_count]) |cv| cv.deinit(allocator);
1203	                allocator.free(cloned);
1204	            }
1205	            for (items) |item| {
1206	                cloned[cloned_count] = try cloneValue(allocator, item);
1207	                cloned_count += 1;
1208	            }
1209	            break :blk .{ .list_val = cloned };
1210	        },
1211	        .map_val => |entries| blk: {
1212	            const cloned = try allocator.alloc(Value.MapEntryValue, entries.len);
1213	            var cloned_count: usize = 0;
1214	            errdefer {
1215	                for (cloned[0..cloned_count]) |e| {
1216	                    e.key.deinit(allocator);
1217	                    e.value.deinit(allocator);
1218	                }
1219	                allocator.free(cloned);
1220	            }
1221	            for (entries) |entry| {
1222	                const key = try cloneValue(allocator, entry.key);
1223	                errdefer key.deinit(allocator);
1224	                const value = try cloneValue(allocator, entry.value);
1225	                cloned[cloned_count] = .{ .key = key, .value = value };
1226	                cloned_count += 1;
1227	            }
1228	            break :blk .{ .map_val = cloned };
1229	        },
1230	        .struct_val => |fields| blk: {
1231	            const cloned = try allocator.alloc(Value.FieldValue, fields.len);
1232	            var cloned_count: usize = 0;
1233	            errdefer {
1234	                for (cloned[0..cloned_count]) |f| {
1235	                    allocator.free(f.name);
1236	                    f.value.deinit(allocator);
1237	                }
1238	                allocator.free(cloned);
1239	            }
1240	            for (fields) |field| {
1241	                const name = try allocator.dupe(u8, field.name);
1242	                errdefer allocator.free(name);
1243	                const value = try cloneValue(allocator, field.value);
1244	                cloned[cloned_count] = .{ .name = name, .value = value };
1245	                cloned_count += 1;
1246	            }
1247	            break :blk .{ .struct_val = cloned };
1248	        },
1249	    };
1250	}
1251	
1252	// =============================================================================
1253	// Tests
1254	// =============================================================================
1255	
1256	test "nested row assembly groups values by rep_level" {
1257	    const allocator = std.testing.allocator;
1258	
1259	    // Simulate a nested column with rep_levels:
1260	    // rep=0 means new row, rep>0 means continuation
1261	    // Values: [a, b, c, d, e]
1262	    // Rep levels: [0, 1, 0, 1, 1]
1263	    // Expected: Row 0 = [a, b], Row 1 = [c, d, e]
1264	
1265	    const col_values = [_]Value{
1266	        .{ .bytes_val = "a" },
1267	        .{ .bytes_val = "b" },
1268	        .{ .bytes_val = "c" },
1269	        .{ .bytes_val = "d" },
1270	        .{ .bytes_val = "e" },
1271	    };
1272	
1273	    const rep_levels = [_]u32{ 0, 1, 0, 1, 1 };
1274	
1275	    // Test the row boundary detection logic that assembleNestedRows uses
1276	    // Find row boundaries (where rep_level == 0)
1277	    var row_starts: std.ArrayListUnmanaged(usize) = .empty;
1278	    defer row_starts.deinit(allocator);
1279	
1280	    for (rep_levels, 0..) |rl, i| {
1281	        if (rl == 0) {
1282	            try row_starts.append(allocator, i);
1283	        }
1284	    }
1285	
1286	    // Verify row boundaries
1287	    try std.testing.expectEqual(@as(usize, 2), row_starts.items.len);
1288	    try std.testing.expectEqual(@as(usize, 0), row_starts.items[0]);
1289	    try std.testing.expectEqual(@as(usize, 2), row_starts.items[1]);
1290	
1291	    // Verify row 0 would contain values[0..2] = [a, b]
1292	    const row0_start = row_starts.items[0];
1293	    const row0_end = row_starts.items[1];
1294	    try std.testing.expectEqual(@as(usize, 2), row0_end - row0_start);
1295	
1296	    // Verify row 1 would contain values[2..5] = [c, d, e]
1297	    const row1_start = row_starts.items[1];
1298	    const row1_end = col_values.len;
1299	    try std.testing.expectEqual(@as(usize, 3), row1_end - row1_start);
1300	}
