1	//! FileReader - file-based SeekableReader backend
2	//!
3	//! Provides lazy reading - only reads data when requested, not at init time.
4	
5	const std = @import("std");
6	const SeekableReader = @import("../core/seekable_reader.zig").SeekableReader;
7	
8	pub const FileReader = struct {
9	    file: std.Io.File,
10	    io: std.Io,
11	    file_size: u64,
12	
13	    /// Create a FileReader from an open file handle.
14	    /// The file must be seekable and remain open while the FileReader is in use.
15	    pub fn init(file: std.Io.File, io: std.Io) SeekableReader.Error!FileReader {
16	        const file_size = file.length(io) catch return error.Unseekable;
17	        return .{ .file = file, .io = io, .file_size = file_size };
18	    }
19	
20	    /// Get a SeekableReader interface for this file.
21	    /// The FileReader must outlive the returned SeekableReader.
22	    pub fn reader(self: *FileReader) SeekableReader {
23	        return .{
24	            .ptr = self,
25	            .vtable = &vtable,
26	        };
27	    }
28	
29	    const vtable = SeekableReader.VTable{
30	        .readAt = readAt,
31	        .size = getSize,
32	    };
33	
34	    fn readAt(ctx: *anyopaque, offset: u64, buf: []u8) SeekableReader.Error!usize {
35	        const self: *FileReader = @ptrCast(@alignCast(ctx));
36	        return self.file.readPositionalAll(self.io, buf, offset) catch return error.InputOutput;
37	    }
38	
39	    fn getSize(ctx: *anyopaque) u64 {
40	        const self: *FileReader = @ptrCast(@alignCast(ctx));
41	        return self.file_size;
42	    }
43	};
44

1	//! Shared Parquet reading utilities
2	//!
3	//! Common code for parsing Parquet file structure using SeekableReader.
4	//! This eliminates code duplication across Reader, DynamicReader, and RowReader.
5	
6	const std = @import("std");
7	const safe = @import("safe.zig");
8	const seekable_reader = @import("seekable_reader.zig");
9	const format = @import("format.zig");
10	const thrift = @import("thrift/mod.zig");
11	const types = @import("types.zig");
12	
13	pub const SeekableReader = seekable_reader.SeekableReader;
14	pub const ReaderError = types.ReaderError;
15	
16	/// Cleanup callback for owned backends (e.g., heap-allocated FileReader/BufferReader).
17	/// Set by convenience constructors in api/zig/. Core code does not create these.
18	pub const BackendCleanup = struct {
19	    ptr: *anyopaque,
20	    deinit_fn: *const fn (*anyopaque, std.mem.Allocator) void,
21	};
22	
23	/// Options for controlling page checksum validation.
24	pub const ChecksumOptions = struct {
25	    /// Whether to validate page CRC32 checksums when reading.
26	    /// Default: false (for performance; checksums verified on-demand)
27	    validate_page_checksum: bool = false,
28	
29	    /// If true, return error when a page has no CRC checksum.
30	    /// Only applies when validate_page_checksum is true.
31	    /// Default: false (allow pages without checksums)
32	    strict_checksum: bool = false,
33	};
34	
35	/// Allocation limits for reading untrusted Parquet files.
36	///
37	/// These limits help prevent denial-of-service attacks where a malicious
38	/// Parquet file could cause excessive memory allocation.
39	pub const AllocationLimits = struct {
40	    /// Maximum dictionary size in bytes (default: 64MB)
41	    max_dictionary_size: usize = 64 * 1024 * 1024,
42	
43	    /// Maximum page size in bytes (default: 128MB)
44	    max_page_size: usize = 128 * 1024 * 1024,
45	
46	    /// Maximum string length in bytes (default: 16MB)
47	    max_string_length: usize = 16 * 1024 * 1024,
48	
49	    /// Check if a dictionary size is within limits
50	    pub fn checkDictionarySize(self: AllocationLimits, size: usize) ReaderError!void {
51	        if (size > self.max_dictionary_size) return error.AllocationLimitExceeded;
52	    }
53	
54	    /// Check if a page size is within limits
55	    pub fn checkPageSize(self: AllocationLimits, size: usize) ReaderError!void {
56	        if (size > self.max_page_size) return error.AllocationLimitExceeded;
57	    }
58	
59	    /// Check if a string length is within limits
60	    pub fn checkStringLength(self: AllocationLimits, length: usize) ReaderError!void {
61	        if (length > self.max_string_length) return error.AllocationLimitExceeded;
62	    }
63	
64	    /// Default limits (generous for most use cases)
65	    pub const default = AllocationLimits{};
66	
67	    /// No limits (for trusted input only)
68	    pub const unlimited = AllocationLimits{
69	        .max_dictionary_size = std.math.maxInt(usize),
70	        .max_page_size = std.math.maxInt(usize),
71	        .max_string_length = std.math.maxInt(usize),
72	    };
73	};
74	
75	
76	/// Result of parsing a Parquet file footer
77	pub const FooterInfo = struct {
78	    metadata: format.FileMetaData,
79	    footer_data: []u8, // Caller must free with allocator
80	};
81	
82	/// Parse Parquet file footer from a SeekableReader.
83	///
84	/// This validates the magic bytes, reads the footer, and parses the Thrift-encoded
85	/// FileMetaData. The caller owns the returned footer_data and must free it.
86	///
87	/// This is the shared implementation used by Reader, DynamicReader, and RowReader.
88	pub fn parseFooter(allocator: std.mem.Allocator, source: SeekableReader) ReaderError!FooterInfo {
89	    const file_size = source.size();
90	    if (file_size < 12) return error.FileTooSmall; // 4 (magic) + 4 (footer size) + 4 (magic)
91	
92	    // Read the last 8 bytes to get footer size and validate trailing magic
93	    var tail: [8]u8 = undefined;
94	    const tail_read = source.readAt(file_size - 8, &tail) catch return error.InputOutput;
95	    if (tail_read != 8) return error.InputOutput;
96	
97	    // Validate trailing magic
98	    if (!std.mem.eql(u8, tail[4..8], format.PARQUET_MAGIC)) {
99	        return error.InvalidMagic;
100	    }
101	
102	    // Get footer size
103	    const footer_size = std.mem.readInt(u32, tail[0..4], .little);
104	    if (footer_size > file_size - 8) return error.FooterTooLarge;
105	
106	    // Read footer data
107	    const footer_data = allocator.alloc(u8, footer_size) catch return error.OutOfMemory;
108	    errdefer allocator.free(footer_data);
109	
110	    const footer_read = source.readAt(file_size - 8 - footer_size, footer_data) catch return error.InputOutput;
111	    if (footer_read != footer_size) return error.InputOutput;
112	
113	    // Validate leading magic
114	    var head: [4]u8 = undefined;
115	    const head_read = source.readAt(0, &head) catch return error.InputOutput;
116	    if (head_read != 4) return error.InputOutput;
117	    if (!std.mem.eql(u8, &head, format.PARQUET_MAGIC)) {
118	        return error.InvalidMagic;
119	    }
120	
121	    // Parse the Thrift-encoded metadata
122	    var thrift_reader = thrift.CompactReader.init(footer_data);
123	    const metadata = format.FileMetaData.parse(allocator, &thrift_reader) catch |e| {
124	        return e;
125	    };
126	
127	    return .{
128	        .metadata = metadata,
129	        .footer_data = footer_data,
130	    };
131	}
132	
133	/// Read raw page data for a column chunk from a SeekableReader.
134	///
135	/// This reads the entire column chunk (including dictionary page if present)
136	/// into a newly allocated buffer. The caller owns the returned data.
137	/// Size is bounded by total_compressed_size from the column metadata and the file size;
138	/// per-page allocation limits are applied when decoding individual pages.
139	pub fn readColumnChunkData(
140	    allocator: std.mem.Allocator,
141	    source: SeekableReader,
142	    chunk: *const format.ColumnChunk,
143	) ReaderError![]u8 {
144	    const meta = chunk.meta_data orelse return error.InvalidArgument;
145	
146	    // Determine where to start reading
147	    // Note: Some writers set dictionary_page_offset=0 to mean "no dictionary"
148	    // (0 is invalid as it's before the PAR1 magic bytes)
149	    const start_offset: u64 = if (meta.dictionary_page_offset) |dict_off|
150	        if (dict_off > 0) try safe.cast(dict_off) else try safe.cast(meta.data_page_offset)
151	    else
152	        try safe.cast(meta.data_page_offset);
153	
154	    const size = try safe.cast(meta.total_compressed_size);
155	
156	    // Read the data
157	    const data = allocator.alloc(u8, size) catch return error.OutOfMemory;
158	    errdefer allocator.free(data);
159	
160	    const bytes_read = source.readAt(start_offset, data) catch return error.InputOutput;
161	    if (bytes_read != size) return error.InputOutput;
162	
163	    return data;
164	}
165	
166	// ============================================================================
167	// Page Header Helpers
168	// ============================================================================
169	
170	/// Free the allocated contents within a PageHeader (statistics min/max values).
171	///
172	/// This does NOT free the PageHeader struct itself - only the heap-allocated
173	/// fields inside it (Statistics.min, max, min_value, max_value).
174	/// Call this on every PageHeader returned by PageIterator.next().
175	pub fn freePageHeaderContents(allocator: std.mem.Allocator, header: *const format.PageHeader) void {
176	    if (header.data_page_header) |dph| {
177	        if (dph.statistics) |stats| {
178	            freeStatistics(allocator, &stats);
179	        }
180	    }
181	    if (header.data_page_header_v2) |v2| {
182	        if (v2.statistics) |stats| {
183	            freeStatistics(allocator, &stats);
184	        }
185	    }
186	}
187	
188	/// Free Statistics allocated memory
189	fn freeStatistics(allocator: std.mem.Allocator, stats: *const format.Statistics) void {
190	    if (stats.max) |m| allocator.free(m);
191	    if (stats.min) |m| allocator.free(m);
192	    if (stats.max_value) |m| allocator.free(m);
193	    if (stats.min_value) |m| allocator.free(m);
194	}
195	
196	/// Result of parsing a page header
197	pub const PageInfo = struct {
198	    /// The parsed page header (caller must free with freePageHeaderContents)
199	    header: format.PageHeader,
200	    /// The compressed page body data (slice into page_data)
201	    body: []const u8,
202	    /// Position after this page in the source data
203	    next_pos: usize,
204	    /// Whether this is a dictionary page
205	    is_dictionary: bool,
206	    /// Whether this is a data page (V1 or V2)
207	    is_data_page: bool,
208	};
209	
210	/// Iterator for parsing pages from a column chunk's raw data.
211	///
212	/// This handles the common logic of parsing page headers and extracting
213	/// page bodies, abstracting away the Thrift parsing and position tracking.
214	pub const PageIterator = struct {
215	    page_data: []const u8,
216	    pos: usize,
217	    allocator: std.mem.Allocator,
218	    checksum_options: ChecksumOptions,
219	
220	    const Self = @This();
221	    const crc = std.hash.crc;
222	
223	    /// Compute CRC32 checksum for page data (per Parquet spec, covers compressed data)
224	    fn computePageCrc(data: []const u8) i32 {
225	        return @bitCast(crc.Crc32.hash(data));
226	    }
227	
228	    /// Initialize a page iterator
229	    pub fn init(allocator: std.mem.Allocator, page_data: []const u8) Self {
230	        return .{
231	            .page_data = page_data,
232	            .pos = 0,
233	            .allocator = allocator,
234	            .checksum_options = .{}, // Default: no validation
235	        };
236	    }
237	
238	    /// Initialize a page iterator with checksum options
239	    pub fn initWithOptions(allocator: std.mem.Allocator, page_data: []const u8, checksum_options: ChecksumOptions) Self {
240	        return .{
241	            .page_data = page_data,
242	            .pos = 0,
243	            .allocator = allocator,
244	            .checksum_options = checksum_options,
245	        };
246	    }
247	
248	    /// Get the next page, or null if no more pages.
249	    /// Caller must call freePageHeaderContents on the returned header when done.
250	    pub fn next(self: *Self) ReaderError!?PageInfo {
251	        if (self.pos >= self.page_data.len) {
252	            return null;
253	        }
254	
255	        // Parse page header using Thrift
256	        var thrift_reader = thrift.CompactReader.init(self.page_data[self.pos..]);
257	        const header = format.PageHeader.parse(self.allocator, &thrift_reader) catch |e| {
258	            return e;
259	        };
260	        errdefer freePageHeaderContents(self.allocator, &header);
261	
262	        const header_end = std.math.add(usize, self.pos, thrift_reader.pos) catch return error.IntegerOverflow;
263	
264	        // Get the compressed body
265	        const compressed_size = safe.cast(header.compressed_page_size) catch return error.IntegerOverflow;
266	        if (header_end + compressed_size > self.page_data.len) {
267	            freePageHeaderContents(self.allocator, &header);
268	            return error.InvalidPageData;
269	        }
270	
271	        const body = try safe.slice(self.page_data, header_end, compressed_size);
272	        const next_pos = header_end + compressed_size;
273	
274	        // Validate CRC32 checksum if enabled
275	        if (self.checksum_options.validate_page_checksum) {
276	            if (header.crc) |expected_crc| {
277	                const actual_crc = computePageCrc(body);
278	                if (actual_crc != expected_crc) {
279	                    freePageHeaderContents(self.allocator, &header);
280	                    return error.PageChecksumMismatch;
281	                }
282	            } else if (self.checksum_options.strict_checksum) {
283	                freePageHeaderContents(self.allocator, &header);
284	                return error.MissingPageChecksum;
285	            }
286	        }
287	
288	        // Determine page type
289	        const is_dictionary = header.dictionary_page_header != null;
290	        const is_data_page = header.data_page_header != null or header.data_page_header_v2 != null;
291	
292	        // Advance position
293	        self.pos = next_pos;
294	
295	        return .{
296	            .header = header,
297	            .body = body,
298	            .next_pos = next_pos,
299	            .is_dictionary = is_dictionary,
300	            .is_data_page = is_data_page,
301	        };
302	    }
303	
304	    /// Skip a page without returning it (useful for skipping dictionary pages already processed)
305	    pub fn skip(self: *Self) ReaderError!bool {
306	        const page_info = try self.next();
307	        if (page_info) |info| {
308	            freePageHeaderContents(self.allocator, &info.header);
309	            return true;
310	        }
311	        return false;
312	    }
313	
314	    /// Peek at the next page header without consuming it.
315	    /// Caller must call freePageHeaderContents on the returned header when done.
316	    pub fn peek(self: *Self) ReaderError!?format.PageHeader {
317	        if (self.pos >= self.page_data.len) {
318	            return null;
319	        }
320	
321	        var thrift_reader = thrift.CompactReader.init(self.page_data[self.pos..]);
322	        const header = format.PageHeader.parse(self.allocator, &thrift_reader) catch |e| {
323	            return e;
324	        };
325	
326	        return header;
327	    }
328	
329	    /// Check if there are more pages
330	    pub fn hasMore(self: *Self) bool {
331	        return self.pos < self.page_data.len;
332	    }
333	};
