405	/// Decode a column with OPTIONAL repetition (has definition levels)
406	/// Legacy version that discards levels.
407	fn decodeOptionalColumn(
408	    comptime T: type,
409	    ctx: DecodeContext,
410	    value_data: []const u8,
411	    result: []Optional(T),
412	    is_fixed_len: bool,
413	    fixed_len: usize,
414	) !void {
415	    const levels = try decodeOptionalColumnWithLevels(T, ctx, value_data, result, is_fixed_len, fixed_len);
416	    // Discard levels in legacy mode
417	    if (levels.def_levels) |dl| ctx.allocator.free(dl);
418	    if (levels.rep_levels) |rl| ctx.allocator.free(rl);
419	}
