640	/// Decode PLAIN-encoded values with definition levels
641	fn decodePlainWithDefLevels(
642	    comptime T: type,
643	    ctx: DecodeContext,
644	    value_data: []const u8,
645	    values_start: usize,
646	    def_levels: []const bool,
647	    result: []Optional(T),
648	    is_fixed_len: bool,
649	    fixed_len: usize,
650	) !void {
651	    var value_pos: usize = 0;
652	    var data_offset: usize = values_start;
653	
654	    for (0..ctx.num_values) |i| {
655	        if (def_levels[i]) {
656	            // Value is present
657	            if (T == bool) {
658	                // Booleans are bit-packed: use value_pos as cumulative bit index
659	                // decodeBool handles the byte/bit offset calculation internally
660	                result[i] = .{ .value = try plain.decodeBool(value_data[values_start..], value_pos) };
661	                value_pos += 1;
662	            } else if (T == i32) {
663	                if (data_offset + 4 > value_data.len) return error.EndOfData;
664	                result[i] = .{ .value = try plain.decodeI32(value_data[data_offset..]) };
665	                data_offset += 4;
666	            } else if (T == i64) {
667	                if (data_offset + 8 > value_data.len) return error.EndOfData;
668	                result[i] = .{ .value = try plain.decodeI64(value_data[data_offset..]) };
669	                data_offset += 8;
670	            } else if (T == f32) {
671	                if (data_offset + 4 > value_data.len) return error.EndOfData;
672	                result[i] = .{ .value = try plain.decodeFloat(value_data[data_offset..]) };
673	                data_offset += 4;
674	            } else if (T == f64) {
675	                if (data_offset + 8 > value_data.len) return error.EndOfData;
676	                result[i] = .{ .value = try plain.decodeDouble(value_data[data_offset..]) };
677	                data_offset += 8;
678	            } else if (T == f16) {
679	                // Float16: 2 bytes, IEEE 754 half-precision (stored as FIXED_LEN_BYTE_ARRAY(2))
680	                if (data_offset + 2 > value_data.len) return error.EndOfData;
681	                const bytes: [2]u8 = .{ value_data[data_offset], value_data[data_offset + 1] };
682	                result[i] = .{ .value = @bitCast(bytes) };
683	                data_offset += 2;
684	            } else if (T == []const u8) {
685	                if (is_fixed_len) {
686	                    // Fixed-length byte array - no length prefix
687	                    if (data_offset + fixed_len > value_data.len) return error.EndOfData;
688	                    const value = value_data[data_offset..][0..fixed_len];
689	                    result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, value) };
690	                    data_offset += fixed_len;
691	                } else if (isDecimalIntColumn(ctx)) {
692	                    // Decimal stored as INT32/INT64: read integer bytes, convert to big-endian
693	                    const int_size: usize = if (ctx.schema_elem.type_ == .int32) 4 else 8;
694	                    result[i] = .{ .value = try decodeDecimalInt(ctx.allocator, value_data, data_offset, int_size) };
695	                    data_offset += int_size;
696	                } else {
697	                    // Variable-length byte array - has 4-byte length prefix
698	                    if (data_offset + 4 > value_data.len) return error.EndOfData;
699	                    const ba = try plain.decodeByteArray(value_data[data_offset..]);
700	                    if (data_offset + ba.bytes_read > value_data.len) return error.EndOfData;
701	                    result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, ba.value) };
702	                    data_offset += ba.bytes_read;
703	                }
704	            } else if (T == Int96) {
705	                if (data_offset + 12 > value_data.len) return error.EndOfData;
706	                result[i] = .{ .value = Int96.fromBytes(value_data[data_offset..][0..12].*) };
707	                data_offset += 12;
708	            }
709	        } else {
710	            result[i] = .{ .null_value = {} };
711	        }
712	    }
713	}
