950	/// Decode column values dynamically with explicit level and value encodings
951	pub fn decodeColumnDynamicWithValueEncoding(
952	    allocator: std.mem.Allocator,
953	    schema_elem: format.SchemaElement,
954	    value_data: []const u8,
955	    num_values: usize,
956	    max_def_level: u8,
957	    max_rep_level: u8,
958	    uses_dict: bool,
959	    string_dict: ?*dictionary.StringDictionary,
960	    int32_dict: ?*dictionary.Int32Dictionary,
961	    int64_dict: ?*dictionary.Int64Dictionary,
962	    float32_dict: ?*dictionary.Float32Dictionary,
963	    float64_dict: ?*dictionary.Float64Dictionary,
964	    fixed_byte_array_dict: ?*dictionary.FixedByteArrayDictionary,
965	    int96_dict: ?*dictionary.Int96Dictionary,
966	    def_level_encoding: format.Encoding,
967	    rep_level_encoding: format.Encoding,
968	    value_encoding: format.Encoding,
969	) !DynamicDecodeResult {
970	    const physical_type = schema_elem.type_ orelse return error.InvalidArgument;
971	
972	    // Check for delta encodings and dispatch to specialized decoders
973	    switch (value_encoding) {
974	        .delta_binary_packed => {
975	            return decodeDeltaBinaryPacked(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, def_level_encoding, rep_level_encoding);
976	        },
977	        .delta_length_byte_array => {
978	            return decodeDeltaLengthByteArray(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, def_level_encoding, rep_level_encoding);
979	        },
980	        .delta_byte_array => {
981	            return decodeDeltaByteArray(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, def_level_encoding, rep_level_encoding);
982	        },
983	        .byte_stream_split => {
984	            return decodeByteStreamSplit(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, def_level_encoding, rep_level_encoding);
985	        },
986	        .rle => {
987	            if (physical_type == .boolean) {
988	                return decodeDynamicBoolRLE(allocator, value_data, num_values, max_def_level, max_rep_level, def_level_encoding, rep_level_encoding);
989	            }
990	            return error.UnsupportedEncoding;
991	        },
992	        .plain, .rle_dictionary, .plain_dictionary => {},
993	        else => return error.UnsupportedEncoding,
994	    }
995	
996	    // Standard PLAIN/dictionary encoding path
997	    // Only use dictionary decoding if the encoding is actually dictionary-based
998	    const is_dict_encoded = uses_dict and
999	        (value_encoding == .rle_dictionary or value_encoding == .plain_dictionary);
1000	
1001	    return switch (physical_type) {
1002	        .boolean => decodeDynamicBool(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, def_level_encoding, rep_level_encoding),
1003	        .int32 => decodeDynamicInt32(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, is_dict_encoded, int32_dict, def_level_encoding, rep_level_encoding),
1004	        .int64 => decodeDynamicInt64(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, is_dict_encoded, int64_dict, def_level_encoding, rep_level_encoding),
1005	        .float => decodeDynamicFloat(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, is_dict_encoded, float32_dict, def_level_encoding, rep_level_encoding),
1006	        .double => decodeDynamicDouble(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, is_dict_encoded, float64_dict, def_level_encoding, rep_level_encoding),
1007	        .byte_array => decodeDynamicByteArray(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, is_dict_encoded, string_dict, def_level_encoding, rep_level_encoding),
1008	        .fixed_len_byte_array => decodeDynamicFixedByteArray(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, is_dict_encoded, fixed_byte_array_dict, def_level_encoding, rep_level_encoding),
1009	        .int96 => decodeDynamicInt96(allocator, schema_elem, value_data, num_values, max_def_level, max_rep_level, is_dict_encoded, int96_dict, def_level_encoding, rep_level_encoding),
1010	    };
1011	}
