1133	// Delta encoding decoder for V2 pages
1134	fn decodeDeltaEncodedValuesV2(
1135	    allocator: std.mem.Allocator,
1136	    physical_type: format.PhysicalType,
1137	    values_data: []const u8,
1138	    num_values: usize,
1139	    def_mask: []const bool,
1140	    non_null_count: usize,
1141	    value_encoding: format.Encoding,
1142	) ![]Value {
1143	    const values = try allocator.alloc(Value, num_values);
1144	    errdefer allocator.free(values);
1145	
1146	    switch (value_encoding) {
1147	        .delta_binary_packed => {
1148	            // Decode all non-null values
1149	            switch (physical_type) {
1150	                .int32 => {
1151	                    const decoded = try delta_binary_packed.decodeInt32(allocator, values_data);
1152	                    defer allocator.free(decoded);
1153	
1154	                    var decoded_idx: usize = 0;
1155	                    for (0..num_values) |i| {
1156	                        if (def_mask[i]) {
1157	                            if (decoded_idx < decoded.len) {
1158	                                values[i] = .{ .int32_val = decoded[decoded_idx] };
1159	                                decoded_idx += 1;
1160	                            } else {
1161	                                values[i] = .{ .null_val = {} };
1162	                            }
1163	                        } else {
1164	                            values[i] = .{ .null_val = {} };
1165	                        }
1166	                    }
1167	                },
1168	                .int64 => {
1169	                    const decoded = try delta_binary_packed.decodeInt64(allocator, values_data);
1170	                    defer allocator.free(decoded);
1171	
1172	                    var decoded_idx: usize = 0;
1173	                    for (0..num_values) |i| {
1174	                        if (def_mask[i]) {
1175	                            if (decoded_idx < decoded.len) {
1176	                                values[i] = .{ .int64_val = decoded[decoded_idx] };
1177	                                decoded_idx += 1;
1178	                            } else {
1179	                                values[i] = .{ .null_val = {} };
1180	                            }
1181	                        } else {
1182	                            values[i] = .{ .null_val = {} };
1183	                        }
1184	                    }
1185	                },
1186	                else => return error.UnsupportedEncoding,
1187	            }
1188	        },
1189	        .delta_length_byte_array => {
1190	            var result = try delta_length_byte_array.decode(allocator, values_data);
1191	            defer result.deinit();
1192	
1193	            var decoded_idx: usize = 0;
1194	            for (0..num_values) |i| {
1195	                if (def_mask[i]) {
1196	                    if (decoded_idx < result.values.len) {
1197	                        values[i] = .{ .bytes_val = try value_mod.dupeBytes(allocator, result.values[decoded_idx]) };
1198	                        decoded_idx += 1;
1199	                    } else {
1200	                        values[i] = .{ .null_val = {} };
1201	                    }
1202	                } else {
1203	                    values[i] = .{ .null_val = {} };
1204	                }
1205	            }
1206	        },
1207	        .delta_byte_array => {
1208	            var result = try delta_byte_array.decode(allocator, values_data);
1209	            defer result.deinit();
1210	
1211	            var decoded_idx: usize = 0;
1212	            for (0..num_values) |i| {
1213	                if (def_mask[i]) {
1214	                    if (decoded_idx < result.values.len) {
1215	                        values[i] = .{ .bytes_val = try value_mod.dupeBytes(allocator, result.values[decoded_idx]) };
1216	                        decoded_idx += 1;
1217	                    } else {
1218	                        values[i] = .{ .null_val = {} };
1219	                    }
1220	                } else {
1221	                    values[i] = .{ .null_val = {} };
1222	                }
1223	            }
1224	        },
1225	        .byte_stream_split => {
1226	            switch (physical_type) {
1227	                .float => {
1228	                    const decoded = try allocator.alloc(f32, non_null_count);
1229	                    defer allocator.free(decoded);
1230	                    try byte_stream_split.decodeFloat32Into(values_data, decoded);
1231	
1232	                    var decoded_idx: usize = 0;
1233	                    for (0..num_values) |i| {
1234	                        if (def_mask[i]) {
1235	                            if (decoded_idx < decoded.len) {
1236	                                values[i] = .{ .float_val = decoded[decoded_idx] };
1237	                                decoded_idx += 1;
1238	                            } else {
1239	                                values[i] = .{ .null_val = {} };
1240	                            }
1241	                        } else {
1242	                            values[i] = .{ .null_val = {} };
1243	                        }
1244	                    }
1245	                },
1246	                .double => {
1247	                    const decoded = try allocator.alloc(f64, non_null_count);
1248	                    defer allocator.free(decoded);
1249	                    try byte_stream_split.decodeFloat64Into(values_data, decoded);
1250	
1251	                    var decoded_idx: usize = 0;
1252	                    for (0..num_values) |i| {
1253	                        if (def_mask[i]) {
1254	                            if (decoded_idx < decoded.len) {
1255	                                values[i] = .{ .double_val = decoded[decoded_idx] };
1256	                                decoded_idx += 1;
1257	                            } else {
1258	                                values[i] = .{ .null_val = {} };
1259	                            }
1260	                        } else {
1261	                            values[i] = .{ .null_val = {} };
1262	                        }
1263	                    }
1264	                },
1265	                .int32 => {
1266	                    const decoded = try allocator.alloc(i32, non_null_count);
1267	                    defer allocator.free(decoded);
1268	                    try byte_stream_split.decodeInt32Into(values_data, decoded);
1269	
1270	                    var decoded_idx: usize = 0;
1271	                    for (0..num_values) |i| {
