1318	    // Handle empty case - all nulls
1319	    if (non_null_count == 0 or values_data.len == 0) {
1320	        for (0..num_values) |i| {
1321	            values[i] = .{ .null_val = {} };
1322	        }
1323	        return values;
1324	    }
1325	
1326	    // Validate data size: non_null_count booleans need (non_null_count + 7) / 8 bytes
1327	    const required_bytes = (non_null_count + 7) / 8;
1328	    if (values_data.len < required_bytes) {
1329	        return error.EndOfData;
1330	    }
1331	
1332	    // Decode packed booleans - each boolean is 1 bit, 8 per byte
1333	    var value_pos: usize = 0;
1334	
1335	    for (0..num_values) |i| {
1336	        if (def_mask[i]) {
1337	            // value_pos is the index of the non-null value
1338	            // decodeBool uses value_pos to compute byte_idx = value_pos / 8 and bit_idx = value_pos % 8
1339	            values[i] = .{ .bool_val = try plain.decodeBool(values_data, value_pos) };
1340	            value_pos += 1;
1341	        } else {
1342	            values[i] = .{ .null_val = {} };
1343	        }
1344	    }
1345	    return values;
1346	}
