20	    /// Get a SeekableReader interface for this file.
21	    /// The FileReader must outlive the returned SeekableReader.
22	    pub fn reader(self: *FileReader) SeekableReader {
23	        return .{
24	            .ptr = self,
25	            .vtable = &vtable,
26	        };
27	    }
