133	/// Read raw page data for a column chunk from a SeekableReader.
134	///
135	/// This reads the entire column chunk (including dictionary page if present)
136	/// into a newly allocated buffer. The caller owns the returned data.
137	/// Size is bounded by total_compressed_size from the column metadata and the file size;
138	/// per-page allocation limits are applied when decoding individual pages.
139	pub fn readColumnChunkData(
140	    allocator: std.mem.Allocator,
141	    source: SeekableReader,
142	    chunk: *const format.ColumnChunk,
143	) ReaderError![]u8 {
144	    const meta = chunk.meta_data orelse return error.InvalidArgument;
145	
146	    // Determine where to start reading
147	    // Note: Some writers set dictionary_page_offset=0 to mean "no dictionary"
148	    // (0 is invalid as it's before the PAR1 magic bytes)
149	    const start_offset: u64 = if (meta.dictionary_page_offset) |dict_off|
150	        if (dict_off > 0) try safe.cast(dict_off) else try safe.cast(meta.data_page_offset)
151	    else
152	        try safe.cast(meta.data_page_offset);
153	
154	    const size = try safe.cast(meta.total_compressed_size);
155	
156	    // Read the data
157	    const data = allocator.alloc(u8, size) catch return error.OutOfMemory;
158	    errdefer allocator.free(data);
159	
160	    const bytes_read = source.readAt(start_offset, data) catch return error.InputOutput;
161	    if (bytes_read != size) return error.InputOutput;
162	
163	    return data;
164	}
