214	pub const PageIterator = struct {
215	    page_data: []const u8,
216	    pos: usize,
217	    allocator: std.mem.Allocator,
218	    checksum_options: ChecksumOptions,
219	
220	    const Self = @This();
221	    const crc = std.hash.crc;
222	
223	    /// Compute CRC32 checksum for page data (per Parquet spec, covers compressed data)
224	    fn computePageCrc(data: []const u8) i32 {
225	        return @bitCast(crc.Crc32.hash(data));
226	    }
227	
228	    /// Initialize a page iterator
229	    pub fn init(allocator: std.mem.Allocator, page_data: []const u8) Self {
230	        return .{
231	            .page_data = page_data,
232	            .pos = 0,
233	            .allocator = allocator,
234	            .checksum_options = .{}, // Default: no validation
235	        };
236	    }
