238	    /// Initialize a page iterator with checksum options
239	    pub fn initWithOptions(allocator: std.mem.Allocator, page_data: []const u8, checksum_options: ChecksumOptions) Self {
240	        return .{
241	            .page_data = page_data,
242	            .pos = 0,
243	            .allocator = allocator,
244	            .checksum_options = checksum_options,
245	        };
246	    }
