336	// Dictionary Helpers
337	// ============================================================================
338	
339	const dictionary = @import("encoding/dictionary.zig");
340	const compress = @import("compress/mod.zig");
341	
342	/// Container for all dictionary types that might be used when decoding a column.
343	/// This eliminates the need to declare 3-4 separate dictionary variables in each
344	/// column reading function.
345	pub const DictionarySet = struct {
346	    string_dict: ?dictionary.StringDictionary = null,
347	    int32_dict: ?dictionary.Int32Dictionary = null,
348	    int64_dict: ?dictionary.Int64Dictionary = null,
349	    float32_dict: ?dictionary.Float32Dictionary = null,
350	    float64_dict: ?dictionary.Float64Dictionary = null,
351	    int96_dict: ?dictionary.Int96Dictionary = null,
352	    fixed_byte_array_dict: ?dictionary.FixedByteArrayDictionary = null,
353	    allocator: std.mem.Allocator,
354	
355	    const Self = @This();
356	
357	    /// Initialize an empty dictionary set
358	    pub fn init(allocator: std.mem.Allocator) Self {
359	        return .{ .allocator = allocator };
360	    }
361	
362	    /// Check if any dictionary is present
363	    pub fn hasDictionary(self: *const Self) bool {
364	        return self.string_dict != null or
365	            self.int32_dict != null or
366	            self.int64_dict != null or
367	            self.float32_dict != null or
368	            self.float64_dict != null or
369	            self.int96_dict != null or
370	            self.fixed_byte_array_dict != null;
371	    }
372	
373	    /// Initialize dictionaries from a dictionary page.
374	    /// This parses the dictionary page and builds the appropriate dictionary
375	    /// based on the physical type.
376	    pub fn initFromPage(
377	        self: *Self,
378	        dict_page_body: []const u8,
379	        num_values: usize,
380	        physical_type: ?format.PhysicalType,
381	        type_length: ?i32,
382	        codec: format.CompressionCodec,
383	        uncompressed_size: usize,
384	    ) ReaderError!void {
385	        return self.initFromPageWithLimits(dict_page_body, num_values, physical_type, type_length, codec, uncompressed_size, null);
386	    }
387	
388	    /// Initialize dictionaries from a dictionary page with allocation limits.
389	    /// This parses the dictionary page and builds the appropriate dictionary
390	    /// based on the physical type.
391	    pub fn initFromPageWithLimits(
392	        self: *Self,
393	        dict_page_body: []const u8,
394	        num_values: usize,
395	        physical_type: ?format.PhysicalType,
396	        type_length: ?i32,
397	        codec: format.CompressionCodec,
398	        uncompressed_size: usize,
399	        limits: ?AllocationLimits,
400	    ) ReaderError!void {
401	        // Check allocation limits
402	        if (limits) |lim| {
403	            try lim.checkDictionarySize(uncompressed_size);
404	        }
405	
406	        // Decompress dictionary page if needed
407	        const dict_data = if (codec != .uncompressed) blk: {
408	            break :blk decompressData(self.allocator, dict_page_body, codec, uncompressed_size) catch
409	                return error.DecompressionError;
410	        } else dict_page_body;
411	        defer if (codec != .uncompressed) self.allocator.free(dict_data);
412	
413	        // Build appropriate dictionary based on physical type.
414	        // Guard against re-initialization which would leak the existing dictionary.
415	        if (physical_type) |pt| {
416	            switch (pt) {
417	                .byte_array => {
418	                    if (self.string_dict != null) return error.InvalidPageData;
419	                    self.string_dict = dictionary.StringDictionary.fromPlain(
420	                        self.allocator,
421	                        dict_data,
422	                        num_values,
423	                    ) catch return error.OutOfMemory;
424	                },
425	                .fixed_len_byte_array => {
426	                    // type_length == 0 is valid but meaningless for FLBA; skip silently
427	                    const fixed_len = safe.cast(type_length orelse 0) catch return error.IntegerOverflow;
428	                    if (fixed_len > 0) {
429	                        if (self.fixed_byte_array_dict != null) return error.InvalidPageData;
430	                        self.fixed_byte_array_dict = dictionary.FixedByteArrayDictionary.fromPlain(
431	                            self.allocator,
432	                            dict_data,
433	                            num_values,
434	                            fixed_len,
435	                        ) catch return error.OutOfMemory;
436	                    }
437	                },
438	                .int32 => {
439	                    if (self.int32_dict != null) return error.InvalidPageData;
440	                    self.int32_dict = dictionary.Int32Dictionary.fromPlain(
441	                        self.allocator,
442	                        dict_data,
443	                        num_values,
444	                    ) catch return error.OutOfMemory;
445	                },
446	                .int64 => {
447	                    if (self.int64_dict != null) return error.InvalidPageData;
448	                    self.int64_dict = dictionary.Int64Dictionary.fromPlain(
449	                        self.allocator,
450	                        dict_data,
451	                        num_values,
452	                    ) catch return error.OutOfMemory;
453	                },
454	                .float => {
455	                    if (self.float32_dict != null) return error.InvalidPageData;
456	                    self.float32_dict = dictionary.Float32Dictionary.fromPlain(
457	                        self.allocator,
458	                        dict_data,
459	                        num_values,
460	                    ) catch return error.OutOfMemory;
461	                },
462	                .double => {
463	                    if (self.float64_dict != null) return error.InvalidPageData;
464	                    self.float64_dict = dictionary.Float64Dictionary.fromPlain(
465	                        self.allocator,
466	                        dict_data,
467	                        num_values,
468	                    ) catch return error.OutOfMemory;
469	                },
470	                .int96 => {
471	                    self.int96_dict = dictionary.Int96Dictionary.fromPlain(
472	                        self.allocator,
473	                        dict_data,
474	                        num_values,
475	                    ) catch return error.OutOfMemory;
476	                },
477	                else => {},
478	            }
479	        }
480	    }
481	
482	    /// Free all dictionaries
483	    pub fn deinit(self: *Self) void {
484	        if (self.string_dict) |*d| d.deinit();
485	        if (self.int32_dict) |*d| d.deinit();
486	        if (self.int64_dict) |*d| d.deinit();
487	        if (self.float32_dict) |*d| d.deinit();
488	        if (self.float64_dict) |*d| d.deinit();
489	        if (self.int96_dict) |*d| d.deinit();
490	        if (self.fixed_byte_array_dict) |*d| d.deinit();
491	    }
492	};
493	
494	/// Decompress data using the specified codec
495	fn decompressData(
496	    allocator: std.mem.Allocator,
497	    compressed: []const u8,
498	    codec: format.CompressionCodec,
499	    uncompressed_size: usize,
500	) ![]u8 {
501	    if (codec == .uncompressed) return error.InvalidCompressionState;
502	    return compress.decompress(allocator, compressed, codec, uncompressed_size);
503	}
