1	//! SeekableReader - vtable-based interface for random-access reading
2	//!
3	//! Enables reading from buffers (WASM, testing) or files with the same API.
4	
5	const std = @import("std");
6	
7	/// Vtable-based interface for random-access reading from any data source.
8	///
9	/// This enables the same reader code to work with in-memory buffers (for WASM/testing)
10	/// or files (for native usage) without code duplication.
11	pub const SeekableReader = struct {
12	    ptr: *anyopaque,
13	    vtable: *const VTable,
14	
15	    pub const VTable = struct {
16	        readAt: *const fn (ctx: *anyopaque, offset: u64, buf: []u8) Error!usize,
17	        size: *const fn (ctx: *anyopaque) u64,
18	    };
19	
20	    pub const Error = error{
21	        InputOutput,
22	        Unseekable,
23	    };
24	
25	    /// Read data starting at the given offset into the buffer.
26	    /// Returns the number of bytes read (may be less than buf.len at end of data).
27	    pub fn readAt(self: SeekableReader, offset: u64, buf: []u8) Error!usize {
28	        return self.vtable.readAt(self.ptr, offset, buf);
29	    }
30	
31	    /// Get the total size of the data source in bytes.
32	    pub fn size(self: SeekableReader) u64 {
33	        return self.vtable.size(self.ptr);
34	    }
35	};
