1	//! Column value decoder
2	//!
3	//! Decodes column values from Parquet page data, handling:
4	//! - Definition levels (for nullable columns)
5	//! - Repetition levels (for repeated/list columns)
6	//! - Dictionary encoding
7	//! - PLAIN encoding
8	//! - Various physical types (bool, i32, i64, f32, f64, byte arrays)
9	
10	const std = @import("std");
11	const safe = @import("safe.zig");
12	const format = @import("format.zig");
13	const plain = @import("encoding/plain.zig");
14	const rle = @import("encoding/rle.zig");
15	const dictionary = @import("encoding/dictionary.zig");
16	const delta_binary_packed = @import("encoding/delta_binary_packed.zig");
17	const delta_length_byte_array = @import("encoding/delta_length_byte_array.zig");
18	const delta_byte_array = @import("encoding/delta_byte_array.zig");
19	const byte_stream_split = @import("encoding/byte_stream_split.zig");
20	const types = @import("types.zig");
21	const value_mod = @import("value.zig");
22	
23	pub const Optional = types.Optional;
24	pub const Int96 = types.Int96;
25	pub const Value = value_mod.Value;
26	
27	/// Extract and validate bit_width from dictionary-encoded data.
28	/// Bit width must be 0-31 to fit in u5 for RLE decoding.
29	fn extractBitWidth(data: []const u8, offset: usize) error{InvalidBitWidth, EndOfData}!u5 {
30	    if (offset >= data.len) return error.EndOfData;
31	    const raw = data[offset];
32	    if (raw > 31) return error.InvalidBitWidth;
33	    return @truncate(raw); // Safe: validated above
34	}
35	
36	/// Safely cast type_length (i32) to usize, validating non-negative.
37	pub fn safeTypeLength(type_length: ?i32) error{InvalidTypeLength}!usize {
38	    const tl = type_length orelse return 0;
39	    return safe.cast(tl) catch return error.InvalidTypeLength;
40	}
41	
42	/// Check if schema indicates a decimal column stored as INT32 or INT64 (not FLBA)
43	fn isDecimalIntColumn(ctx: DecodeContext) bool {
44	    if (ctx.schema_elem.type_ != .int32 and ctx.schema_elem.type_ != .int64) return false;
45	    if (ctx.schema_elem.logical_type) |lt| {
46	        return lt == .decimal;
47	    }
48	    return false;
49	}
50	
51	/// Convert a fixed-size integer (read as little-endian bytes) to big-endian []const u8
52	/// for decimal columns stored as INT32/INT64
53	fn decodeDecimalInt(allocator: std.mem.Allocator, data: []const u8, data_offset: usize, int_size: usize) ![]const u8 {
54	    if (data_offset + int_size > data.len) return error.EndOfData;
55	    const result = try allocator.alloc(u8, int_size);
56	    errdefer allocator.free(result);
57	    // Parquet stores ints as little-endian; decimal expects big-endian two's complement
58	    var j: usize = 0;
59	    while (j < int_size) : (j += 1) {
60	        result[j] = data[data_offset + int_size - 1 - j];
61	    }
62	    return result;
63	}
64	
65	/// Context needed to decode a column
66	pub const DecodeContext = struct {
67	    allocator: std.mem.Allocator,
68	    schema_elem: format.SchemaElement,
69	    num_values: usize,
70	    uses_dict: bool,
71	    string_dict: ?*dictionary.StringDictionary,
72	    int32_dict: ?*dictionary.Int32Dictionary = null,
73	    int64_dict: ?*dictionary.Int64Dictionary = null,
74	    float32_dict: ?*dictionary.Float32Dictionary = null,
75	    float64_dict: ?*dictionary.Float64Dictionary = null,
76	    int96_dict: ?*dictionary.Int96Dictionary = null,
77	    fixed_byte_array_dict: ?*dictionary.FixedByteArrayDictionary = null,
78	    /// Maximum definition level for this column (defaults to 1 for simple optional columns)
79	    max_definition_level: u8 = 1,
80	    /// Maximum repetition level for this column (defaults to 0 for non-repeated columns)
81	    max_repetition_level: u8 = 0,
82	    /// Definition level encoding (defaults to RLE)
83	    def_level_encoding: format.Encoding = .rle,
84	    /// Repetition level encoding (defaults to RLE)
85	    rep_level_encoding: format.Encoding = .rle,
86	    /// Value encoding (defaults to PLAIN)
87	    value_encoding: format.Encoding = .plain,
88	};
89	
90	/// Result of decoding a column - includes values and levels
91	pub fn DecodeResult(comptime T: type) type {
92	    return struct {
93	        values: []Optional(T),
94	        def_levels: ?[]u32,
95	        rep_levels: ?[]u32,
96	
97	        pub fn deinit(self: *@This(), allocator: std.mem.Allocator, is_byte_array: bool) void {
98	            // Free individual byte arrays if applicable
99	            if (is_byte_array) {
100	                for (self.values) |v| {
101	                    switch (v) {
102	                        .value => |s| allocator.free(s),
103	                        .null_value => {},
104	                    }
105	                }
106	            }
107	            allocator.free(self.values);
108	            if (self.def_levels) |dl| allocator.free(dl);
109	            if (self.rep_levels) |rl| allocator.free(rl);
110	        }
111	    };
112	}
113	
114	/// Decode column values from page data, returning values and levels
115	fn decodeColumnWithLevels(
116	    comptime T: type,
117	    ctx: DecodeContext,
118	    value_data: []const u8,
119	) !DecodeResult(T) {
120	    switch (ctx.value_encoding) {
121	        .delta_binary_packed, .delta_length_byte_array, .delta_byte_array, .byte_stream_split => {
122	            return decodeColumnWithLevelsAndDeltaEncoding(T, ctx, value_data);
123	        },
124	        else => {},
125	    }
126	
127	    const is_optional = ctx.schema_elem.repetition_type == .optional;
128	    const is_fixed_len = ctx.schema_elem.type_ == .fixed_len_byte_array;
129	    const fixed_len: usize = if (ctx.schema_elem.type_length) |tl| blk: {
130	        if (tl < 0) return error.InvalidTypeLength;
131	        break :blk safe.cast(tl) catch return error.InvalidTypeLength;
132	    } else 0;
133	
134	    const result = try ctx.allocator.alloc(Optional(T), ctx.num_values);
135	    errdefer ctx.allocator.free(result);
136	
137	    var def_levels: ?[]u32 = null;
138	    var rep_levels: ?[]u32 = null;
139	
140	    if (is_optional or ctx.max_repetition_level > 0) {
141	        const levels = try decodeOptionalColumnWithLevels(T, ctx, value_data, result, is_fixed_len, fixed_len);
142	        def_levels = levels.def_levels;
143	        rep_levels = levels.rep_levels;
144	    } else {
145	        try decodeRequiredColumn(T, ctx, value_data, result, is_fixed_len, fixed_len);
146	    }
147	
148	    return .{
149	        .values = result,
150	        .def_levels = def_levels,
151	        .rep_levels = rep_levels,
152	    };
153	}
154	
155	/// Decode column with delta/BSS encoding, returning values and levels
156	fn decodeColumnWithLevelsAndDeltaEncoding(
157	    comptime T: type,
158	    ctx: DecodeContext,
159	    value_data: []const u8,
160	) anyerror!DecodeResult(T) {
161	    const dynamic_result = try decodeColumnDynamicWithValueEncoding(
162	        ctx.allocator,
163	        ctx.schema_elem,
164	        value_data,
165	        ctx.num_values,
166	        ctx.max_definition_level,
167	        ctx.max_repetition_level,
168	        ctx.uses_dict,
169	        ctx.string_dict,
170	        ctx.int32_dict,
171	        ctx.int64_dict,
172	        ctx.float32_dict,
173	        ctx.float64_dict,
174	        ctx.fixed_byte_array_dict,
175	        ctx.int96_dict,
176	        ctx.def_level_encoding,
177	        ctx.rep_level_encoding,
178	        ctx.value_encoding,
179	    );
180	    defer {
181	        for (dynamic_result.values) |v| {
182	            switch (v) {
183	                .bytes_val => |ba| ctx.allocator.free(ba),
184	                .fixed_bytes_val => |ba| ctx.allocator.free(ba),
185	                else => {},
186	            }
187	        }
188	        ctx.allocator.free(dynamic_result.values);
189	    }
190	    errdefer {
191	        if (dynamic_result.def_levels) |dl| ctx.allocator.free(dl);
192	        if (dynamic_result.rep_levels) |rl| ctx.allocator.free(rl);
193	    }
194	
195	    const result = try ctx.allocator.alloc(Optional(T), ctx.num_values);
196	    errdefer {
197	        if (T == []const u8) {
198	            for (result) |opt| {
199	                switch (opt) {
200	                    .value => |v| ctx.allocator.free(v),
201	                    .null_value => {},
202	                }
203	            }
204	        }
205	        ctx.allocator.free(result);
206	    }
207	    @memset(result, .null_value);
208	
209	    for (dynamic_result.values, 0..) |v, i| {
210	        result[i] = try convertDynamicValue(T, v, ctx.allocator);
211	    }
212	
213	    return .{
214	        .values = result,
215	        .def_levels = dynamic_result.def_levels,
216	        .rep_levels = dynamic_result.rep_levels,
217	    };
218	}
219	
220	/// Convert a dynamic Value to a typed Optional(T)
221	fn convertDynamicValue(comptime T: type, v: Value, allocator: std.mem.Allocator) !Optional(T) {
222	    return switch (v) {
223	        .null_val => .null_value,
224	        .int32_val => |val| blk: {
225	            if (T == i32) {
226	                break :blk Optional(T).from(val);
227	            } else if (T == i64) {
228	                break :blk Optional(T).from(@as(i64, val)); // Widening cast always safe
229	            } else {
230	                break :blk .null_value;
231	            }
232	        },
233	        .int64_val => |val| blk: {
234	            if (T == i64) {
235	                break :blk Optional(T).from(val);
236	            } else if (T == i32) {
237	                // Check if i64 value fits in i32
238	                if (val > std.math.maxInt(i32) or val < std.math.minInt(i32)) {
239	                    break :blk .null_value;
240	                }
241	                break :blk Optional(T).from(@as(i32, @truncate(val))); // Safe: validated above
242	            } else {
243	                break :blk .null_value;
244	            }
245	        },
246	        .float_val => |val| blk: {
247	            if (T == f32) {
248	                break :blk Optional(T).from(val);
249	            } else if (T == f64) {
250	                break :blk Optional(T).from(@as(f64, @floatCast(val)));
251	            } else {
252	                break :blk .null_value;
253	            }
254	        },
255	        .double_val => |val| blk: {
256	            if (T == f64) {
257	                break :blk Optional(T).from(val);
258	            } else if (T == f32) {
259	                break :blk Optional(T).from(@as(f32, @floatCast(val)));
260	            } else {
261	                break :blk .null_value;
262	            }
263	        },
264	        .bytes_val, .fixed_bytes_val => |val| blk: {
265	            if (T == []const u8) {
266	                const dup = try allocator.dupe(u8, val);
267	                break :blk Optional(T).from(dup);
268	            } else if (comptime @typeInfo(T) == .array and @typeInfo(T).array.child == u8) {
269	                const len = @typeInfo(T).array.len;
270	                if (val.len >= len) {
271	                    break :blk Optional(T).from(val[0..len].*);
272	                }
273	                break :blk .null_value;
274	            } else if (T == f16) {
275	                if (val.len >= 2) {
276	                    break :blk Optional(T).from(@as(f16, @bitCast(val[0..2].*)));
277	                }
278	                break :blk .null_value;
279	            } else {
280	                break :blk .null_value;
281	            }
282	        },
283	        .bool_val => |val| blk: {
284	            if (T == bool) {
285	                break :blk Optional(T).from(val);
286	            } else {
287	                break :blk .null_value;
288	            }
289	        },
290	        .list_val, .map_val, .struct_val => .null_value,
291	    };
292	}
293	
294	/// Result of decoding levels
295	const LevelsResult = struct {
296	    def_levels: ?[]u32,
297	    rep_levels: ?[]u32,
298	};
299	
300	/// Decode a column with OPTIONAL repetition (has definition levels)
301	/// Also handles repetition levels for nested/repeated columns.
302	/// Returns the decoded levels for list reconstruction.
303	fn decodeOptionalColumnWithLevels(
304	    comptime T: type,
305	    ctx: DecodeContext,
306	    value_data: []const u8,
307	    result: []Optional(T),
308	    is_fixed_len: bool,
309	    fixed_len: usize,
310	) !LevelsResult {
311	    var data_offset: usize = 0;
312	    var rep_levels_result: ?[]u32 = null;
313	    errdefer if (rep_levels_result) |rl| ctx.allocator.free(rl);
314	
315	    // Read repetition levels first (if present)
316	    // In Parquet, repetition levels come before definition levels
317	    if (ctx.max_repetition_level > 0) {
318	        const rep_bit_width = format.computeBitWidth(ctx.max_repetition_level);
319	
320	        if (ctx.rep_level_encoding == .bit_packed) {
321	            // Pure bit-packed: no length prefix
322	            const rep_bytes = rle.bitPackedSize(ctx.num_values, rep_bit_width);
323	            const rep_levels_data = try safe.slice(value_data, data_offset, rep_bytes);
324	            data_offset += rep_bytes;
325	            rep_levels_result = try rle.decodeBitPackedLevels(ctx.allocator, rep_levels_data, rep_bit_width, ctx.num_values);
326	        } else {
327	            // RLE hybrid: has length prefix
328	            const rep_levels_len = try plain.decodeU32(value_data[data_offset..]);
329	            data_offset += 4;
330	            const rep_levels_data = try safe.slice(value_data, data_offset, rep_levels_len);
331	            data_offset += rep_levels_len;
332	            rep_levels_result = try rle.decode(ctx.allocator, rep_levels_data, rep_bit_width, ctx.num_values);
333	        }
334	    }
335	
336	    // Read definition levels
337	    const def_bit_width = format.computeBitWidth(ctx.max_definition_level);
338	    var def_levels_raw: []u32 = undefined;
339	
340	    if (ctx.def_level_encoding == .bit_packed) {
341	        // Pure bit-packed: no length prefix
342	        const def_bytes = rle.bitPackedSize(ctx.num_values, def_bit_width);
343	        const def_levels_data = try safe.slice(value_data, data_offset, def_bytes);
344	        data_offset += def_bytes;
345	        def_levels_raw = try rle.decodeBitPackedLevels(ctx.allocator, def_levels_data, def_bit_width, ctx.num_values);
346	    } else {
347	        // RLE hybrid: has length prefix
348	        const def_levels_len = try plain.decodeU32(value_data[data_offset..]);
349	        data_offset += 4;
350	        const def_levels_data = try safe.slice(value_data, data_offset, def_levels_len);
351	        data_offset += def_levels_len;
352	        def_levels_raw = try rle.decodeLevels(ctx.allocator, def_levels_data, def_bit_width, ctx.num_values);
353	    }
354	    errdefer ctx.allocator.free(def_levels_raw);
355	
356	    const values_start = data_offset;
357	
358	    // Convert to boolean mask: value is present only when def_level == max_def_level
359	    // For nested types (structs, lists), lower def levels mean a parent is null
360	    const def_mask = try ctx.allocator.alloc(bool, ctx.num_values);
361	    defer ctx.allocator.free(def_mask);
362	
363	    var non_null_count: usize = 0;
364	    for (def_levels_raw, 0..) |level, i| {
365	        const is_present = level == ctx.max_definition_level;
366	        def_mask[i] = is_present;
367	        if (is_present) non_null_count += 1;
368	    }
369	
370	    // The caller has already checked if this page uses dictionary encoding
371	    // and set uses_dict accordingly (accounting for dictionary fallback)
372	    if (ctx.uses_dict) {
373	        // Dictionary encoded values with definition levels
374	        if (T == []const u8 and is_fixed_len and ctx.fixed_byte_array_dict != null) {
375	            // Fixed-length byte array with dictionary
376	            try decodeDictFixedByteArrayWithDefLevels(ctx, value_data, values_start, def_mask, non_null_count, result);
377	        } else if (T == []const u8 and !is_fixed_len) {
378	            // Variable-length byte array with dictionary
379	            try decodeDictStringsWithDefLevels(ctx, value_data, values_start, def_mask, non_null_count, result);
380	        } else if (T == i32) {
381	            try decodeDictInt32WithDefLevels(ctx, value_data, values_start, def_mask, non_null_count, result);
382	        } else if (T == i64) {
383	            try decodeDictInt64WithDefLevels(ctx, value_data, values_start, def_mask, non_null_count, result);
384	        } else if (T == f32 and ctx.float32_dict != null) {
385	            try decodeDictFloat32WithDefLevels(ctx, value_data, values_start, def_mask, non_null_count, result);
386	        } else if (T == f64 and ctx.float64_dict != null) {
387	            try decodeDictFloat64WithDefLevels(ctx, value_data, values_start, def_mask, non_null_count, result);
388	        } else if (T == Int96 and ctx.int96_dict != null) {
389	            try decodeDictInt96WithDefLevels(ctx, value_data, values_start, def_mask, non_null_count, result);
390	        } else {
391	            // Unsupported dictionary type - fall back to PLAIN
392	            try decodePlainWithDefLevels(T, ctx, value_data, values_start, def_mask, result, is_fixed_len, fixed_len);
393	        }
394	    } else {
395	        // PLAIN encoding with definition levels
396	        try decodePlainWithDefLevels(T, ctx, value_data, values_start, def_mask, result, is_fixed_len, fixed_len);
397	    }
398	
399	    return .{
400	        .def_levels = def_levels_raw,
401	        .rep_levels = rep_levels_result,
402	    };
403	}
