421	/// Decode dictionary-encoded strings with definition levels
422	fn decodeDictStringsWithDefLevels(
423	    ctx: DecodeContext,
424	    value_data: []const u8,
425	    values_start: usize,
426	    def_levels: []const bool,
427	    non_null_count: usize,
428	    result: []Optional([]const u8),
429	) !void {
430	    // After def levels, we have bit_width byte, then RLE-encoded indices
431	    const bit_width = try extractBitWidth(value_data, values_start);
432	    const indices_data = value_data[values_start + 1 ..];
433	
434	    // Decode only non-null indices
435	    const indices = try rle.decode(ctx.allocator, indices_data, bit_width, non_null_count);
436	    defer ctx.allocator.free(indices);
437	
438	    var idx_pos: usize = 0;
439	    for (0..ctx.num_values) |i| {
440	        if (def_levels[i]) {
441	            const dict_idx = indices[idx_pos];
442	            idx_pos += 1;
443	            if (ctx.string_dict.?.get(dict_idx)) |v| {
444	                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, v) };
445	            } else {
446	                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, "") };
447	            }
448	        } else {
449	            result[i] = .{ .null_value = {} };
450	        }
451	    }
452	}
