715	/// Decode a column with REQUIRED repetition (no definition levels)
716	fn decodeRequiredColumn(
717	    comptime T: type,
718	    ctx: DecodeContext,
719	    value_data: []const u8,
720	    result: []Optional(T),
721	    is_fixed_len: bool,
722	    fixed_len: usize,
723	) !void {
724	    // The caller has already checked if this page uses dictionary encoding
725	    // and set uses_dict accordingly (accounting for dictionary fallback)
726	    if (ctx.uses_dict and T == []const u8 and is_fixed_len and ctx.fixed_byte_array_dict != null) {
727	        // Dictionary encoded fixed-length byte array, required column
728	        const bit_width = try extractBitWidth(value_data, 0);
729	        const indices_data = value_data[1..];
730	
731	        const indices = try rle.decode(ctx.allocator, indices_data, bit_width, ctx.num_values);
732	        defer ctx.allocator.free(indices);
733	
734	        for (0..ctx.num_values) |i| {
735	            if (ctx.fixed_byte_array_dict.?.get(indices[i])) |v| {
736	                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, v) };
737	            } else {
738	                result[i] = .{ .null_value = {} };
739	            }
740	        }
741	    } else if (ctx.uses_dict and T == []const u8 and !is_fixed_len) {
742	        // Dictionary encoded strings (variable-length), required column
743	        // First byte is bit_width, then RLE-encoded indices
744	        const bit_width = try extractBitWidth(value_data, 0);
745	        const indices_data = value_data[1..];
746	
747	        const indices = try rle.decode(ctx.allocator, indices_data, bit_width, ctx.num_values);
748	        defer ctx.allocator.free(indices);
749	
750	        for (0..ctx.num_values) |i| {
751	            if (ctx.string_dict.?.get(indices[i])) |v| {
752	                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, v) };
753	            } else {
754	                result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, "") };
755	            }
756	        }
757	    } else if (ctx.uses_dict and T == i32) {
758	        // Dictionary encoded i32, required column
759	        const bit_width = try extractBitWidth(value_data, 0);
760	        const indices_data = value_data[1..];
761	
762	        const indices = try rle.decode(ctx.allocator, indices_data, bit_width, ctx.num_values);
763	        defer ctx.allocator.free(indices);
764	
765	        for (0..ctx.num_values) |i| {
766	            if (ctx.int32_dict.?.get(indices[i])) |v| {
767	                result[i] = .{ .value = v };
768	            } else {
769	                result[i] = .{ .value = 0 };
770	            }
771	        }
772	    } else if (ctx.uses_dict and T == i64) {
773	        // Dictionary encoded i64, required column
774	        const bit_width = try extractBitWidth(value_data, 0);
775	        const indices_data = value_data[1..];
776	
777	        const indices = try rle.decode(ctx.allocator, indices_data, bit_width, ctx.num_values);
778	        defer ctx.allocator.free(indices);
779	
780	        for (0..ctx.num_values) |i| {
781	            if (ctx.int64_dict.?.get(indices[i])) |v| {
782	                result[i] = .{ .value = v };
783	            } else {
784	                result[i] = .{ .value = 0 };
785	            }
786	        }
787	    } else if (ctx.uses_dict and T == f32 and ctx.float32_dict != null) {
788	        const bit_width = try extractBitWidth(value_data, 0);
789	        const indices = try rle.decode(ctx.allocator, value_data[1..], bit_width, ctx.num_values);
790	        defer ctx.allocator.free(indices);
791	
792	        for (0..ctx.num_values) |i| {
793	            if (ctx.float32_dict.?.get(indices[i])) |v| {
794	                result[i] = .{ .value = v };
795	            } else {
796	                result[i] = .{ .value = 0.0 };
797	            }
798	        }
799	    } else if (ctx.uses_dict and T == f64 and ctx.float64_dict != null) {
800	        const bit_width = try extractBitWidth(value_data, 0);
801	        const indices = try rle.decode(ctx.allocator, value_data[1..], bit_width, ctx.num_values);
802	        defer ctx.allocator.free(indices);
803	
804	        for (0..ctx.num_values) |i| {
805	            if (ctx.float64_dict.?.get(indices[i])) |v| {
806	                result[i] = .{ .value = v };
807	            } else {
808	                result[i] = .{ .value = 0.0 };
809	            }
810	        }
811	    } else if (T == []const u8 and is_fixed_len) {
812	        // Fixed-length byte array - no length prefix
813	        var data_offset: usize = 0;
814	        for (0..ctx.num_values) |i| {
815	            if (data_offset + fixed_len > value_data.len) return error.EndOfData;
816	            const value = value_data[data_offset..][0..fixed_len];
817	            result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, value) };
818	            data_offset += fixed_len;
819	        }
820	    } else if (T == f16 and is_fixed_len and fixed_len == 2) {
821	        // Float16: stored as FIXED_LEN_BYTE_ARRAY(2)
822	        var data_offset: usize = 0;
823	        for (0..ctx.num_values) |i| {
824	            if (data_offset + 2 > value_data.len) return error.EndOfData;
825	            const bytes: [2]u8 = .{ value_data[data_offset], value_data[data_offset + 1] };
826	            result[i] = .{ .value = @bitCast(bytes) };
827	            data_offset += 2;
828	        }
829	    } else if (T == []const u8 and !is_fixed_len and isDecimalIntColumn(ctx)) {
830	        // Decimal stored as INT32/INT64: read integer bytes, convert to big-endian
831	        const int_size: usize = if (ctx.schema_elem.type_ == .int32) 4 else 8;
832	        var data_offset: usize = 0;
833	        for (0..ctx.num_values) |i| {
834	            result[i] = .{ .value = try decodeDecimalInt(ctx.allocator, value_data, data_offset, int_size) };
835	            data_offset += int_size;
836	        }
837	    } else {
838	        // PLAIN encoding, required column
839	        var decoder = plain.PlainDecoder(T).init(value_data, ctx.num_values);
840	        for (0..ctx.num_values) |i| {
841	            if (decoder.next()) |v| {
842	                // For byte arrays, we need to dupe since value_data may be freed
843	                if (T == []const u8) {
844	                    result[i] = .{ .value = try value_mod.dupeBytes(ctx.allocator, v) };
845	                } else {
846	                    result[i] = .{ .value = v };
847	                }
848	            } else {
849	                result[i] = .{ .null_value = {} };
850	            }
851	        }
852	    }
853	}
