1013	/// Decode column values dynamically for DataPageV2 format
1014	/// In V2, levels are pre-extracted and passed separately (no length prefix in data)
1015	pub fn decodeColumnDynamicV2(
1016	    allocator: std.mem.Allocator,
1017	    schema_elem: format.SchemaElement,
1018	    rep_levels_data: []const u8,
1019	    def_levels_data: []const u8,
1020	    values_data: []const u8,
1021	    num_values: usize,
1022	    max_def_level: u8,
1023	    max_rep_level: u8,
1024	    uses_dict: bool,
1025	    string_dict: ?*dictionary.StringDictionary,
1026	    int32_dict: ?*dictionary.Int32Dictionary,
1027	    int64_dict: ?*dictionary.Int64Dictionary,
1028	    float32_dict: ?*dictionary.Float32Dictionary,
1029	    float64_dict: ?*dictionary.Float64Dictionary,
1030	    fixed_byte_array_dict: ?*dictionary.FixedByteArrayDictionary,
1031	    int96_dict: ?*dictionary.Int96Dictionary,
1032	    value_encoding: format.Encoding,
1033	) !DynamicDecodeResult {
1034	    // Decode levels from pre-extracted data (V2 format: RLE without length prefix)
1035	    const levels_result = try decodeLevelsV2(allocator, rep_levels_data, def_levels_data, num_values, max_def_level, max_rep_level);
1036	    errdefer {
1037	        if (levels_result.def_levels) |dl| allocator.free(dl);
1038	        if (levels_result.rep_levels) |rl| allocator.free(rl);
1039	        allocator.free(levels_result.def_mask);
1040	    }
1041	
1042	    const physical_type = schema_elem.type_ orelse return error.InvalidArgument;
1043	
1044	    // Check for delta encodings and dispatch appropriately
1045	    const values = try switch (value_encoding) {
1046	        .delta_binary_packed, .delta_length_byte_array, .delta_byte_array, .byte_stream_split => blk: {
1047	            // Use the delta encoding dispatcher
1048	            break :blk try decodeDeltaEncodedValuesV2(allocator, physical_type, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, value_encoding);
1049	        },
1050	        .rle => blk: {
1051	            if (physical_type == .boolean) {
1052	                break :blk try decodeDynamicBoolRLEV2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count);
1053	            }
1054	            return error.UnsupportedEncoding;
1055	        },
1056	        .plain, .rle_dictionary, .plain_dictionary => blk: {
1057	            const is_dict_encoded = uses_dict and
1058	                (value_encoding == .rle_dictionary or value_encoding == .plain_dictionary);
1059	
1060	            break :blk switch (physical_type) {
1061	                .boolean => decodeDynamicBoolV2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count),
1062	                .int32 => decodeDynamicInt32V2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, is_dict_encoded, int32_dict),
1063	                .int64 => decodeDynamicInt64V2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, is_dict_encoded, int64_dict),
1064	                .float => decodeDynamicFloatV2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, is_dict_encoded, float32_dict),
1065	                .double => decodeDynamicDoubleV2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, is_dict_encoded, float64_dict),
1066	                .byte_array => decodeDynamicByteArrayV2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, is_dict_encoded, string_dict),
1067	                .fixed_len_byte_array => decodeDynamicFixedByteArrayV2(allocator, schema_elem, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, is_dict_encoded, fixed_byte_array_dict),
1068	                .int96 => decodeDynamicInt96V2(allocator, values_data, num_values, levels_result.def_mask, levels_result.non_null_count, is_dict_encoded, int96_dict),
1069	            };
1070	        },
1071	        else => return error.UnsupportedEncoding,
1072	    };
1073	
1074	    allocator.free(levels_result.def_mask);
1075	
1076	    return .{
1077	        .values = values,
1078	        .def_levels = levels_result.def_levels,
1079	        .rep_levels = levels_result.rep_levels,
1080	    };
1081	}
