1083	/// Decode levels for V2 format (pre-extracted, no length prefix)
1084	fn decodeLevelsV2(
1085	    allocator: std.mem.Allocator,
1086	    rep_levels_data: []const u8,
1087	    def_levels_data: []const u8,
1088	    num_values: usize,
1089	    max_def_level: u8,
1090	    max_rep_level: u8,
1091	) !struct { def_levels: ?[]u32, rep_levels: ?[]u32, def_mask: []bool, non_null_count: usize } {
1092	    var rep_levels: ?[]u32 = null;
1093	    errdefer if (rep_levels) |rl| allocator.free(rl);
1094	
1095	    // Decode repetition levels if present
1096	    if (max_rep_level > 0 and rep_levels_data.len > 0) {
1097	        const rep_bit_width = format.computeBitWidth(max_rep_level);
1098	        // V2 uses RLE without length prefix
1099	        rep_levels = try rle.decodeLevels(allocator, rep_levels_data, rep_bit_width, num_values);
1100	    }
1101	
1102	    // Decode definition levels
1103	    var def_levels: ?[]u32 = null;
1104	    var def_mask = try allocator.alloc(bool, num_values);
1105	    errdefer allocator.free(def_mask);
1106	    var non_null_count: usize = num_values;
1107	
1108	    if (max_def_level > 0 and def_levels_data.len > 0) {
1109	        const def_bit_width = format.computeBitWidth(max_def_level);
1110	        // V2 uses RLE without length prefix
1111	        def_levels = try rle.decodeLevels(allocator, def_levels_data, def_bit_width, num_values);
1112	        errdefer if (def_levels) |dl| allocator.free(dl);
1113	
1114	        non_null_count = 0;
1115	        for (def_levels.?, 0..) |level, i| {
1116	            const is_present = level == max_def_level;
1117	            def_mask[i] = is_present;
1118	            if (is_present) non_null_count += 1;
1119	        }
1120	    } else {
1121	        // All values present
1122	        @memset(def_mask, true);
1123	    }
1124	
1125	    return .{
1126	        .def_levels = def_levels,
1127	        .rep_levels = rep_levels,
1128	        .def_mask = def_mask,
1129	        .non_null_count = non_null_count,
1130	    };
1131	}
