1285	                    const decoded = try allocator.alloc(i64, non_null_count);
1286	                    defer allocator.free(decoded);
1287	                    try byte_stream_split.decodeInt64Into(values_data, decoded);
1288	
1289	                    var decoded_idx: usize = 0;
1290	                    for (0..num_values) |i| {
1291	                        if (def_mask[i]) {
