1	//! BufferReader - in-memory SeekableReader backend
2	//!
3	//! Useful for WASM (where data is fetched via JS and passed as a buffer)
4	//! and for testing (where test data can be constructed in memory).
5	
6	const std = @import("std");
7	const safe = @import("../core/safe.zig");
8	const SeekableReader = @import("../core/seekable_reader.zig").SeekableReader;
9	
10	pub const BufferReader = struct {
11	    data: []const u8,
12	
13	    /// Create a BufferReader from a byte slice.
14	    /// The slice must outlive the BufferReader.
15	    pub fn init(data: []const u8) BufferReader {
16	        return .{ .data = data };
17	    }
18	
19	    /// Get a SeekableReader interface for this buffer.
20	    /// The BufferReader must outlive the returned SeekableReader.
21	    pub fn reader(self: *BufferReader) SeekableReader {
22	        return .{
23	            .ptr = self,
24	            .vtable = &vtable,
25	        };
26	    }
27	
28	    const vtable = SeekableReader.VTable{
29	        .readAt = readAt,
30	        .size = getSize,
31	    };
32	
33	    fn readAt(ctx: *anyopaque, offset: u64, buf: []u8) SeekableReader.Error!usize {
34	        const self: *BufferReader = @ptrCast(@alignCast(ctx));
35	        if (offset >= self.data.len) {
36	            return 0;
37	        }
38	        const start = safe.cast(offset) catch return 0; // Safe: validated above
39	        const len = @min(buf.len, self.data.len - start);
40	        @memcpy(buf[0..len], self.data[start..][0..len]);
41	        return len;
42	    }
43	
44	    fn getSize(ctx: *anyopaque) u64 {
45	        const self: *BufferReader = @ptrCast(@alignCast(ctx));
46	        return self.data.len;
47	    }
48	};
