1	//! CallbackReader - callback-backed SeekableReader implementation
2	//!
3	//! Enables reading from caller-provided function pointers, bridging the
4	//! SeekableReader vtable to external IO callbacks. This is the primary
5	//! transport for C ABI, WASM host, and custom IO backends.
6	//!
7	//! ## Example
8	//! ```zig
9	//! var cb = CallbackReader{
10	//!     .ctx = @ptrCast(&my_source),
11	//!     .read_at_fn = myReadAt,
12	//!     .size_fn = mySize,
13	//! };
14	//! const seekable = cb.reader();
15	//! var reader = try Reader.initFromSeekable(allocator, seekable);
16	//! ```
17	
18	const std = @import("std");
19	const SeekableReader = @import("../core/seekable_reader.zig").SeekableReader;
20	
21	/// Callback-backed random-access reader.
22	///
23	/// The caller owns the context pointer and guarantees it outlives the
24	/// CallbackReader. The library never frees the callback context.
25	pub const CallbackReader = struct {
26	    ctx: *anyopaque,
27	    read_at_fn: *const fn (ctx: *anyopaque, offset: u64, out: []u8) SeekableReader.Error!usize,
28	    size_fn: *const fn (ctx: *anyopaque) u64,
29	
30	    const vtable = SeekableReader.VTable{
31	        .readAt = callbackReadAt,
32	        .size = callbackSize,
33	    };
34	
35	    fn callbackReadAt(ptr: *anyopaque, offset: u64, buf: []u8) SeekableReader.Error!usize {
36	        const self: *CallbackReader = @ptrCast(@alignCast(ptr));
37	        return self.read_at_fn(self.ctx, offset, buf);
38	    }
39	
40	    fn callbackSize(ptr: *anyopaque) u64 {
41	        const self: *CallbackReader = @ptrCast(@alignCast(ptr));
42	        return self.size_fn(self.ctx);
43	    }
44	
45	    /// Get a SeekableReader interface backed by these callbacks.
46	    /// The CallbackReader must outlive the returned SeekableReader.
47	    pub fn reader(self: *CallbackReader) SeekableReader {
48	        return .{ .ptr = @ptrCast(self), .vtable = &vtable };
49	    }
50	};
