1	//! PLAIN encoding decoder
2	//!
3	//! PLAIN is the simplest encoding in Parquet:
4	//! - Boolean: 1 bit per value, packed into bytes
5	//! - Int32/Int64: 4/8 bytes little-endian
6	//! - Float/Double: 4/8 bytes IEEE 754 little-endian
7	//! - ByteArray: 4-byte length prefix + bytes
8	//! - FixedLenByteArray: just the bytes (length known from schema)
9	//! - Int96: 12 bytes (legacy timestamp format)
10	
11	const std = @import("std");
12	const safe = @import("../safe.zig");
13	const types = @import("../types.zig");
14	const Int96 = types.Int96;
15	
16	/// Decode a boolean at the given index (booleans are bit-packed)
17	/// Returns error if index is out of bounds.
18	pub fn decodeBool(data: []const u8, index: usize) error{EndOfData}!bool {
19	    const byte_idx = index / 8;
20	    if (byte_idx >= data.len) return error.EndOfData;
21	        const bit_idx: u3 = safe.castTo(u3, index % 8) catch return error.EndOfData;
22	    return (data[byte_idx] >> bit_idx) & 1 == 1;
23	}
24	
25	/// Decode an i32 from the current position
26	pub fn decodeI32(data: []const u8) !i32 {
27	    if (data.len < 4) return error.EndOfData;
28	    return std.mem.readInt(i32, data[0..4], .little);
29	}
30	
31	/// Decode a u32 from the current position
32	pub fn decodeU32(data: []const u8) !u32 {
33	    if (data.len < 4) return error.EndOfData;
34	    return std.mem.readInt(u32, data[0..4], .little);
35	}
36	
37	/// Decode an i64 from the current position
38	pub fn decodeI64(data: []const u8) !i64 {
39	    if (data.len < 8) return error.EndOfData;
40	    return std.mem.readInt(i64, data[0..8], .little);
41	}
42	
43	/// Decode an f32 from the current position
44	pub fn decodeFloat(data: []const u8) !f32 {
45	    if (data.len < 4) return error.EndOfData;
46	    const bits = std.mem.readInt(u32, data[0..4], .little);
47	    return @bitCast(bits);
48	}
49	
50	/// Decode an f64 from the current position
51	pub fn decodeDouble(data: []const u8) !f64 {
52	    if (data.len < 8) return error.EndOfData;
53	    const bits = std.mem.readInt(u64, data[0..8], .little);
54	    return @bitCast(bits);
55	}
56	
57	/// Decode a byte array (returns slice and bytes consumed)
58	pub const ByteArrayResult = struct {
59	    value: []const u8,
60	    bytes_read: usize,
61	};
62	
63	pub fn decodeByteArray(data: []const u8) !ByteArrayResult {
64	    const len = try decodeU32(data);
65	    if (data.len < 4 + len) return error.EndOfData;
66	    return .{
67	        .value = data[4..][0..len],
68	        .bytes_read = 4 + len,
69	    };
70	}
71	
72	/// A streaming decoder for PLAIN-encoded values
73	pub fn PlainDecoder(comptime T: type) type {
74	    return struct {
75	        data: []const u8,
76	        pos: usize = 0,
77	        count: usize,
78	        current_index: usize = 0,
79	
80	        const Self = @This();
81	
82	        pub fn init(data: []const u8, count: usize) Self {
83	            return .{ .data = data, .count = count };
84	        }
85	
86	        pub fn next(self: *Self) ?T {
87	            if (self.current_index >= self.count) return null;
88	            self.current_index += 1;
89	
90	            if (T == bool) {
91	                const result = decodeBool(self.data, self.current_index - 1) catch return null;
92	                return result;
93	            } else if (T == i32) {
94	                const result = decodeI32(self.data[self.pos..]) catch return null;
95	                self.pos += 4;
96	                return result;
97	            } else if (T == i64) {
98	                const result = decodeI64(self.data[self.pos..]) catch return null;
99	                self.pos += 8;
100	                return result;
101	            } else if (T == f32) {
102	                const result = decodeFloat(self.data[self.pos..]) catch return null;
103	                self.pos += 4;
104	                return result;
105	            } else if (T == f64) {
106	                const result = decodeDouble(self.data[self.pos..]) catch return null;
107	                self.pos += 8;
108	                return result;
109	            } else if (T == []const u8) {
110	                const result = decodeByteArray(self.data[self.pos..]) catch return null;
111	                self.pos += result.bytes_read;
112	                return result.value;
113	            } else if (T == f16) {
114	                // Float16: 2 bytes, IEEE 754 half-precision
115	                if (self.pos + 2 > self.data.len) return null;
116	                const bytes: [2]u8 = .{ self.data[self.pos], self.data[self.pos + 1] };
117	                const result: f16 = @bitCast(bytes);
118	                self.pos += 2;
119	                return result;
120	            } else if (T == Int96) {
121	                // Int96: 12 bytes (legacy timestamp format)
122	                if (self.pos + 12 > self.data.len) return null;
123	                const slice_12 = safe.slice(self.data, self.pos, 12) catch return null;
124	                const result = Int96.fromBytes(slice_12[0..12].*);
125	                self.pos += 12;
126	                return result;
127	            } else {
128	                @compileError("Unsupported type for PlainDecoder");
129	            }
130	        }
131	
132	        pub fn remaining(self: *const Self) usize {
133	            return self.count - self.current_index;
134	        }
135	    };
136	}
