1616	/// Helper to decode levels with explicit encodings
1617	fn decodeLevelsForDynamicWithEncoding(
1618	    allocator: std.mem.Allocator,
1619	    value_data: []const u8,
1620	    num_values: usize,
1621	    max_def_level: u8,
1622	    max_rep_level: u8,
1623	    def_level_encoding: format.Encoding,
1624	    rep_level_encoding: format.Encoding,
1625	) !struct { data_offset: usize, def_levels: ?[]u32, rep_levels: ?[]u32, def_mask: []bool, non_null_count: usize } {
1626	    var data_offset: usize = 0;
1627	    var rep_levels: ?[]u32 = null;
1628	    errdefer if (rep_levels) |rl| allocator.free(rl);
1629	
1630	    // Read repetition levels first (if present)
1631	    if (max_rep_level > 0) {
1632	        const rep_bit_width = format.computeBitWidth(max_rep_level);
1633	
1634	        if (rep_level_encoding == .bit_packed) {
1635	            // Pure bit-packed: no length prefix
1636	            const rep_bytes = rle.bitPackedSize(num_values, rep_bit_width);
1637	            if (data_offset + rep_bytes > value_data.len) return error.EndOfData;
1638	            const rep_levels_data = try safe.slice(value_data, data_offset, rep_bytes);
1639	            data_offset += rep_bytes;
1640	            rep_levels = try rle.decodeBitPackedLevels(allocator, rep_levels_data, rep_bit_width, num_values);
1641	        } else {
1642	            // RLE hybrid: has length prefix
1643	            if (data_offset + 4 > value_data.len) return error.EndOfData;
1644	            const rep_levels_len = try plain.decodeU32(value_data[data_offset..]);
1645	            data_offset += 4;
1646	            if (data_offset + rep_levels_len > value_data.len) return error.EndOfData;
1647	            const rep_levels_data = try safe.slice(value_data, data_offset, rep_levels_len);
1648	            data_offset += rep_levels_len;
1649	            rep_levels = try rle.decode(allocator, rep_levels_data, rep_bit_width, num_values);
1650	        }
1651	    }
1652	
1653	    // Read definition levels (if present)
1654	    var def_levels: ?[]u32 = null;
1655	    var def_mask = try allocator.alloc(bool, num_values);
1656	    errdefer allocator.free(def_mask);
1657	    var non_null_count: usize = num_values;
1658	
1659	    if (max_def_level > 0) {
1660	        const def_bit_width = format.computeBitWidth(max_def_level);
1661	
1662	        if (def_level_encoding == .bit_packed) {
1663	            // Pure bit-packed: no length prefix
1664	            const def_bytes = rle.bitPackedSize(num_values, def_bit_width);
1665	            if (data_offset + def_bytes > value_data.len) return error.EndOfData;
1666	            const def_levels_data = try safe.slice(value_data, data_offset, def_bytes);
1667	            data_offset += def_bytes;
1668	            def_levels = try rle.decodeBitPackedLevels(allocator, def_levels_data, def_bit_width, num_values);
1669	        } else {
1670	            // RLE hybrid: has length prefix
1671	            if (data_offset + 4 > value_data.len) return error.EndOfData;
1672	            const def_levels_len = try plain.decodeU32(value_data[data_offset..]);
1673	            data_offset += 4;
1674	            if (data_offset + def_levels_len > value_data.len) return error.EndOfData;
1675	            const def_levels_data = try safe.slice(value_data, data_offset, def_levels_len);
1676	            data_offset += def_levels_len;
1677	            def_levels = try rle.decodeLevels(allocator, def_levels_data, def_bit_width, num_values);
1678	        }
1679	        errdefer if (def_levels) |dl| allocator.free(dl);
1680	
1681	        non_null_count = 0;
1682	        for (def_levels.?, 0..) |level, i| {
1683	            const is_present = level == max_def_level;
1684	            def_mask[i] = is_present;
1685	            if (is_present) non_null_count += 1;
1686	        }
1687	    } else {
1688	        // REQUIRED column (max_def_level == 0): no definition levels to decode.
1689	        // All values are present per the schema.
1690	        //
1691	        // Note: V2 pages handle malformed files (REQUIRED with level bytes) correctly
1692	        // because the header provides explicit byte counts that are skipped in the caller.
1693	        // V1 pages with malformed REQUIRED columns will fail, matching Go/C++/Java/PyArrow.
1694	        @memset(def_mask, true);
1695	    }
1696	
1697	    return .{
1698	        .data_offset = data_offset,
1699	        .def_levels = def_levels,
1700	        .rep_levels = rep_levels,
1701	        .def_mask = def_mask,
1702	        .non_null_count = non_null_count,
1703	    };
1704	}
