1981	/// Decode dictionary-encoded f32 values
1982	fn decodeDictFloat32(
1983	    allocator: std.mem.Allocator,
1984	    value_data: []const u8,
1985	    num_values: usize,
1986	    max_def_level: u8,
1987	    max_rep_level: u8,
1988	    float32_dict: *dictionary.Float32Dictionary,
1989	    def_level_encoding: format.Encoding,
1990	    rep_level_encoding: format.Encoding,
1991	) !DynamicDecodeResult {
1992	    const levels_info = try decodeLevelsForDynamicWithEncoding(allocator, value_data, num_values, max_def_level, max_rep_level, def_level_encoding, rep_level_encoding);
1993	    defer allocator.free(levels_info.def_mask);
1994	
1995	    const values = try allocator.alloc(Value, num_values);
1996	    errdefer allocator.free(values);
1997	
1998	    // Decode dictionary indices (RLE encoded)
1999	    const indices_data = value_data[levels_info.data_offset..];
2000	    if (indices_data.len == 0) {
2001	        // All nulls
2002	        for (0..num_values) |i| {
2003	            values[i] = .{ .null_val = {} };
2004	        }
2005	    } else {
2006	        const bit_width = try extractBitWidth(indices_data, 0);
2007	        const indices = try rle.decode(allocator, indices_data[1..], bit_width, levels_info.non_null_count);
2008	        defer allocator.free(indices);
2009	
2010	        var idx_pos: usize = 0;
2011	        for (0..num_values) |i| {
2012	            if (levels_info.def_mask[i]) {
2013	                if (float32_dict.get(indices[idx_pos])) |v| {
2014	                    values[i] = .{ .float_val = v };
2015	                } else {
2016	                    values[i] = .{ .float_val = 0 };
2017	                }
2018	                idx_pos += 1;
2019	            } else {
2020	                values[i] = .{ .null_val = {} };
2021	            }
2022	        }
2023	    }
2024	
2025	    return .{
2026	        .values = values,
2027	        .def_levels = levels_info.def_levels,
2028	        .rep_levels = levels_info.rep_levels,
2029	    };
2030	}
