2084	    allocator: std.mem.Allocator,
2085	    schema_elem: format.SchemaElement,
2086	    value_data: []const u8,
2087	    num_values: usize,
2088	    max_def_level: u8,
2089	    max_rep_level: u8,
2090	    uses_dict: bool,
2091	    string_dict: ?*dictionary.StringDictionary,
2092	    def_level_encoding: format.Encoding,
2093	    rep_level_encoding: format.Encoding,
2094	) !DynamicDecodeResult {
2095	    const ctx = DecodeContext{
2096	        .allocator = allocator,
2097	        .schema_elem = schema_elem,
2098	        .num_values = num_values,
2099	        .uses_dict = uses_dict,
2100	        .string_dict = string_dict,
2101	        .max_definition_level = max_def_level,
2102	        .max_repetition_level = max_rep_level,
2103	        .def_level_encoding = def_level_encoding,
2104	        .rep_level_encoding = rep_level_encoding,
2105	    };
2106	
2107	    const typed_result = try decodeColumnWithLevels([]const u8, ctx, value_data);
2108	    // Don't defer free - we're transferring ownership of the byte arrays
2109	
2110	    const values = try allocator.alloc(Value, num_values);
2111	    errdefer allocator.free(values);
2112	
2113	    for (typed_result.values, 0..) |opt, i| {
2114	        values[i] = switch (opt) {
2115	            .value => |v| .{ .bytes_val = v }, // Transfer ownership
2116	            .null_value => .{ .null_val = {} },
2117	        };
2118	    }
2119	
2120	    // Free just the container, not the byte array contents (transferred to Value)
2121	    allocator.free(typed_result.values);
2122	
