1	//! DICTIONARY encoding support
2	//!
3	//! Dictionary encoding stores unique values in a dictionary page, then
4	//! references them by index in data pages. This is efficient for columns
5	//! with low cardinality (few unique values).
6	//!
7	//! The dictionary page contains PLAIN-encoded values.
8	//! Data pages contain RLE/bit-packed encoded indices.
9	
10	const std = @import("std");
11	const plain = @import("plain.zig");
12	const rle = @import("rle.zig");
13	const safe = @import("../safe.zig");
14	
15	/// Dictionary for string/binary values
16	pub const StringDictionary = struct {
17	    allocator: std.mem.Allocator,
18	    values: [][]const u8,
19	    owns_memory: bool,
20	
21	    const Self = @This();
22	
23	    /// Create a dictionary from PLAIN-encoded byte arrays
24	    pub fn fromPlain(allocator: std.mem.Allocator, data: []const u8, num_values: usize) !Self {
25	        var values = try allocator.alloc([]const u8, num_values);
26	        var initialized: usize = 0;
27	        errdefer {
28	            for (values[0..initialized]) |v| allocator.free(v);
29	            allocator.free(values);
30	        }
31	
32	        var pos: usize = 0;
33	        for (0..num_values) |i| {
34	            if (pos + 4 > data.len) return error.EndOfData;
35	            const ba = try plain.decodeByteArray(data[pos..]);
36	            values[i] = try allocator.dupe(u8, ba.value);
37	            initialized += 1;
38	            pos += ba.bytes_read;
39	        }
40	
41	        return .{
42	            .allocator = allocator,
43	            .values = values,
44	            .owns_memory = true,
45	        };
46	    }
47	
48	    /// Look up a value by index
49	    pub fn get(self: *const Self, index: u32) ?[]const u8 {
50	        if (index >= self.values.len) return null;
51	        return self.values[index];
52	    }
53	
54	    pub fn deinit(self: *Self) void {
55	        if (self.owns_memory) {
56	            for (self.values) |v| {
57	                self.allocator.free(v);
58	            }
59	        }
60	        self.allocator.free(self.values);
61	    }
62	};
