1588	
1589	        var data_offset: usize = 0;
1590	        for (0..num_values) |i| {
1591	            if (def_mask[i]) {
1592	                if (data_offset + fixed_len > values_data.len) return error.EndOfData;
1593	                const value = values_data[data_offset..][0..fixed_len];
1594	                values[i] = .{ .fixed_bytes_val = try value_mod.dupeBytes(allocator, value) };
1595	                data_offset += fixed_len;
1596	            } else {
1597	                values[i] = .{ .null_val = {} };
1598	            }
1599	        }
1600	    }
1601	    return values;
1602	}
