1747	/// Decode RLE-encoded boolean values (Parquet spec allows RLE for booleans)
1748	fn decodeDynamicBoolRLE(
1749	    allocator: std.mem.Allocator,
1750	    value_data: []const u8,
1751	    num_values: usize,
1752	    max_def_level: u8,
1753	    max_rep_level: u8,
1754	    def_level_encoding: format.Encoding,
1755	    rep_level_encoding: format.Encoding,
1756	) !DynamicDecodeResult {
1757	    // Parse definition/repetition levels first
1758	    const levels_info = try decodeLevelsForDynamicWithEncoding(
1759	        allocator, value_data, num_values, max_def_level, max_rep_level,
1760	        def_level_encoding, rep_level_encoding,
1761	    );
1762	    defer allocator.free(levels_info.def_mask);
1763	
1764	    const values_data = value_data[levels_info.data_offset..];
1765	    const values = try allocator.alloc(Value, num_values);
1766	    errdefer allocator.free(values);
1767	
1768	    if (levels_info.non_null_count == 0 or values_data.len == 0) {
1769	        // All nulls
1770	        for (0..num_values) |i| {
1771	            values[i] = .{ .null_val = {} };
1772	        }
1773	    } else {
1774	        // Decode RLE-encoded booleans with bit_width = 1
1775	        const decoded_u32 = try rle.decode(allocator, values_data, 1, levels_info.non_null_count);
1776	        defer allocator.free(decoded_u32);
1777	
1778	        // Map decoded values to output, respecting nulls
1779	        var decoded_idx: usize = 0;
1780	        for (0..num_values) |i| {
1781	            if (levels_info.def_mask[i]) {
1782	                if (decoded_idx < decoded_u32.len) {
1783	                    values[i] = .{ .bool_val = decoded_u32[decoded_idx] != 0 };
1784	                    decoded_idx += 1;
1785	                } else {
1786	                    values[i] = .{ .null_val = {} };
1787	                }
1788	            } else {
1789	                values[i] = .{ .null_val = {} };
1790	            }
1791	        }
1792	    }
1793	
1794	    return .{
1795	        .values = values,
1796	        .def_levels = levels_info.def_levels,
1797	        .rep_levels = levels_info.rep_levels,
1798	    };
1799	}
