208	/// Dictionary for Int96 (legacy timestamp) values
209	pub const Int96Dictionary = struct {
210	    allocator: std.mem.Allocator,
211	    values: [][12]u8,
212	
213	    const Self = @This();
214	
215	    /// Create a dictionary from PLAIN-encoded Int96 values (12 bytes each)
216	    pub fn fromPlain(allocator: std.mem.Allocator, data: []const u8, num_values: usize) !Self {
217	        const required = std.math.mul(usize, num_values, 12) catch return error.EndOfData;
218	        if (data.len < required) return error.EndOfData;
219	
220	        var values = try allocator.alloc([12]u8, num_values);
221	        errdefer allocator.free(values);
222	
223	        for (0..num_values) |i| {
224	            values[i] = (safe.slice(data, i * 12, 12) catch return error.EndOfData)[0..12].*;
225	        }
226	
227	        return .{
228	            .allocator = allocator,
229	            .values = values,
230	        };
231	    }
232	
233	    /// Look up a value by index (returns raw 12-byte array)
234	    pub fn get(self: *const Self, index: u32) ?[12]u8 {
235	        if (index >= self.values.len) return null;
236	        return self.values[index];
237	    }
238	
239	    pub fn deinit(self: *Self) void {
240	        self.allocator.free(self.values);
241	    }
242	};
