244	/// Dictionary for fixed-length byte array values (e.g., float16, UUID)
245	pub const FixedByteArrayDictionary = struct {
246	    allocator: std.mem.Allocator,
247	    values: [][]const u8,
248	    fixed_len: usize,
249	
250	    const Self = @This();
251	
252	    /// Create a dictionary from PLAIN-encoded fixed-length byte arrays
253	    pub fn fromPlain(allocator: std.mem.Allocator, data: []const u8, num_values: usize, fixed_len: usize) !Self {
254	        const required = std.math.mul(usize, num_values, fixed_len) catch return error.EndOfData;
255	        if (data.len < required) return error.EndOfData;
256	
257	        var values = try allocator.alloc([]const u8, num_values);
258	        var initialized: usize = 0;
259	        errdefer {
260	            for (values[0..initialized]) |v| allocator.free(v);
261	            allocator.free(values);
262	        }
263	
264	        for (0..num_values) |i| {
265	            const start = i * fixed_len;
266	            values[i] = try allocator.dupe(u8, safe.slice(data, start, fixed_len) catch return error.EndOfData);
267	            initialized += 1;
268	        }
269	
270	        return .{
271	            .allocator = allocator,
272	            .values = values,
273	            .fixed_len = fixed_len,
274	        };
275	    }
276	
277	    /// Look up a value by index
278	    pub fn get(self: *const Self, index: u32) ?[]const u8 {
279	        if (index >= self.values.len) return null;
280	        return self.values[index];
281	    }
282	
283	    pub fn deinit(self: *Self) void {
284	        for (self.values) |v| {
285	            self.allocator.free(v);
286	        }
287	        self.allocator.free(self.values);
288	    }
289	};
