1	//! Dynamic value types for nested Parquet data
2	//!
3	//! This module provides a recursive `Value` type that can represent any
4	//! Parquet value, including arbitrarily nested lists, maps, and structs.
5	//! This enables reading Parquet files without knowing the schema at compile time.
6	
7	const std = @import("std");
8	
9	/// Thread-local override for byte payload allocations. When set (typically by
10	/// `DynamicReader.readRowsInternal`), all `bytes_val` / `fixed_bytes_val`
11	/// payloads produced via `dupeBytes` go into this allocator instead of the
12	/// per-value allocator. Paired with `Row.bytes_borrowed = true` so per-value
13	/// frees in `deinit` skip these payloads; the producer frees the arena en
14	/// masse. Save/restore the prior value at each entry point — the pattern is:
15	///
16	///     const prev = value_mod.bytes_arena_allocator;
17	///     value_mod.bytes_arena_allocator = arena.allocator();
18	///     defer value_mod.bytes_arena_allocator = prev;
19	///
20	/// This replaces the per-value `allocator.dupe(u8, ...)` hot path (~440k
21	/// allocations on covid.snappy.parquet) with one arena's worth of contiguous
22	/// allocations, avoiding the N*stack-trace overhead of DebugAllocator.
23	pub threadlocal var bytes_arena_allocator: ?std.mem.Allocator = null;
24	
25	/// Duplicate a byte slice, routing through `bytes_arena_allocator` if set,
26	/// else through the provided `fallback` allocator. Every producer of
27	/// `Value.bytes_val` and `Value.fixed_bytes_val` should call this helper
28	/// instead of `allocator.dupe(u8, ...)` to participate in the arena scheme.
29	pub fn dupeBytes(fallback: std.mem.Allocator, bytes: []const u8) std.mem.Allocator.Error![]u8 {
30	    const alloc = bytes_arena_allocator orelse fallback;
31	    return alloc.dupe(u8, bytes);
32	}
33	
34	/// A dynamic value that can represent any Parquet data.
35	///
36	/// Unlike the typed `Optional(T)` approach which requires knowing types at
37	/// compile time, `Value` can represent any nested structure dynamically.
38	///
39	/// ## Example
40	/// ```zig
41	/// // Represents: {"id": 1, "tags": ["a", "b"]}
42	/// const row = Value{ .struct_val = &[_]Value.FieldValue{
43	///     .{ .name = "id", .value = .{ .int64_val = 1 } },
44	///     .{ .name = "tags", .value = .{ .list_val = &[_]Value{
45	///         .{ .bytes_val = "a" },
46	///         .{ .bytes_val = "b" },
47	///     }}},
48	/// }};
49	/// ```
50	pub const Value = union(enum) {
51	    // Null
52	    null_val: void,
53	
54	    // Primitives
55	    bool_val: bool,
56	    int32_val: i32,
57	    int64_val: i64,
58	    float_val: f32,
59	    double_val: f64,
60	    bytes_val: []const u8,
61	    fixed_bytes_val: []const u8,
62	
63	    // Nested types (recursive via slices)
64	    list_val: []const Value,
65	    map_val: []const MapEntryValue,
66	    struct_val: []const FieldValue,
67	
68	    /// A key-value pair in a map
69	    pub const MapEntryValue = struct {
70	        key: Value,
71	        value: Value,
72	    };
73	
74	    /// A named field in a struct
75	    pub const FieldValue = struct {
76	        name: []const u8,
77	        value: Value,
78	    };
79	
80	    /// Check if this value is null
81	    pub fn isNull(self: Value) bool {
82	        return self == .null_val;
83	    }
84	
85	    /// Get the value as a specific type, or return null if type doesn't match
86	    pub fn asInt32(self: Value) ?i32 {
87	        return switch (self) {
88	            .int32_val => |v| v,
89	            else => null,
90	        };
91	    }
92	
93	    /// Get the value as a specific type, or return null if type doesn't match
94	    pub fn asInt64(self: Value) ?i64 {
95	        return switch (self) {
96	            .int64_val => |v| v,
97	            else => null,
98	        };
99	    }
100	
101	    /// Get the value as a specific type, or return null if type doesn't match
102	    pub fn asFloat(self: Value) ?f32 {
103	        return switch (self) {
104	            .float_val => |v| v,
105	            else => null,
106	        };
107	    }
108	
109	    /// Get the value as a specific type, or return null if type doesn't match
110	    pub fn asDouble(self: Value) ?f64 {
111	        return switch (self) {
112	            .double_val => |v| v,
113	            else => null,
114	        };
115	    }
116	
117	    /// Get the value as a specific type, or return null if type doesn't match
118	    pub fn asBool(self: Value) ?bool {
119	        return switch (self) {
120	            .bool_val => |v| v,
121	            else => null,
122	        };
123	    }
124	
125	    /// Get the value as bytes (string), or return null if type doesn't match
126	    pub fn asBytes(self: Value) ?[]const u8 {
127	        return switch (self) {
128	            .bytes_val => |v| v,
129	            .fixed_bytes_val => |v| v,
130	            else => null,
131	        };
132	    }
133	
134	    /// Get the value as a list, or return null if not a list
135	    pub fn asList(self: Value) ?[]const Value {
136	        return switch (self) {
137	            .list_val => |v| v,
138	            else => null,
139	        };
140	    }
141	
142	    /// Get the value as a map, or return null if not a map
143	    pub fn asMap(self: Value) ?[]const MapEntryValue {
144	        return switch (self) {
145	            .map_val => |v| v,
146	            else => null,
147	        };
148	    }
149	
150	    /// Get the value as a struct, or return null if not a struct
151	    pub fn asStruct(self: Value) ?[]const FieldValue {
152	        return switch (self) {
153	            .struct_val => |v| v,
154	            else => null,
155	        };
156	    }
157	
158	    /// Get a field from a struct value by name
159	    pub fn getField(self: Value, name: []const u8) ?Value {
160	        const fields = self.asStruct() orelse return null;
161	        for (fields) |f| {
162	            if (std.mem.eql(u8, f.name, name)) {
163	                return f.value;
164	            }
165	        }
166	        return null;
167	    }
168	
169	    /// Format value for printing
170	    pub fn format(
171	        self: Value,
172	        writer: *std.Io.Writer,
173	    ) std.Io.Writer.Error!void {
174	        switch (self) {
175	            .null_val => try writer.writeAll("null"),
176	            .bool_val => |v| try writer.print("{}", .{v}),
177	            .int32_val => |v| try writer.print("{}", .{v}),
178	            .int64_val => |v| try writer.print("{}", .{v}),
179	            .float_val => |v| try formatFloat(f32, v, writer),
180	            .double_val => |v| try formatFloat(f64, v, writer),
181	            .bytes_val => |v| try writer.print("\"{s}\"", .{v}),
182	            .fixed_bytes_val => |v| try writer.print("\"{s}\"", .{v}),
183	            .list_val => |items| {
184	                try writer.writeAll("[");
185	                for (items, 0..) |item, i| {
186	                    if (i > 0) try writer.writeAll(", ");
187	                    try item.format(writer);
188	                }
189	                try writer.writeAll("]");
190	            },
191	            .map_val => |entries| {
192	                try writer.writeAll("{");
193	                for (entries, 0..) |entry, i| {
194	                    if (i > 0) try writer.writeAll(", ");
195	                    try entry.key.format(writer);
196	                    try writer.writeAll(": ");
197	                    try entry.value.format(writer);
198	                }
199	                try writer.writeAll("}");
200	            },
201	            .struct_val => |fields| {
202	                try writer.writeAll("{");
203	                for (fields, 0..) |field, i| {
204	                    if (i > 0) try writer.writeAll(", ");
205	                    try writer.print("{s}: ", .{field.name});
206	                    try field.value.format(writer);
207	                }
208	                try writer.writeAll("}");
209	            },
210	        }
211	    }
212	
213	    fn formatFloat(comptime T: type, v: T, writer: *std.Io.Writer) std.Io.Writer.Error!void {
214	        if (std.math.isInf(v)) {
215	            if (v < 0) {
216	                try writer.writeAll("-inf");
217	            } else {
218	                try writer.writeAll("inf");
219	            }
220	        } else if (std.math.isNan(v)) {
221	            try writer.writeAll("nan");
222	        } else {
223	            try writer.print("{d}", .{v});
224	        }
225	    }
