227	    pub const DeinitOptions = struct {
228	        /// When true, skip freeing `bytes_val` / `fixed_bytes_val` payloads.
229	        /// Set by producers that routed byte allocations through an arena
230	        /// (see `bytes_arena_allocator`); those slices are sub-slices of
231	        /// arena chunks and cannot be freed individually.
232	        skip_bytes: bool = false,
233	    };
234	
235	    /// Free all memory owned by this value recursively.
236	    ///
237	    /// If `bytes_arena_allocator` is currently set (i.e. we're inside a
238	    /// decode context), byte payloads are automatically skipped — they
239	    /// live in the arena and are freed en masse by the producer. Outside
240	    /// a decode context this behaves as the classic owned-everything free.
241	    ///
242	    /// For explicit control use `deinitWithOptions`.
243	    pub fn deinit(self: Value, allocator: std.mem.Allocator) void {
244	        self.deinitWithOptions(allocator, .{ .skip_bytes = bytes_arena_allocator != null });
245	    }
246	
247	    /// Like `deinit` but with explicit byte-payload freeing control.
248	    /// Callers holding a `Row` with `bytes_borrowed = true` pass
249	    /// `.{ .skip_bytes = true }` so the arena-owned payloads are preserved.
250	    pub fn deinitWithOptions(self: Value, allocator: std.mem.Allocator, opts: DeinitOptions) void {
251	        switch (self) {
252	            .null_val, .bool_val, .int32_val, .int64_val, .float_val, .double_val => {},
253	            .bytes_val => |v| if (!opts.skip_bytes) allocator.free(v),
254	            .fixed_bytes_val => |v| if (!opts.skip_bytes) allocator.free(v),
255	            .list_val => |items| {
256	                for (items) |item| {
257	                    item.deinitWithOptions(allocator, opts);
258	                }
259	                allocator.free(items);
260	            },
261	            .map_val => |entries| {
262	                for (entries) |entry| {
263	                    entry.key.deinitWithOptions(allocator, opts);
264	                    entry.value.deinitWithOptions(allocator, opts);
265	                }
266	                allocator.free(entries);
267	            },
268	            .struct_val => |fields| {
269	                for (fields) |field| {
270	                    allocator.free(field.name);
271	                    field.value.deinitWithOptions(allocator, opts);
272	                }
273	                allocator.free(fields);
274	            },
275	        }
276	    }
277	};
