279	/// A row of values, one per column
280	pub const Row = struct {
281	    values: []Value,
282	    allocator: std.mem.Allocator,
283	    /// When true, bytes_val / fixed_bytes_val payloads live in an arena
284	    /// owned by the producer (e.g. DynamicReader.bytes_arena) and must
285	    /// NOT be freed per-value. List/map/struct container slices and
286	    /// struct field names are still freed through `allocator`.
287	    bytes_borrowed: bool = false,
288	
289	    /// Get the value for a specific column index
290	    pub fn getColumn(self: Row, col_idx: usize) ?Value {
291	        if (col_idx >= self.values.len) return null;
292	        return self.values[col_idx];
293	    }
294	
295	    /// Get the number of columns in this row
296	    pub fn columnCount(self: Row) usize {
297	        return self.values.len;
298	    }
299	
300	    /// Iterate over all columns, calling the callback for each
301	    /// Returns early if callback returns false
302	    pub fn range(self: Row, context: anytype, callback: fn (ctx: @TypeOf(context), col_idx: usize, value: Value) bool) void {
303	        for (self.values, 0..) |value, col_idx| {
304	            if (!callback(context, col_idx, value)) {
305	                break;
306	            }
307	        }
308	    }
309	
310	    /// Free all memory owned by this row
311	    pub fn deinit(self: Row) void {
312	        const opts: Value.DeinitOptions = .{ .skip_bytes = self.bytes_borrowed };
313	        for (self.values) |v| v.deinitWithOptions(self.allocator, opts);
314	        self.allocator.free(self.values);
315	    }
316	};
