2130	fn decodeDynamicFixedByteArray(
2131	    allocator: std.mem.Allocator,
2132	    schema_elem: format.SchemaElement,
2133	    value_data: []const u8,
2134	    num_values: usize,
2135	    max_def_level: u8,
2136	    max_rep_level: u8,
2137	    uses_dict: bool,
2138	    fixed_byte_array_dict: ?*dictionary.FixedByteArrayDictionary,
2139	    def_level_encoding: format.Encoding,
2140	    rep_level_encoding: format.Encoding,
2141	) !DynamicDecodeResult {
2142	    if (uses_dict and fixed_byte_array_dict != null) {
2143	        // Dictionary-encoded: decode levels first, then look up values from dictionary
2144	        var pos: usize = 0;
2145	
2146	        // Decode repetition levels first (per Parquet V1 spec: rep before def)
2147	        var rep_levels: ?[]u32 = null;
2148	        errdefer if (rep_levels) |rl| allocator.free(rl);
2149	
2150	        if (max_rep_level > 0) {
2151	            const rep_bit_width = format.computeBitWidth(max_rep_level);
2152	            if (rep_level_encoding == .bit_packed) {
2153	                if (pos > value_data.len) return error.EndOfData;
2154	                rep_levels = try rle.decodeBitPackedLevels(allocator, value_data[pos..], rep_bit_width, num_values);
2155	                pos += rle.bitPackedSize(num_values, rep_bit_width);
2156	            } else {
2157	                if (pos + 4 > value_data.len) return error.EndOfData;
2158	                const rep_len = std.mem.readInt(u32, value_data[pos..][0..4], .little);
2159	                pos += 4;
2160	                if (pos + rep_len > value_data.len) return error.EndOfData;
2161	                rep_levels = try rle.decodeLevels(allocator, value_data[pos..][0..rep_len], rep_bit_width, num_values);
2162	                pos += rep_len;
2163	            }
2164	        }
2165	
2166	        // Decode definition levels
2167	        var def_levels: ?[]u32 = null;
2168	        errdefer if (def_levels) |dl| allocator.free(dl);
2169	
2170	        var non_null_count: usize = num_values;
2171	        if (max_def_level > 0) {
2172	            const def_bit_width = format.computeBitWidth(max_def_level);
2173	            if (def_level_encoding == .bit_packed) {
2174	                if (pos > value_data.len) return error.EndOfData;
2175	                def_levels = try rle.decodeBitPackedLevels(allocator, value_data[pos..], def_bit_width, num_values);
2176	                pos += rle.bitPackedSize(num_values, def_bit_width);
2177	            } else {
2178	                if (pos + 4 > value_data.len) return error.EndOfData;
2179	                const def_len = std.mem.readInt(u32, value_data[pos..][0..4], .little);
2180	                pos += 4;
2181	                if (pos + def_len > value_data.len) return error.EndOfData;
2182	                def_levels = try rle.decodeLevels(allocator, value_data[pos..][0..def_len], def_bit_width, num_values);
2183	                pos += def_len;
2184	            }
2185	
2186	            non_null_count = 0;
2187	            for (def_levels.?) |level| {
2188	                if (level == max_def_level) non_null_count += 1;
2189	            }
2190	        }
2191	
2192	        // Handle all-null case
2193	        if (non_null_count == 0) {
2194	            const values = try allocator.alloc(Value, num_values);
2195	            for (0..num_values) |i| {
2196	                values[i] = .{ .null_val = {} };
2197	            }
2198	            return .{
2199	                .values = values,
2200	                .def_levels = def_levels,
2201	                .rep_levels = rep_levels,
2202	            };
2203	        }
2204	
2205	        // Decode dictionary indices
2206	        const indices_data = value_data[pos..];
2207	        if (indices_data.len == 0) return error.EndOfData;
2208	
2209	        const bit_width = try extractBitWidth(indices_data, 0);
2210	        const indices = try rle.decode(allocator, indices_data[1..], bit_width, non_null_count);
2211	        defer allocator.free(indices);
2212	
2213	        // Build output values
2214	        const values = try allocator.alloc(Value, num_values);
2215	        errdefer allocator.free(values);
2216	
2217	        var idx_pos: usize = 0;
2218	        for (0..num_values) |i| {
2219	            const is_present = if (def_levels) |dl| dl[i] == max_def_level else true;
2220	            if (is_present) {
2221	                if (fixed_byte_array_dict.?.get(indices[idx_pos])) |v| {
2222	                    values[i] = .{ .fixed_bytes_val = try value_mod.dupeBytes(allocator, v) };
2223	                } else {
2224	                    values[i] = .{ .null_val = {} };
2225	                }
2226	                idx_pos += 1;
2227	            } else {
2228	                values[i] = .{ .null_val = {} };
2229	            }
2230	        }
2231	
2232	        return .{
2233	            .values = values,
2234	            .def_levels = def_levels,
2235	            .rep_levels = rep_levels,
2236	        };
2237	    }
2238	
2239	    // Plain encoding - use the typed decoder path
2240	    const ctx = DecodeContext{
2241	        .allocator = allocator,
2242	        .schema_elem = schema_elem,
2243	        .num_values = num_values,
2244	        .uses_dict = false,
2245	        .string_dict = null,
2246	        .max_definition_level = max_def_level,
2247	        .max_repetition_level = max_rep_level,
2248	        .def_level_encoding = def_level_encoding,
2249	        .rep_level_encoding = rep_level_encoding,
2250	    };
2251	
2252	    const typed_result = try decodeColumnWithLevels([]const u8, ctx, value_data);
2253	
2254	    const values = try allocator.alloc(Value, num_values);
2255	    errdefer allocator.free(values);
2256	
2257	    for (typed_result.values, 0..) |opt, i| {
2258	        values[i] = switch (opt) {
2259	            .value => |v| .{ .fixed_bytes_val = v }, // Transfer ownership
2260	            .null_value => .{ .null_val = {} },
2261	        };
2262	    }
2263	
2264	    allocator.free(typed_result.values);
2265	
2266	    return .{
2267	        .values = values,
2268	        .def_levels = typed_result.def_levels,
2269	        .rep_levels = typed_result.rep_levels,
2270	    };
2271	}
