2277	/// Decode INT96 values (12-byte legacy timestamp format)
2278	/// Converts to i64 nanoseconds since Unix epoch for compatibility with modern timestamps
2279	fn decodeDynamicInt96(
2280	    allocator: std.mem.Allocator,
2281	    schema_elem: format.SchemaElement,
2282	    value_data: []const u8,
2283	    num_values: usize,
2284	    max_def_level: u8,
2285	    max_rep_level: u8,
2286	    uses_dict: bool,
2287	    int96_dict: ?*dictionary.Int96Dictionary,
2288	    def_level_encoding: format.Encoding,
2289	    rep_level_encoding: format.Encoding,
2290	) !DynamicDecodeResult {
2291	    _ = schema_elem;
2292	
2293	    if (uses_dict and int96_dict != null) {
2294	        return decodeDictInt96(allocator, value_data, num_values, max_def_level, max_rep_level, int96_dict.?, def_level_encoding, rep_level_encoding);
2295	    }
2296	
2297	    // Decode levels first to get data offset
2298	    const levels_info = try decodeLevelsForDynamicWithEncoding(
2299	        allocator, value_data, num_values, max_def_level, max_rep_level,
2300	        def_level_encoding, rep_level_encoding,
2301	    );
2302	    defer allocator.free(levels_info.def_mask);
2303	
2304	    const values_data = value_data[levels_info.data_offset..];
2305	    const values = try allocator.alloc(Value, num_values);
2306	    errdefer allocator.free(values);
2307	
2308	    var data_offset: usize = 0;
2309	    for (0..num_values) |i| {
2310	        if (levels_info.def_mask[i]) {
2311	            if (data_offset + 12 > values_data.len) {
2312	                values[i] = .{ .null_val = {} };
2313	                continue;
2314	            }
2315	            const int96_bytes: [12]u8 = values_data[data_offset..][0..12].*;
2316	            const int96 = Int96.fromBytes(int96_bytes);
2317	            values[i] = .{ .int64_val = int96.toNanos() };
2318	            data_offset += 12;
2319	        } else {
2320	            values[i] = .{ .null_val = {} };
2321	        }
2322	    }
2323	
2324	    return .{
2325	        .values = values,
2326	        .def_levels = levels_info.def_levels,
2327	        .rep_levels = levels_info.rep_levels,
2328	    };
2329	}
