2441	/// Decode DELTA_BINARY_PACKED encoded int32/int64 values
2442	fn decodeDeltaBinaryPacked(
2443	    allocator: std.mem.Allocator,
2444	    schema_elem: format.SchemaElement,
2445	    value_data: []const u8,
2446	    num_values: usize,
2447	    max_def_level: u8,
2448	    max_rep_level: u8,
2449	    def_level_encoding: format.Encoding,
2450	    rep_level_encoding: format.Encoding,
2451	) !DynamicDecodeResult {
2452	    const physical_type = schema_elem.type_ orelse return error.InvalidArgument;
2453	    
2454	    // Decode levels first to get data offset
2455	    const levels_info = try decodeLevelsForDynamicWithEncoding(
2456	        allocator, value_data, num_values, max_def_level, max_rep_level,
2457	        def_level_encoding, rep_level_encoding,
2458	    );
2459	    defer allocator.free(levels_info.def_mask);
2460	    
2461	    const values_data = value_data[levels_info.data_offset..];
2462	    const values = try allocator.alloc(Value, num_values);
2463	    errdefer allocator.free(values);
2464	    
2465	    if (physical_type == .int32) {
2466	        const decoded = delta_binary_packed.decodeInt32(allocator, values_data) catch |err| {
2467	            return switch (err) {
2468	                error.OutOfMemory => error.OutOfMemory,
2469	                else => error.InvalidArgument,
2470	            };
2471	        };
2472	        defer allocator.free(decoded);
2473	        
2474	        // Map decoded values to output, respecting nulls
2475	        var decoded_idx: usize = 0;
2476	        for (0..num_values) |i| {
2477	            if (levels_info.def_mask[i]) {
2478	                if (decoded_idx < decoded.len) {
2479	                    values[i] = .{ .int32_val = decoded[decoded_idx] };
2480	                    decoded_idx += 1;
2481	                } else {
2482	                    values[i] = .{ .null_val = {} };
2483	                }
2484	            } else {
