1	//! Thrift Compact Protocol decoder
2	//!
3	//! The Compact Protocol is a binary protocol that uses variable-length encoding
4	//! for integers and packs field headers efficiently.
5	
6	const std = @import("std");
7	const safe = @import("../safe.zig");
8	
9	/// Thrift type codes used in Compact Protocol
10	pub const Type = enum(u4) {
11	    stop = 0,
12	    bool_true = 1,
13	    bool_false = 2,
14	    i8 = 3,
15	    i16 = 4,
16	    i32 = 5,
17	    i64 = 6,
18	    double = 7,
19	    binary = 8, // Also used for strings
20	    list = 9,
21	    set = 10,
22	    map = 11,
23	    struct_ = 12,
24	    // uuid = 13, // Not used in Parquet
25	};
26	
27	pub const FieldHeader = struct {
28	    field_id: i16,
29	    field_type: Type,
30	};
31	
32	pub const ListHeader = struct {
33	    element_type: Type,
34	    size: u32,
35	};
36	
37	/// A reader for Thrift Compact Protocol encoded data
38	pub const CompactReader = struct {
39	    data: []const u8,
40	    pos: usize = 0,
41	    last_field_id: i16 = 0,
42	
43	    const Self = @This();
44	
45	    pub fn init(data: []const u8) Self {
46	        return .{ .data = data };
47	    }
48	
49	    /// Read a single byte
50	    pub fn readByte(self: *Self) !u8 {
51	        if (self.pos >= self.data.len) return error.EndOfData;
52	        const b = self.data[self.pos];
53	        self.pos += 1;
54	        return b;
55	    }
56	
57	    /// Read N bytes
58	    fn readBytes(self: *Self, n: usize) ![]const u8 {
59	        if (self.pos + n > self.data.len) return error.EndOfData;
60	            const bytes = try safe.slice(self.data, self.pos, n);
61	        self.pos += n;
62	        return bytes;
63	    }
64	
65	    /// Read an unsigned variable-length integer (varint)
66	    pub fn readVarInt(self: *Self) !u64 {
67	        var result: u64 = 0;
68	        var shift: u7 = 0;
69	        while (true) {
70	            const b = try self.readByte();
71	            result |= @as(u64, b & 0x7F) << @as(u6, std.math.cast(u6, shift) orelse return error.VarIntTooLong);
72	            if (b & 0x80 == 0) break;
73	            shift += 7;
74	            if (shift >= 64) return error.VarIntTooLong;
75	        }
76	        return result;
77	    }
78	
79	    /// Decode a zigzag-encoded signed integer
80	    fn zigzagDecode(n: u64) i64 {
81	        return @bitCast((n >> 1) ^ -%@as(u64, n & 1));
82	    }
83	
84	    /// Read a signed 16-bit integer (zigzag + varint)
85	    pub fn readI16(self: *Self) !i16 {
86	        const v = try self.readVarInt();
87	        const decoded = zigzagDecode(v);
88	        if (decoded < std.math.minInt(i16) or decoded > std.math.maxInt(i16)) {
89	            return error.IntegerOverflow;
90	        }
91	        return safe.castTo(i16, decoded) catch return error.IntegerOverflow;
92	    }
93	
94	    /// Read a signed 32-bit integer (zigzag + varint)
95	    pub fn readI32(self: *Self) !i32 {
96	        const v = try self.readVarInt();
97	        const decoded = zigzagDecode(v);
98	        if (decoded < std.math.minInt(i32) or decoded > std.math.maxInt(i32)) {
99	            return error.IntegerOverflow;
100	        }
101	        return safe.castTo(i32, decoded) catch return error.IntegerOverflow;
102	    }
103	
104	    /// Read a signed 64-bit integer (zigzag + varint)
105	    pub fn readI64(self: *Self) !i64 {
106	        const v = try self.readVarInt();
107	        return zigzagDecode(v);
108	    }
109	
110	    /// Read an 8-byte double
111	    pub fn readDouble(self: *Self) !f64 {
112	        const bytes = try self.readBytes(8);
113	        return @bitCast(std.mem.readInt(u64, bytes[0..8], .little));
114	    }
115	
116	    /// Read a length-prefixed binary blob
117	    pub fn readBinary(self: *Self) ![]const u8 {
118	        const len = try self.readVarInt();
119	        if (len > std.math.maxInt(usize)) return error.LengthTooLong;
120	        return try self.readBytes(safe.castTo(usize, len) catch return error.IntegerOverflow);
121	    }
122	
123	    /// Read a length-prefixed string (same as binary but semantically UTF-8)
124	    pub fn readString(self: *Self) ![]const u8 {
125	        return self.readBinary();
126	    }
127	
128	    /// Read a field header, returns null when STOP field is encountered
129	    pub fn readFieldHeader(self: *Self) !?FieldHeader {
130	        const b = try self.readByte();
131	
132	        // STOP field
133	        if (b == 0) return null;
134	
135	        // Mask to 4 bits: value 0-15 always fits in u4
136	        const type_id: u4 = @truncate(b & 0x0F);
137	        const field_type = std.enums.fromInt(Type, type_id) orelse return error.InvalidFieldType;
138	
139	        // Delta encoding: high nibble contains field ID delta
140	        const delta: u4 = @truncate((b >> 4) & 0x0F);
141	        var field_id: i16 = undefined;
142	
143	        if (delta != 0) {
144	            // Delta encoded
145	            field_id = self.last_field_id + delta;
146	        } else {
147	            // Full field ID follows
148	            field_id = try self.readI16();
149	        }
150	
151	        self.last_field_id = field_id;
152	        return .{ .field_id = field_id, .field_type = field_type };
153	    }
154	
155	    /// Read a list header
156	    pub fn readListHeader(self: *Self) !ListHeader {
157	        const b = try self.readByte();
158	
159	        // Mask to 4 bits: value 0-15 always fits in u4
160	        const size_nibble: u4 = @truncate((b >> 4) & 0x0F);
161	        const type_nibble: u4 = @truncate(b & 0x0F);
162	        const element_type = std.enums.fromInt(Type, type_nibble) orelse return error.InvalidListType;
163	
164	        var size: u32 = undefined;
165	        if (size_nibble == 0x0F) {
166	            // Size is in following varint
167	            const s = try self.readVarInt();
168	            if (s > std.math.maxInt(u32)) return error.ListTooLong;
169	            size = safe.castTo(u32, s) catch return error.IntegerOverflow;
170	        } else {
171	            size = size_nibble;
172	        }
173	
174	        return .{ .element_type = element_type, .size = size };
175	    }
176	
177	    /// Reset field ID tracking (call when entering a new struct)
178	    pub fn resetFieldTracking(self: *Self) void {
179	        self.last_field_id = 0;
180	    }
181	
182	    /// Skip a value of the given type
183	    pub fn skip(self: *Self, t: Type) !void {
184	        switch (t) {
185	            .stop => {},
186	            .bool_true, .bool_false => {},
187	            .i8 => _ = try self.readByte(),
188	            .i16, .i32, .i64 => _ = try self.readVarInt(),
189	            .double => _ = try self.readBytes(8),
190	            .binary => {
191	                const len = try self.readVarInt();
192	                if (len > std.math.maxInt(usize)) return error.LengthTooLong;
193	                _ = try self.readBytes(safe.castTo(usize, len) catch return error.IntegerOverflow);
194	            },
195	            .list, .set => {
196	                const header = try self.readListHeader();
197	                for (0..header.size) |_| {
198	                    try self.skip(header.element_type);
199	                }
200	            },
201	            .map => {
202	                const size = try self.readVarInt();
203	                if (size == 0) return;
204	                if (size > std.math.maxInt(usize)) return error.ListTooLong;
205	                const types = try self.readByte();
206	                // Mask to 4 bits: (0-15) always fits in u4
207	                const key_type: Type = @enumFromInt(@as(u4, @truncate((types >> 4) & 0x0F)));
208	                const val_type: Type = @enumFromInt(@as(u4, @truncate(types & 0x0F)));
209	                for (0..safe.castTo(usize, size) catch return error.IntegerOverflow) |_| {
210	                    try self.skip(key_type);
211	                    try self.skip(val_type);
212	                }
213	            },
214	            .struct_ => {
215	                const saved_field_id = self.last_field_id;
216	                self.resetFieldTracking();
217	                while (try self.readFieldHeader()) |field| {
218	                    try self.skip(field.field_type);
219	                }
220	                self.last_field_id = saved_field_id;
221	            },
222	        }
223	    }
224	
225	    /// Get remaining unread data
226	    pub fn remaining(self: *Self) []const u8 {
227	        return self.data[self.pos..];
228	    }
229	
230	    /// Check if at end of data
231	    pub fn isAtEnd(self: *Self) bool {
232	        return self.pos >= self.data.len;
233	    }
234	};
