1	//! Safe operations for hardening against malformed data.
2	//!
3	//! All operations return errors instead of causing undefined behavior.
4	//! This module enables the library's safety guarantee: no UB from malformed input.
5	
6	const std = @import("std");
7	
8	/// Safe cast to usize. Uses anytype to infer source type.
9	/// Returns error.IntegerOverflow when value is negative or would overflow.
10	pub fn cast(val: anytype) error{IntegerOverflow}!usize {
11	    return castTo(usize, val);
12	}
13	
14	/// Safe cast to a specific target type (when target is not usize).
15	pub fn castTo(comptime Target: type, val: anytype) error{IntegerOverflow}!Target {
16	    return std.math.cast(Target, val) orelse error.IntegerOverflow;
17	}
18	
19	/// Safe slice with bounds checking.
20	pub fn slice(data: []const u8, offset: usize, len: usize) error{EndOfData}![]const u8 {
21	    if (offset > data.len) return error.EndOfData;
22	    if (len > data.len - offset) return error.EndOfData;
23	    return data[offset..][0..len];
24	}
25	
26	/// Generic safe slice for any element type.
27	pub fn sliceOf(comptime T: type, data: []const T, offset: usize, len: usize) error{EndOfData}![]const T {
28	    if (offset > data.len) return error.EndOfData;
29	    if (len > data.len - offset) return error.EndOfData;
30	    return data[offset..][0..len];
31	}
32	
33	/// Generic safe mutable slice for any element type.
34	pub fn sliceMutOf(comptime T: type, data: []T, offset: usize, len: usize) error{EndOfData}![]T {
35	    if (offset > data.len) return error.EndOfData;
36	    if (len > data.len - offset) return error.EndOfData;
37	    return data[offset..][0..len];
38	}
39	
40	/// Safe mutable slice with bounds checking.
41	pub fn sliceMut(data: []u8, offset: usize, len: usize) error{EndOfData}![]u8 {
42	    if (offset > data.len) return error.EndOfData;
43	    if (len > data.len - offset) return error.EndOfData;
44	    return data[offset..][0..len];
45	}
46	
47	/// Safe array indexing.
48	pub fn get(comptime T: type, data: []const T, index: usize) error{EndOfData}!T {
49	    if (index >= data.len) return error.EndOfData;
50	    return data[index];
51	}
