1	//! DELTA_BINARY_PACKED Encoding
2	//!
3	//! This encoding is used for integer types (INT32, INT64). It stores the first value
4	//! directly, then encodes subsequent values as deltas from the previous value.
5	//!
6	//! Structure:
7	//! - Header (all unsigned varints except first_value which is signed):
8	//!   - block_size: number of values per block (must be multiple of 128)
9	//!   - num_mini_blocks: number of mini-blocks per block
10	//!   - total_values: total count of values in the encoded data
11	//!   - first_value: the first value (signed zigzag-encoded varint)
12	//!
13	//! - For each block:
14	//!   - min_delta: minimum delta in the block (signed zigzag-encoded varint)
15	//!   - bit_widths: one byte per mini-block, the bit width used
16	//!   - mini-blocks: bit-packed relative deltas (delta - min_delta)
17	//!
18	//! Decoding: unpack bits → add min_delta → add to previous value
19	//!
20	//! Reference: https://parquet.apache.org/docs/file-format/data-pages/encodings/#delta-encoding-delta_binary_packed--5
21	
22	const std = @import("std");
23	const safe = @import("../safe.zig");
24	
25	pub const Error = error{
26	    InvalidHeader,
27	    InvalidBlockSize,
28	    InvalidMiniBlockCount,
29	    InvalidValueCount,
30	    InsufficientData,
31	    VarintOverflow,
32	    OutOfMemory,
33	};
34	
35	/// Decode DELTA_BINARY_PACKED encoded i32 values
36	pub fn decodeInt32(allocator: std.mem.Allocator, data: []const u8) Error![]i32 {
37	    var decoder = Decoder(i32).init(data);
38	    return decoder.decode(allocator);
39	}
40	
41	/// Decode DELTA_BINARY_PACKED encoded i64 values
42	pub fn decodeInt64(allocator: std.mem.Allocator, data: []const u8) Error![]i64 {
43	    var decoder = Decoder(i64).init(data);
44	    return decoder.decode(allocator);
45	}
46	
47	/// Generic delta binary packed decoder
48	pub fn Decoder(comptime T: type) type {
49	    return struct {
50	        const Self = @This();
51	
52	        data: []const u8,
53	        pos: usize,
54	
55	        // Header values
56	        block_size: usize,
57	        num_mini_blocks: usize,
58	        total_values: usize,
59	        first_value: T,
60	
61	        pub fn init(data: []const u8) Self {
62	            return .{
63	                .data = data,
64	                .pos = 0,
65	                .block_size = 0,
66	                .num_mini_blocks = 0,
67	                .total_values = 0,
68	                .first_value = 0,
69	            };
70	        }
71	
72	        pub fn decode(self: *Self, allocator: std.mem.Allocator) Error![]T {
73	            // Parse header
74	            try self.readHeader();
75	
76	            if (self.total_values == 0) {
77	                return allocator.alloc(T, 0) catch return error.OutOfMemory;
78	            }
79	
80	            // Allocate result
81	            const result = allocator.alloc(T, self.total_values) catch return error.OutOfMemory;
82	            errdefer allocator.free(result);
83	
84	            // First value is stored directly
85	            result[0] = self.first_value;
86	
87	            if (self.total_values == 1) {
88	                return result;
89	            }
90	
91	            // Decode remaining values in blocks
92	            var values_decoded: usize = 1;
93	            var last_value = self.first_value;
94	            const mini_block_size = self.block_size / self.num_mini_blocks;
95	
96	            while (values_decoded < self.total_values) {
97	                // Read block header
98	                const min_delta_raw = try self.readSignedVarint();
99	                // Validate min_delta fits in T
100	                const min_delta = std.math.cast(T, min_delta_raw) orelse return error.InvalidValueCount;
101	
102	                // Read bit widths for each mini-block
103	                if (self.pos + self.num_mini_blocks > self.data.len) {
104	                    return error.InsufficientData;
105	                }
106	            const bit_widths = safe.slice(self.data, self.pos, self.num_mini_blocks) catch return error.InsufficientData;
107	                self.pos += self.num_mini_blocks;
108	
109	                // Decode each mini-block
110	                for (bit_widths) |bit_width| {
111	                    if (values_decoded >= self.total_values) break;
112	
113	                    const values_in_mini_block = @min(mini_block_size, self.total_values - values_decoded);
114	
115	                    if (bit_width == 0) {
116	                        // All values have delta = min_delta
117	                        for (0..values_in_mini_block) |_| {
118	                            const value = last_value +% min_delta;
119	                            result[values_decoded] = value;
120	                            last_value = value;
121	                            values_decoded += 1;
122	                        }
123	                    } else {
124	                        // Bit-packed values
125	                        const mini_block_bytes = (mini_block_size * bit_width + 7) / 8;
126	                        if (self.pos + mini_block_bytes > self.data.len) {
127	                            return error.InsufficientData;
128	                        }
129	                        const packed_data = safe.slice(self.data, self.pos, mini_block_bytes) catch return error.InsufficientData;
130	                        self.pos += mini_block_bytes;
131	
132	                        // Unpack and accumulate
133	                        try self.unpackMiniBlock(packed_data, bit_width, min_delta, &last_value, safe.sliceMutOf(T, result, values_decoded, values_in_mini_block) catch return error.InsufficientData);
134	                        values_decoded += values_in_mini_block;
135	                    }
136	                }
137	            }
138	
139	            return result;
140	        }
141	
142	        fn readHeader(self: *Self) Error!void {
143	            const block_size_raw = try self.readUnsignedVarint();
144	            const num_mini_blocks_raw = try self.readUnsignedVarint();
145	            const total_values_raw = try self.readUnsignedVarint();
146	            const first_value_raw = try self.readSignedVarint();
147	
148	            // Validate and cast header values
149	            self.block_size = std.math.cast(usize, block_size_raw) orelse return error.InvalidBlockSize;
150	            self.num_mini_blocks = std.math.cast(usize, num_mini_blocks_raw) orelse return error.InvalidMiniBlockCount;
151	            self.total_values = std.math.cast(usize, total_values_raw) orelse return error.InvalidValueCount;
152	            self.first_value = std.math.cast(T, first_value_raw) orelse return error.InvalidValueCount;
153	
154	            // Validate header
155	            if (self.block_size == 0 or self.block_size % 128 != 0) {
156	                return error.InvalidBlockSize;
157	            }
158	            if (self.num_mini_blocks == 0) {
159	                return error.InvalidMiniBlockCount;
160	            }
161	            const mini_block_size = self.block_size / self.num_mini_blocks;
162	            if (mini_block_size % 32 != 0) {
163	                return error.InvalidMiniBlockCount;
164	            }
165	        }
166	
167	        fn readUnsignedVarint(self: *Self) Error!u64 {
168	            var result: u64 = 0;
169	            var shift: u6 = 0;
170	
171	            while (self.pos < self.data.len) {
172	                const b = self.data[self.pos];
173	                self.pos += 1;
174	
175	                result |= @as(u64, b & 0x7F) << shift;
176	
177	                if (b & 0x80 == 0) {
178	                    return result;
179	                }
180	
181	                shift += 7;
182	                if (shift >= 64) {
183	                    return error.VarintOverflow;
184	                }
185	            }
186	
187	            return error.InsufficientData;
188	        }
189	
190	        fn readSignedVarint(self: *Self) Error!i64 {
191	            // Zigzag decode
192	            const unsigned = try self.readUnsignedVarint();
193	            // Zigzag: (n >> 1) ^ -(n & 1)
194	            const n: i64 = @bitCast(unsigned);
195	            return (n >> 1) ^ (-(n & 1));
196	        }
197	
198	        fn unpackMiniBlock(
199	            self: *Self,
200	            packed_data: []const u8,
201	            bit_width: u8,
202	            min_delta: T,
203	            last_value: *T,
204	            output: []T,
205	        ) Error!void {
206	            _ = self;
207	
208	            // Validate bit_width is reasonable (max 64 bits for u64 values)
209	            if (bit_width > 64) return error.InvalidHeader;
210	
211	            var bit_pos: usize = 0;
212	            const mask = if (bit_width >= 64) ~@as(u64, 0) else (@as(u64, 1) << (safe.castTo(u6, bit_width) catch unreachable)) - 1; // bit_width <= 64 from check above
213	
214	            for (output) |*out| {
215	                // Extract bit_width bits starting at bit_pos
216	                const byte_pos = bit_pos / 8;
217	                const bit_offset: u6 = safe.castTo(u6, bit_pos % 8) catch unreachable; // bit_pos % 8 is strictly 0-7, fits u6
218	
219	                // Read up to 8 bytes (enough for 64 bits)
220	                var value: u64 = 0;
221	                const bytes_needed = (bit_offset + bit_width + 7) / 8;
222	
223	                        const bytes_to_read = @min(bytes_needed, packed_data.len - byte_pos);
224	                        for (0..@min(bytes_to_read, 8)) |i| {
225	                            value |= @as(u64, packed_data[byte_pos + i]) << (safe.castTo(u6, i * 8) catch unreachable); // i < 8, so i * 8 <= 56, fits u6
226	                        }
227	
228	                // Shift and mask
229	                value = (value >> bit_offset) & mask;
230	
231	                // Add min_delta and accumulate
232	                // The packed value is an unsigned offset from min_delta
233	                // Do all arithmetic in i128 to avoid overflow, then truncate to T
234	                const delta_i128: i128 = @as(i128, min_delta) + @as(i128, value);
235	                const last_i128: i128 = @as(i128, last_value.*);
236	                const new_value_i128 = last_i128 + delta_i128;
237	                const new_value: T = @truncate(@as(i64, @truncate(new_value_i128)));
238	                out.* = new_value;
239	                last_value.* = new_value;
240	
241	                bit_pos += bit_width;
242	            }
243	        }
244	    };
245	}
