104	        // Block header - deltas are [2, -3], min_delta = -3
105	        0x05, // min_delta = -3 (zigzag: -3 -> 5)
106	        // bit_widths: need 3 bits to store [2-(-3)=5, -3-(-3)=0] = [5, 0]
