1	//! BYTE_STREAM_SPLIT Encoding
2	//!
3	//! This encoding splits each value's bytes and groups them by byte position.
4	//! For example, for 32-bit floats with N values:
5	//! - All first bytes together (N bytes)
6	//! - All second bytes together (N bytes)
7	//! - All third bytes together (N bytes)
8	//! - All fourth bytes together (N bytes)
9	//!
10	//! This is effective for floating-point data because similar values often share
11	//! byte patterns, making the grouped bytes more compressible.
12	//!
13	//! Reference: https://parquet.apache.org/docs/file-format/data-pages/encodings/#byte-stream-split
14	
15	const std = @import("std");
16	
17	
18	/// Decode BYTE_STREAM_SPLIT encoded floats into pre-allocated buffer
19	pub fn decodeFloat32Into(data: []const u8, result: []f32) !void {
20	    return decodeGenericInto(f32, data, result);
21	}
22	
23	/// Decode BYTE_STREAM_SPLIT encoded doubles into pre-allocated buffer
24	pub fn decodeFloat64Into(data: []const u8, result: []f64) !void {
25	    return decodeGenericInto(f64, data, result);
26	}
27	
28	/// Decode BYTE_STREAM_SPLIT encoded 32-bit integers into pre-allocated buffer
29	pub fn decodeInt32Into(data: []const u8, result: []i32) !void {
30	    return decodeGenericInto(i32, data, result);
31	}
32	
33	/// Decode BYTE_STREAM_SPLIT encoded 64-bit integers into pre-allocated buffer
34	pub fn decodeInt64Into(data: []const u8, result: []i64) !void {
35	    return decodeGenericInto(i64, data, result);
36	}
37	
38	/// Decode BYTE_STREAM_SPLIT encoded 16-bit floats into pre-allocated buffer
39	pub fn decodeFloat16Into(data: []const u8, result: []f16) !void {
40	    return decodeGenericInto(f16, data, result);
41	}
42	
43	/// Generic decoder that writes into pre-allocated buffer
44	fn decodeGenericInto(comptime T: type, data: []const u8, result: []T) !void {
45	    const byte_width = @sizeOf(T);
46	    const num_values = result.len;
47	    
48	    const required_generic = std.math.mul(usize, num_values, byte_width) catch return error.InsufficientData;
49	    if (data.len < required_generic) {
50	        return error.InsufficientData;
51	    }
52	    
53	    // Each stream contains one byte from each value
54	    // Stream 0: all byte 0s, Stream 1: all byte 1s, etc.
55	    const streams: [byte_width][]const u8 = blk: {
56	        var s: [byte_width][]const u8 = undefined;
57	        for (0..byte_width) |i| {
58	            const start = i * num_values;
59	            const end = (i + 1) * num_values;
60	            s[i] = data[start..end];
61	        }
62	        break :blk s;
63	    };
64	    
65	    // Reconstruct each value from its bytes
66	    for (0..num_values) |i| {
67	        var bytes: [@sizeOf(T)]u8 = undefined;
68	        inline for (0..byte_width) |j| {
69	            bytes[j] = streams[j][i];
70	        }
71	        result[i] = @bitCast(bytes);
72	    }
73	}
74	
75	/// Decode BYTE_STREAM_SPLIT for fixed-length byte arrays
76	fn decodeFixedLenInto(data: []const u8, result: [][]u8, type_length: usize) !void {
77	    const num_values = result.len;
78	    const required = std.math.mul(usize, num_values, type_length) catch return error.InsufficientData;
79	    
80	    if (data.len < required) {
81	        return error.InsufficientData;
82	    }
83	    
84	    // For fixed-length byte arrays, streams are organized similarly
85	    for (0..num_values) |i| {
86	        for (0..type_length) |j| {
87	            const stream_offset = j * num_values;
88	            result[i][j] = data[stream_offset + i];
89	        }
90	    }
91	}
92	
93	// =============================================================================
94	// Allocating versions
95	// =============================================================================
96	
97	/// Decode BYTE_STREAM_SPLIT encoded f32 values with allocation
98	pub fn decodeFloat32Alloc(allocator: std.mem.Allocator, data: []const u8, num_values: usize) ![]f32 {
99	    const result = try allocator.alloc(f32, num_values);
100	    errdefer allocator.free(result);
101	    try decodeFloat32Into(data, result);
102	    return result;
103	}
104	
105	/// Decode BYTE_STREAM_SPLIT encoded f64 values with allocation
106	pub fn decodeFloat64Alloc(allocator: std.mem.Allocator, data: []const u8, num_values: usize) ![]f64 {
107	    const result = try allocator.alloc(f64, num_values);
108	    errdefer allocator.free(result);
109	    try decodeFloat64Into(data, result);
110	    return result;
111	}
112	
113	/// Decode BYTE_STREAM_SPLIT encoded i32 values with allocation
114	pub fn decodeInt32Alloc(allocator: std.mem.Allocator, data: []const u8, num_values: usize) ![]i32 {
115	    const result = try allocator.alloc(i32, num_values);
116	    errdefer allocator.free(result);
117	    try decodeInt32Into(data, result);
118	    return result;
119	}
120	
121	/// Decode BYTE_STREAM_SPLIT encoded i64 values with allocation
122	pub fn decodeInt64Alloc(allocator: std.mem.Allocator, data: []const u8, num_values: usize) ![]i64 {
123	    const result = try allocator.alloc(i64, num_values);
124	    errdefer allocator.free(result);
125	    try decodeInt64Into(data, result);
126	    return result;
127	}
128	
129	/// Decode BYTE_STREAM_SPLIT encoded fixed-length byte arrays with allocation
130	pub fn decodeFixedLenAlloc(allocator: std.mem.Allocator, data: []const u8, num_values: usize, type_length: usize) ![][]u8 {
131	    const required = std.math.mul(usize, num_values, type_length) catch return error.InsufficientData;
132	    if (data.len < required) {
133	        return error.InsufficientData;
134	    }
135	
136	    // Allocate the outer slice
137	    const result = try allocator.alloc([]u8, num_values);
138	    errdefer allocator.free(result);
139	
140	    // Allocate each inner slice
141	    var allocated: usize = 0;
142	    errdefer {
143	        for (result[0..allocated]) |slice| {
144	            allocator.free(slice);
145	        }
146	    }
147	
148	    for (0..num_values) |i| {
149	        result[i] = try allocator.alloc(u8, type_length);
150	        allocated += 1;
151	    }
152	
153	    // Decode into the allocated buffers
154	    try decodeFixedLenInto(data, result, type_length);
155	    return result;
156	}
