1	//! DELTA_LENGTH_BYTE_ARRAY Encoding
2	//!
3	//! This encoding is for variable-length byte arrays (strings, binary).
4	//! It stores the lengths using DELTA_BINARY_PACKED encoding, followed by
5	//! the concatenated raw bytes of all values.
6	//!
7	//! Structure:
8	//! - Lengths: encoded using DELTA_BINARY_PACKED (as i32 values)
9	//! - Values: concatenated raw bytes
10	//!
11	//! Reference: https://parquet.apache.org/docs/file-format/data-pages/encodings/#delta-length-byte-array-delta_length_byte_array--6
12	
13	const std = @import("std");
14	const safe = @import("../safe.zig");
15	const delta_binary_packed = @import("delta_binary_packed.zig");
16	
17	pub const Error = error{
18	    InvalidLength,
19	    InsufficientData,
20	    OutOfMemory,
21	} || delta_binary_packed.Error;
22	
23	/// Decode DELTA_LENGTH_BYTE_ARRAY encoded byte arrays
24	/// Returns a slice of slices pointing into the decoded data buffer
25	pub fn decode(allocator: std.mem.Allocator, data: []const u8) Error!DecodeResult {
26	    // First, decode the lengths using DELTA_BINARY_PACKED
27	    var lengths_decoder = delta_binary_packed.Decoder(i32).init(data);
28	    const lengths = try lengths_decoder.decode(allocator);
29	    errdefer allocator.free(lengths);
30	    
31	    const values_start = lengths_decoder.pos;
32	    const values_data = data[values_start..];
33	    
34	    // Validate lengths and calculate total size
35	    var total_size: usize = 0;
36	    for (lengths) |len| {
37	        if (len < 0) {
38	            return error.InvalidLength;
39	        }
40	        const ulen = safe.castTo(usize, len) catch return error.InvalidLength;
41	        total_size = std.math.add(usize, total_size, ulen) catch return error.InsufficientData;
42	    }
43	    
44	    if (values_data.len < total_size) {
45	        return error.InsufficientData;
46	    }
47	    
48	    // Build result - copy each value
49	    const result = allocator.alloc([]const u8, lengths.len) catch return error.OutOfMemory;
50	    var initialized: usize = 0;
51	    errdefer {
52	        for (result[0..initialized]) |slice| allocator.free(slice);
53	        allocator.free(result);
54	    }
55	    
56	    var offset: usize = 0;
57	    for (lengths, 0..) |len, i| {
58	        const length: usize = safe.castTo(usize, len) catch return error.InvalidLength;
59	        const value = safe.slice(values_data, offset, length) catch return error.InsufficientData;
60	        result[i] = allocator.dupe(u8, value) catch return error.OutOfMemory;
61	        initialized += 1;
62	        offset += length;
63	    }
64	    
65	    allocator.free(lengths);
66	    
67	    return .{
68	        .values = result,
69	        .allocator = allocator,
70	    };
71	}
72	
73	/// Result of decoding DELTA_LENGTH_BYTE_ARRAY
74	pub const DecodeResult = struct {
75	    values: [][]const u8,
76	    allocator: std.mem.Allocator,
77	    
78	    pub fn deinit(self: *DecodeResult) void {
79	        for (self.values) |slice| self.allocator.free(slice);
80	        self.allocator.free(self.values);
81	    }
82	};
