89	    const allocator = std.testing.allocator;
90	    
91	    // Three strings: "abc", "defgh", "ij"
92	    // Lengths: [3, 5, 2]
93	    // Delta encoded lengths:
94	    // - header: block_size=128, mini_blocks=4, total=3, first=3
95	    // - block: min_delta=-1 (zigzag: 1), values vary
96	    //
97	    // For simplicity, use constant delta = 0 for testing
98	    const data = [_]u8{
99	        // DELTA_BINARY_PACKED header for lengths [3, 5, 2]
100	        0x80, 0x01, // block_size = 128
101	        0x04, // num_mini_blocks = 4
102	        0x03, // total_values = 3
103	        0x06, // first_value = 3 (zigzag: 3 -> 6)
104	        // Block header - deltas are [2, -3], min_delta = -3
105	        0x05, // min_delta = -3 (zigzag: -3 -> 5)
106	        // bit_widths: need 3 bits to store [2-(-3)=5, -3-(-3)=0] = [5, 0]
107	        0x03, 0x00, 0x00, 0x00, // bit_widths [3, 0, 0, 0]
108	        // Mini-block 0: values [5, 0] bit-packed at 3 bits each
109	        // 5 = 101, 0 = 000 -> 0b00_000_101 = 0x05, but we need 32 values...
110	        // Actually for 2 values in mini-block, it's (2*3+7)/8 = 1 byte minimum
111	        // But mini_block_size is 32, so we'd need 32*3/8 = 12 bytes
112	        // This is complex - let's use a simpler test case
113	    };
