127	    };
128	    
129	    var result = try decode(allocator, &simple_data);
130	    defer result.deinit();
131	    
132	    try std.testing.expectEqual(@as(usize, 3), result.values.len);
133	    try std.testing.expectEqualStrings("abc", result.values[0]);
