1	//! DELTA_BYTE_ARRAY Encoding (Incremental Encoding)
2	//!
3	//! This encoding is optimized for sorted strings or strings with common prefixes.
4	//! It stores each value as:
5	//! - Prefix length: how many bytes to copy from the previous value
6	//! - Suffix: the new bytes after the prefix
7	//!
8	//! Structure:
9	//! - Prefix lengths: encoded using DELTA_BINARY_PACKED (as i32)
10	//! - Suffix lengths: encoded using DELTA_BINARY_PACKED (as i32)
11	//! - Suffixes: concatenated raw suffix bytes
12	//!
13	//! Example: ["apple", "application", "apply"]
14	//! - "apple" -> prefix=0, suffix="apple"
15	//! - "application" -> prefix=5, suffix="ication" (shares "apple" prefix... wait no)
16	//! - Actually: "appl" is common, so prefix=4, suffix="ication"
17	//!
18	//! Reference: https://parquet.apache.org/docs/file-format/data-pages/encodings/#delta-strings-delta_byte_array--7
19	
20	const std = @import("std");
21	const safe = @import("../safe.zig");
22	const delta_binary_packed = @import("delta_binary_packed.zig");
23	
24	pub const Error = error{
25	    InvalidPrefixLength,
26	    InvalidSuffixLength,
27	    PrefixLengthTooLarge,
28	    InsufficientData,
29	    OutOfMemory,
30	} || delta_binary_packed.Error;
31	
32	/// Decode DELTA_BYTE_ARRAY encoded strings
33	pub fn decode(allocator: std.mem.Allocator, data: []const u8) Error!DecodeResult {
34	    if (data.len == 0) {
35	        return .{
36	            .values = &[_][]const u8{},
37	            .allocator = allocator,
38	        };
39	    }
40	    
41	    // Decode prefix lengths
42	    var prefix_decoder = delta_binary_packed.Decoder(i32).init(data);
43	    const prefix_lengths = try prefix_decoder.decode(allocator);
44	    errdefer allocator.free(prefix_lengths);
45	    
46	    const num_values = prefix_lengths.len;
47	    if (num_values == 0) {
48	        allocator.free(prefix_lengths);
49	        return .{
50	            .values = allocator.alloc([]const u8, 0) catch return error.OutOfMemory,
51	            .allocator = allocator,
52	        };
53	    }
54	    
55	    // Decode suffix lengths from remaining data
56	    var suffix_decoder = delta_binary_packed.Decoder(i32).init(data[prefix_decoder.pos..]);
57	    const suffix_lengths = try suffix_decoder.decode(allocator);
58	    errdefer allocator.free(suffix_lengths);
59	    
60	    if (suffix_lengths.len != num_values) {
61	        return error.InsufficientData;
62	    }
63	    
64	    // Calculate total suffix bytes and validate
65	    var total_suffix_bytes: usize = 0;
66	    for (suffix_lengths) |len| {
67	        if (len < 0) {
68	            return error.InvalidSuffixLength;
69	        }
70	        total_suffix_bytes += safe.castTo(usize, len) catch return error.InvalidSuffixLength;
71	    }
72	    
73	    const suffix_data_start = std.math.add(usize, prefix_decoder.pos, suffix_decoder.pos) catch return error.InsufficientData;
74	    const suffix_data = data[suffix_data_start..];
75	    
76	    if (suffix_data.len < total_suffix_bytes) {
77	        return error.InsufficientData;
78	    }
79	    
80	    // Build result values
81	    const result = allocator.alloc([]u8, num_values) catch return error.OutOfMemory;
82	    var initialized: usize = 0;
83	    errdefer {
84	        for (result[0..initialized]) |slice| allocator.free(slice);
85	        allocator.free(result);
86	    }
87	    
88	    var suffix_offset: usize = 0;
89	    var last_value: []const u8 = "";
90	    
91	    for (0..num_values) |i| {
92	        const prefix_len = prefix_lengths[i];
93	        const suffix_len = suffix_lengths[i];
94	        
95	        if (prefix_len < 0) {
96	            return error.InvalidPrefixLength;
97	        }
98	        
99	        const prefix_length: usize = safe.castTo(usize, prefix_len) catch return error.InvalidPrefixLength;
100	        const suffix_length: usize = safe.castTo(usize, suffix_len) catch return error.InvalidSuffixLength;
101	        
102	        if (prefix_length > last_value.len) {
103	            return error.PrefixLengthTooLarge;
104	        }
105	        
106	        // Allocate space for this value
107	        const value_len = prefix_length + suffix_length;
108	        const value = allocator.alloc(u8, value_len) catch return error.OutOfMemory;
109	        errdefer allocator.free(value);
110	        
111	        // Copy prefix from previous value
112	        if (prefix_length > 0) {
113	            @memcpy(value[0..prefix_length], last_value[0..prefix_length]);
114	        }
115	        
116	        // Copy suffix from data
117	        if (suffix_length > 0) {
118	            @memcpy(value[prefix_length..], safe.slice(suffix_data, suffix_offset, suffix_length) catch return error.InsufficientData);
119	        }
120	        
121	        result[i] = value;
122	        initialized += 1;
123	        last_value = value;
124	        suffix_offset += suffix_length;
125	    }
126	    
127	    allocator.free(prefix_lengths);
128	    allocator.free(suffix_lengths);
129	    
130	    // Cast to const slices
131	    const const_result = allocator.alloc([]const u8, num_values) catch return error.OutOfMemory;
132	    for (result, 0..) |v, i| {
133	        const_result[i] = v;
134	    }
135	    allocator.free(result);
136	    
137	    return .{
138	        .values = const_result,
139	        .allocator = allocator,
140	    };
141	}
142	
143	/// Result of decoding DELTA_BYTE_ARRAY
144	pub const DecodeResult = struct {
145	    values: [][]const u8,
146	    allocator: std.mem.Allocator,
147	    
148	    pub fn deinit(self: *DecodeResult) void {
149	        for (self.values) |slice| {
150	            const mutable: []u8 = @constCast(slice);
151	            self.allocator.free(mutable);
152	        }
153	        self.allocator.free(self.values);
154	    }
155	};
