1	//! Compression codec support for Parquet
2	//!
3	//! Parquet supports multiple compression codecs. This module provides
4	//! compression and decompression for supported codecs.
5	//!
6	//! Use `-Dcodecs=` to control which codecs are included (default: all).
7	//! Values: all, c-only, none, zig-only, or comma-separated list of: c-zstd,zstd,c-snappy,snappy,c-gzip,gzip,c-lz4,lz4,c-brotli,brotli
8	
9	const build_options = @import("build_options");
10	
11	pub const zstd = if (build_options.enable_zstd) @import("c_zstd.zig") else {};
12	pub const snappy = if (build_options.enable_snappy) @import("c_snappy.zig") else {};
13	pub const gzip = if (build_options.enable_gzip) @import("c_gzip.zig") else {};
14	pub const lz4 = if (build_options.enable_lz4) @import("c_lz4.zig") else {};
15	pub const brotli = if (build_options.enable_brotli) @import("c_brotli.zig") else {};
16	
17	pub const zig_zstd = if (build_options.enable_zig_zstd) @import("zstd.zig") else {};
18	pub const zig_snappy = if (build_options.enable_zig_snappy) @import("snappy.zig") else {};
19	pub const zig_gzip = if (build_options.enable_zig_gzip) @import("gzip.zig") else {};
20	pub const zig_lz4 = if (build_options.enable_zig_lz4) @import("lz4.zig") else {};
21	pub const zig_brotli = if (build_options.enable_zig_brotli) @import("brotli.zig") else {};
22	
23	const std = @import("std");
24	const format = @import("../format.zig");
