38	/// Compress data based on the codec
39	pub fn compress(
40	    allocator: std.mem.Allocator,
41	    data: []const u8,
42	    codec: format.CompressionCodec,
43	) CompressError![]u8 {
44	    switch (codec) {
45	        .uncompressed => {
46	            return allocator.dupe(u8, data) catch return error.OutOfMemory;
47	        },
48	        .zstd => {
49	            if (build_options.enable_zig_zstd) {
50	                return zig_zstd.compress(allocator, data) catch |e| switch (e) {
51	                    error.CompressionError => return error.CompressionError,
52	                    error.OutOfMemory => return error.OutOfMemory,
53	                    error.DecompressionError => return error.CompressionError,
54	                    error.InvalidSize => return error.CompressionError,
55	                };
56	            } else if (build_options.enable_zstd) {
57	                return zstd.compress(allocator, data) catch |e| switch (e) {
58	                    error.CompressionError => return error.CompressionError,
59	                    error.OutOfMemory => return error.OutOfMemory,
60	                    error.DecompressionError => return error.CompressionError,
61	                    error.InvalidSize => return error.CompressionError,
62	                };
63	            }
64	            return error.UnsupportedCompression;
65	        },
66	        .gzip => {
67	            if (build_options.enable_zig_gzip) {
68	                return zig_gzip.compress(allocator, data) catch |e| switch (e) {
69	                    error.CompressionError => return error.CompressionError,
70	                    error.OutOfMemory => return error.OutOfMemory,
71	                    error.DecompressionError => return error.CompressionError,
72	                    error.InvalidSize => return error.CompressionError,
73	                };
74	            } else if (build_options.enable_gzip) {
