79	                    error.InvalidSize => return error.CompressionError,
80	                };
81	            }
82	            return error.UnsupportedCompression;
83	        },
84	        .snappy => {
85	            if (build_options.enable_zig_snappy) {
86	                return zig_snappy.compress(allocator, data) catch |e| switch (e) {
87	                    error.CompressionError => return error.CompressionError,
