112	                    error.CompressionError => return error.CompressionError,
113	                    error.OutOfMemory => return error.OutOfMemory,
114	                    error.DecompressionError => return error.CompressionError,
115	                };
116	            }
117	            return error.UnsupportedCompression;
118	        },
119	        .brotli => {
120	            if (build_options.enable_zig_brotli) {
121	                return zig_brotli.compress(allocator, data) catch |e| switch (e) {
122	                    error.CompressionError => return error.CompressionError,
123	                    error.OutOfMemory => return error.OutOfMemory,
124	                    error.DecompressionError => return error.CompressionError,
125	                    error.InvalidSize => return error.CompressionError,
126	                };
127	            } else if (build_options.enable_brotli) {
