1	//! Lazy reader that fetches only the pages of a column chunk whose row ranges
2	//! intersect a caller-supplied `RowRanges`.
3	//!
4	//! Produces a byte buffer laid out as `[dict_page?][data_page_k0][data_page_k1]...`
5	//! — i.e. exactly what the existing `PageIterator` / `readColumnDynamic`
6	//! already know how to consume. Pages that are not selected are never read
7	//! from the source and never decompressed, which is the whole point of the
8	//! page-index skip path.
9	//!
10	//! The dictionary page (if any) is always included, since every data page in
11	//! the chunk may reference it.
12	//!
13	//! Contiguous runs of selected pages are coalesced into a single `readAt` for
14	//! remote-I/O friendliness.
15	
16	const std = @import("std");
17	const safe = @import("safe.zig");
18	const format = @import("format.zig");
19	const seekable_reader = @import("seekable_reader.zig");
20	const row_ranges = @import("row_ranges.zig");
21	
22	pub const SeekableReader = seekable_reader.SeekableReader;
23	pub const RowRanges = row_ranges.RowRanges;
24	pub const RowRange = row_ranges.RowRange;
25	
26	pub const Error = error{
27	    InputOutput,
28	    OutOfMemory,
29	    InvalidPageIndex,
30	    InvalidArgument,
31	    IntegerOverflow,
32	};
33	
34	/// Describes one selected data page within the returned buffer.
35	pub const SelectedPage = struct {
36	    /// Index into the `OffsetIndex.page_locations` slice.
37	    page_index: usize,
38	    /// First top-level row index within the row group.
39	    first_row_index: u64,
40	    /// Exclusive upper bound of this page's rows within the row group.
41	    /// Equals `rg_num_rows` for the final page.
42	    end_row_index: u64,
43	    /// Offset within `PageRangeResult.data` where this page (header+body)
44	    /// begins. Dict page — if present — occupies `[0, data[0].buffer_offset)`.
45	    buffer_offset: usize,
46	    /// Number of bytes in `PageRangeResult.data` belonging to this page.
47	    buffer_length: usize,
48	};
49	
50	pub const PageRangeResult = struct {
51	    /// `[dict_page?][selected data pages concatenated in chunk order]`.
52	    /// Drop-in replacement for `readColumnChunkData`'s output for a filtered read.
53	    data: []u8,
54	    /// True when `data[0..selected[0].buffer_offset]` is a dictionary page.
55	    has_dictionary: bool,
56	    /// Selected data pages, in chunk order (ascending `page_index`).
57	    selected: []SelectedPage,
58	
59	    pub fn deinit(self: *PageRangeResult, allocator: std.mem.Allocator) void {
60	        if (self.data.len > 0) allocator.free(self.data);
61	        if (self.selected.len > 0) allocator.free(self.selected);
62	        self.* = .{ .data = &.{}, .has_dictionary = false, .selected = &.{} };
63	    }
64	
65	    /// Translate a decoded-row index (0-based within the decoded output) into
66	    /// the row-group-local row index. Returns null when `decoded_row` is past
67	    /// the total decoded row count.
68	    pub fn mapDecodedRow(self: *const PageRangeResult, decoded_row: u64) ?u64 {
69	        var seen: u64 = 0;
70	        for (self.selected) |sp| {
71	            const page_rows = sp.end_row_index - sp.first_row_index;
72	            if (decoded_row < seen + page_rows) {
73	                return sp.first_row_index + (decoded_row - seen);
74	            }
75	            seen += page_rows;
76	        }
77	        return null;
78	    }
79	
80	    /// Total decoded rows across every selected page.
81	    pub fn totalDecodedRows(self: *const PageRangeResult) u64 {
82	        var total: u64 = 0;
83	        for (self.selected) |sp| total += sp.end_row_index - sp.first_row_index;
84	        return total;
85	    }
86	};
87	
88	pub fn readSelectedPages(
89	    allocator: std.mem.Allocator,
90	    source: SeekableReader,
91	    chunk: *const format.ColumnChunk,
92	    offset_index: *const format.OffsetIndex,
93	    wanted: RowRanges,
94	    rg_num_rows: u64,
95	) Error!PageRangeResult {
96	    const meta = chunk.meta_data orelse return error.InvalidArgument;
97	    if (offset_index.page_locations.len == 0) {
98	        return .{ .data = &.{}, .has_dictionary = false, .selected = &.{} };
99	    }
100	
101	    // Identify which data pages intersect `wanted`.
102	    var selected_raw = try std.ArrayList(SelectedPage).initCapacity(allocator, offset_index.page_locations.len);
103	    errdefer selected_raw.deinit(allocator);
104	
105	    const n_pages = offset_index.page_locations.len;
106	    for (offset_index.page_locations, 0..) |loc, i| {
107	        if (loc.offset < 0 or loc.compressed_page_size < 0 or loc.first_row_index < 0) {
108	            return error.InvalidPageIndex;
109	        }
110	        const first: u64 = @intCast(loc.first_row_index);
111	        const end: u64 = if (i + 1 < n_pages) blk: {
112	            const next = offset_index.page_locations[i + 1].first_row_index;
113	            if (next < 0) return error.InvalidPageIndex;
114	            break :blk @intCast(next);
115	        } else rg_num_rows;
116	        if (end < first) return error.InvalidPageIndex;
117	        if (end == first) continue; // empty page — shouldn't happen but skip safely
118	
119	        if (!rangeIntersects(wanted, first, end)) continue;
120	
121	        const len = safe.castTo(usize, @as(u64, @intCast(loc.compressed_page_size))) catch return error.IntegerOverflow;
122	        try selected_raw.append(allocator, .{
123	            .page_index = i,
124	            .first_row_index = first,
125	            .end_row_index = end,
126	            .buffer_offset = 0, // filled in below
127	            .buffer_length = len,
128	        });
129	    }
130	
131	    // Compute dict-page presence + size.
132	    // Per Parquet convention, a dict page (when present) immediately precedes
133	    // the first data page; its size is `first_data_page_offset - dict_offset`.
134	    var dict_info: ?struct { offset: u64, length: usize } = null;
135	    if (meta.dictionary_page_offset) |dict_off| {
136	        if (dict_off > 0) {
137	            const first_data_off = if (selected_raw.items.len > 0) blk: {
138	                const first_selected_loc = offset_index.page_locations[selected_raw.items[0].page_index];
139	                break :blk first_selected_loc.offset;
140	            } else meta.data_page_offset;
141	            if (first_data_off <= dict_off) return error.InvalidPageIndex;
142	            // Dict size is distance from dict_off to the *first* data page in the
143	            // chunk — not the first selected data page (we might have skipped
144	            // initial data pages).
145	            const chunk_first_data = offset_index.page_locations[0].offset;
146	            if (chunk_first_data <= dict_off) return error.InvalidPageIndex;
147	            const dict_len_i64 = chunk_first_data - dict_off;
148	            const dict_len = safe.castTo(usize, dict_len_i64) catch return error.IntegerOverflow;
149	            dict_info = .{ .offset = @intCast(dict_off), .length = dict_len };
150	        }
151	    }
152	
153	    // Total output buffer size.
154	    var total: usize = 0;
155	    if (dict_info) |d| total += d.length;
156	    for (selected_raw.items) |*sp| total += sp.buffer_length;
157	
158	    if (total == 0) {
159	        selected_raw.deinit(allocator);
160	        return .{ .data = &.{}, .has_dictionary = false, .selected = &.{} };
161	    }
162	
163	    const buffer = try allocator.alloc(u8, total);
164	    errdefer allocator.free(buffer);
165	
166	    // Read dict page (if any) — single readAt.
167	    var cursor: usize = 0;
168	    if (dict_info) |d| {
169	        const got = source.readAt(d.offset, buffer[0..d.length]) catch return error.InputOutput;
170	        if (got != d.length) return error.InputOutput;
171	        cursor = d.length;
172	    }
173	
174	    // Coalesce contiguous runs of selected data pages into one readAt each.
175	    var i: usize = 0;
176	    while (i < selected_raw.items.len) {
177	        const run_start = i;
178	        var run_len: usize = selected_raw.items[i].buffer_length;
179	        var expected_next_offset: i64 = blk: {
180	            const loc = offset_index.page_locations[selected_raw.items[i].page_index];
181	            break :blk loc.offset + @as(i64, @intCast(selected_raw.items[i].buffer_length));
182	        };
183	        var j = i + 1;
184	        while (j < selected_raw.items.len) : (j += 1) {
185	            const next_loc = offset_index.page_locations[selected_raw.items[j].page_index];
186	            if (next_loc.offset != expected_next_offset) break;
187	            run_len += selected_raw.items[j].buffer_length;
188	            expected_next_offset = next_loc.offset + @as(i64, @intCast(selected_raw.items[j].buffer_length));
189	        }
190	
191	        // Single readAt covering the run.
192	        const run_first_loc = offset_index.page_locations[selected_raw.items[run_start].page_index];
193	        if (run_first_loc.offset < 0) return error.InvalidPageIndex;
194	        const run_off: u64 = @intCast(run_first_loc.offset);
195	        const got = source.readAt(run_off, buffer[cursor .. cursor + run_len]) catch return error.InputOutput;
196	        if (got != run_len) return error.InputOutput;
197	
198	        // Assign buffer offsets for each page in the run.
199	        var sub_cursor = cursor;
200	        for (selected_raw.items[run_start..j]) |*sp| {
201	            sp.buffer_offset = sub_cursor;
202	            sub_cursor += sp.buffer_length;
203	        }
204	        cursor = sub_cursor;
205	
206	        i = j;
207	    }
208	
209	    return .{
210	        .data = buffer,
211	        .has_dictionary = dict_info != null,
212	        .selected = try selected_raw.toOwnedSlice(allocator),
213	    };
214	}
215	
216	fn rangeIntersects(wanted: RowRanges, first: u64, end: u64) bool {
217	    if (wanted.isEmpty()) return false;
218	    for (wanted.ranges) |r| {
219	        if (r.first >= end) break; // ranges sorted — no further overlap possible
220	        if (r.last > first) return true;
221	    }
222	    return false;
223	}
