231	/// Counting in-memory source — also verifies we only issue `readAt` for wanted
232	/// byte ranges, not the whole chunk.
233	const Source = struct {
234	    data: []const u8,
235	    reads: std.ArrayListUnmanaged(Record) = .empty,
236	    allocator: std.mem.Allocator,
237	
238	    const Record = struct { offset: u64, length: usize };
239	
240	    fn readAt(ctx: *anyopaque, offset: u64, buf: []u8) SeekableReader.Error!usize {
241	        const self: *Source = @ptrCast(@alignCast(ctx));
242	        self.reads.append(self.allocator, .{ .offset = offset, .length = buf.len }) catch return error.InputOutput;
243	        if (offset >= self.data.len) return 0;
244	        const end = @min(offset + buf.len, self.data.len);
245	        const n = end - offset;
246	        @memcpy(buf[0..n], self.data[offset..end]);
247	        return n;
248	    }
249	    fn sizeFn(ctx: *anyopaque) u64 {
250	        const self: *Source = @ptrCast(@alignCast(ctx));
251	        return self.data.len;
252	    }
253	    const vtable: SeekableReader.VTable = .{ .readAt = readAt, .size = sizeFn };
254	    fn reader(self: *Source) SeekableReader {
255	        return .{ .ptr = self, .vtable = &vtable };
256	    }
257	    fn deinit(self: *Source) void {
258	        self.reads.deinit(self.allocator);
259	    }
260	};
