1	//! Recursive flattening and assembly for nested Parquet data
2	//!
3	//! This module provides generalized functions to:
4	//! - Flatten nested `Value` structures into flat column arrays with def/rep levels
5	//! - Assemble flat column data back into nested `Value` structures
6	//!
7	//! These functions handle arbitrary nesting depth (list<struct<list<...>>>).
8	
9	const std = @import("std");
10	const schema_mod = @import("schema.zig");
11	const value_mod = @import("value.zig");
12	
13	const SchemaNode = schema_mod.SchemaNode;
14	const Value = value_mod.Value;
15	
16	const max_nesting_depth: u32 = 64;
17	
18	/// Represents a single leaf column's flattened data
19	pub const FlatColumn = struct {
20	    values: std.ArrayList(Value),
21	    def_levels: std.ArrayList(u32),
22	    rep_levels: std.ArrayList(u32),
23	
24	    pub fn init() FlatColumn {
25	        return .{
26	            .values = .empty,
27	            .def_levels = .empty,
28	            .rep_levels = .empty,
29	        };
30	    }
31	
32	    pub fn deinit(self: *FlatColumn, allocator: std.mem.Allocator) void {
33	        self.values.deinit(allocator);
34	        self.def_levels.deinit(allocator);
35	        self.rep_levels.deinit(allocator);
36	    }
37	};
38	
39	/// Collection of flattened columns for a schema
