148	                        ctx.current_rep = ctx.rep_depth;
149	                    }
150	                    try flattenRecursive(element, item, ctx, true, depth + 1);
151	                }
152	                ctx.rep_depth -= 1;
153	                ctx.current_def -= 1;
154	                if (!is_repeated) {
155	                    // Reset rep to 0 after processing list (ready for next top-level record)
156	                    ctx.current_rep = 0;
157	                }
158	            }
159	        },
160	        .map => |m| {
