187	                    ctx.current_def += value_extra_def;
188	                    try flattenRecursive(m.value, entry.value, ctx, true, depth + 1);
189	                    ctx.current_def -= value_extra_def;
190	                    ctx.column_index -= key_leaves;
191	                }
192	                ctx.rep_depth -= 1;
193	                ctx.current_def -= 1;
194	                if (!is_repeated) {
195	                    ctx.current_rep = 0;
196	                }
197	            }
198	        },
199	        .struct_ => |s| {
200	            const fields = value.asStruct();
201	            if (fields == null or value.isNull()) {
202	                // Null struct - write nulls to all field columns
203	                for (s.fields) |f| {
204	                    try writeNullToLeaves(f.node, ctx);
205	                    ctx.column_index += f.node.countLeafColumns();
206	                }
207	                // Reset column index
208	                for (s.fields) |f| {
209	                    ctx.column_index -= f.node.countLeafColumns();
210	                }
211	            } else {
