244	fn writeNullToLeaves(node: *const SchemaNode, ctx: *FlattenContext) !void {
245	    switch (node.*) {
246	        .optional => |child| try writeNullToLeaves(child, ctx),
247	        .list => |element| try writeNullToLeaves(element, ctx),
248	        .map => |m| {
249	            try writeNullToLeaves(m.key, ctx);
250	            ctx.column_index += m.key.countLeafColumns();
251	            try writeNullToLeaves(m.value, ctx);
252	            ctx.column_index -= m.key.countLeafColumns();
253	        },
254	        .struct_ => |s| {
255	            for (s.fields) |f| {
256	                try writeNullToLeaves(f.node, ctx);
257	                ctx.column_index += f.node.countLeafColumns();
258	            }
259	            for (s.fields) |f| {
260	                ctx.column_index -= f.node.countLeafColumns();
261	            }
262	        },
263	        .boolean, .int32, .int64, .float, .double, .byte_array, .fixed_len_byte_array => {
264	            const col = &ctx.columns.columns.items[ctx.column_index];
265	            try col.values.append(ctx.allocator, .{ .null_val = {} });
266	            try col.def_levels.append(ctx.allocator, ctx.current_def);
267	            try col.rep_levels.append(ctx.allocator, ctx.current_rep);
268	        },
269	    }
270	}
