1	//! Recursive flattening and assembly for nested Parquet data
2	//!
3	//! This module provides generalized functions to:
4	//! - Flatten nested `Value` structures into flat column arrays with def/rep levels
5	//! - Assemble flat column data back into nested `Value` structures
6	//!
7	//! These functions handle arbitrary nesting depth (list<struct<list<...>>>).
8	
9	const std = @import("std");
10	const schema_mod = @import("schema.zig");
11	const value_mod = @import("value.zig");
12	
13	const SchemaNode = schema_mod.SchemaNode;
14	const Value = value_mod.Value;
15	
16	const max_nesting_depth: u32 = 64;
17	
18	/// Represents a single leaf column's flattened data
19	pub const FlatColumn = struct {
20	    values: std.ArrayList(Value),
21	    def_levels: std.ArrayList(u32),
22	    rep_levels: std.ArrayList(u32),
23	
24	    pub fn init() FlatColumn {
25	        return .{
26	            .values = .empty,
27	            .def_levels = .empty,
28	            .rep_levels = .empty,
29	        };
30	    }
31	
32	    pub fn deinit(self: *FlatColumn, allocator: std.mem.Allocator) void {
33	        self.values.deinit(allocator);
34	        self.def_levels.deinit(allocator);
35	        self.rep_levels.deinit(allocator);
36	    }
37	};
38	
39	/// Collection of flattened columns for a schema
40	pub const FlatColumns = struct {
41	    columns: std.ArrayList(FlatColumn),
42	    allocator: std.mem.Allocator,
43	
44	    pub fn init(allocator: std.mem.Allocator) FlatColumns {
45	        return .{
46	            .columns = .empty,
47	            .allocator = allocator,
48	        };
49	    }
50	
51	    pub fn deinit(self: *FlatColumns) void {
52	        for (self.columns.items) |*col| {
53	            col.deinit(self.allocator);
54	        }
55	        self.columns.deinit(self.allocator);
56	    }
57	
58	    pub fn addColumn(self: *FlatColumns) !*FlatColumn {
59	        try self.columns.append(self.allocator, FlatColumn.init());
60	        return &self.columns.items[self.columns.items.len - 1];
61	    }
62	};
63	
64	/// Context for tracking levels during flattening
65	const FlattenContext = struct {
66	    allocator: std.mem.Allocator,
67	    columns: *FlatColumns,
68	    current_def: u32,
69	    current_rep: u32,
70	    rep_depth: u32, // tracks which repetition level we're at
71	    column_index: usize,
72	};
73	
74	/// Flatten a nested Value according to its schema into flat columns with levels.
75	///
76	/// This is the inverse of `assembleValue` - it takes a nested structure and
77	/// produces flat arrays suitable for Parquet column encoding.
78	pub fn flattenValue(
79	    allocator: std.mem.Allocator,
80	    node: *const SchemaNode,
81	    value: Value,
82	) !FlatColumns {
83	    var columns = FlatColumns.init(allocator);
84	    errdefer columns.deinit();
85	
86	    // Pre-allocate columns for all leaves
87	    const num_leaves = node.countLeafColumns();
88	    for (0..num_leaves) |_| {
89	        _ = try columns.addColumn();
90	    }
91	
92	    var ctx = FlattenContext{
93	        .allocator = allocator,
94	        .columns = &columns,
95	        .current_def = 0,
96	        .current_rep = 0,
97	        .rep_depth = 0,
98	        .column_index = 0,
99	    };
100	
101	    try flattenRecursive(node, value, &ctx, false, 0);
102	
103	    return columns;
104	}
105	
106	fn flattenRecursive(
107	    node: *const SchemaNode,
108	    value: Value,
109	    ctx: *FlattenContext,
110	    is_repeated: bool,
111	    depth: u32,
112	) !void {
113	    if (depth > max_nesting_depth) return error.NestingTooDeep;
114	    switch (node.*) {
115	        .optional => |child| {
116	            if (value.isNull()) {
117	                // Write null marker to all leaf columns under this optional
118	                try writeNullToLeaves(child, ctx);
119	            } else {
120	                ctx.current_def += 1;
121	                try flattenRecursive(child, value, ctx, is_repeated, depth + 1);
122	                ctx.current_def -= 1;
123	            }
124	        },
125	        .list => |element| {
126	            // Parquet list encoding with definition and repetition levels:
127	            // Definition levels:
128	            //   def=0: list is null
129	            //   def=1: list exists but is empty
130	            //   def>=2: element exists (higher values for nested optional fields)
131	            // Repetition levels:
132	            //   rep=0: first element of a new record (new row)
133	            //   rep=1: subsequent element in the same list (repeated at list level)
134	            //   rep=2+: for nested lists, repeating at inner level
135	            const items = value.asList();
136	            if (items == null or value.isNull()) {
137	                // Null list: def=0, rep unchanged (uses current_rep from context)
138	                try writeNullToLeaves(element, ctx);
139	            } else if (items.?.len == 0) {
140	                // Empty list: def stays at current level (repeated group has no instances)
141	                try writeNullToLeaves(element, ctx);
142	            } else {
143	                ctx.current_def += 1;
144	                ctx.rep_depth += 1;
145	                for (items.?, 0..) |item, i| {
146	                    if (i > 0) {
147	                        // Subsequent elements: rep=rep_depth (indicates repetition at this list level)
148	                        ctx.current_rep = ctx.rep_depth;
149	                    }
150	                    try flattenRecursive(element, item, ctx, true, depth + 1);
151	                }
152	                ctx.rep_depth -= 1;
153	                ctx.current_def -= 1;
154	                if (!is_repeated) {
155	                    // Reset rep to 0 after processing list (ready for next top-level record)
156	                    ctx.current_rep = 0;
157	                }
158	            }
159	        },
160	        .map => |m| {
161	            // Map levels: key_value repeated group adds +1 def, +1 rep.
162	            // Parquet schema always marks map values as OPTIONAL, so add +1 def for value
163	            // unless the node already has an .optional wrapper.
164	            const entries = value.asMap();
165	            const key_leaves = m.key.countLeafColumns();
166	            const value_extra_def: u32 = if (m.value.* == .optional) 0 else 1;
167	
168	            if (entries == null or value.isNull()) {
169	                try writeNullToLeaves(m.key, ctx);
170	                ctx.column_index += key_leaves;
171	                try writeNullToLeaves(m.value, ctx);
172	                ctx.column_index -= key_leaves;
173	            } else if (entries.?.len == 0) {
174	                try writeNullToLeaves(m.key, ctx);
175	                ctx.column_index += key_leaves;
176	                try writeNullToLeaves(m.value, ctx);
177	                ctx.column_index -= key_leaves;
178	            } else {
179	                ctx.current_def += 1;
180	                ctx.rep_depth += 1;
181	                for (entries.?, 0..) |entry, i| {
