12	/// Data page header
13	pub const DataPageHeader = struct {
14	    num_values: i32 = 0,
15	    encoding: Encoding = .plain,
16	    definition_level_encoding: Encoding = .rle,
17	    repetition_level_encoding: Encoding = .rle,
18	    statistics: ?Statistics = null,
19	
20	    const Self = @This();
21	
22	    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
23	        if (self.statistics) |*stats| stats.deinit(allocator);
24	        self.* = .{};
25	    }
26	
27	    pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !Self {
28	        var header = Self{};
29	        const saved_field_id = reader.last_field_id;
30	        reader.resetFieldTracking();
31	
32	        while (try reader.readFieldHeader()) |field| {
33	            switch (field.field_id) {
34	                1 => header.num_values = try reader.readI32(),
35	                2 => header.encoding = try Encoding.fromInt(try reader.readI32()),
36	                3 => header.definition_level_encoding = try Encoding.fromInt(try reader.readI32()),
37	                4 => header.repetition_level_encoding = try Encoding.fromInt(try reader.readI32()),
38	                5 => header.statistics = try Statistics.parse(allocator, reader),
39	                else => try reader.skip(field.field_type),
40	            }
41	        }
42	
43	        reader.last_field_id = saved_field_id;
44	        return header;
45	    }
46	
47	    /// Serialize to Thrift Compact Protocol
48	    pub fn serialize(self: *const Self, writer: *thrift.CompactWriter) !void {
49	        const saved = writer.saveFieldId();
50	        writer.resetFieldTracking();
51	
52	        try writer.writeFieldHeader(1, .i32);
53	        try writer.writeI32(self.num_values);
54	
55	        try writer.writeFieldHeader(2, .i32);
56	        try writer.writeI32(@intFromEnum(self.encoding));
57	
58	        try writer.writeFieldHeader(3, .i32);
59	        try writer.writeI32(@intFromEnum(self.definition_level_encoding));
60	
61	        try writer.writeFieldHeader(4, .i32);
62	        try writer.writeI32(@intFromEnum(self.repetition_level_encoding));
63	
64	        if (self.statistics) |*stats| {
65	            try writer.writeFieldHeader(5, .struct_);
66	            try stats.serialize(writer);
67	        }
68	
69	        try writer.writeStructEnd();
70	        writer.restoreFieldId(saved);
71	    }
72	};
