80	    encoding: Encoding = .plain,
81	    definition_levels_byte_length: i32 = 0,
82	    repetition_levels_byte_length: i32 = 0,
83	    is_compressed: bool = true, // default true per spec
84	    statistics: ?Statistics = null,
85	
86	    const Self = @This();
87	
88	    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
89	        if (self.statistics) |*stats| stats.deinit(allocator);
90	        self.* = .{};
91	    }
92	
93	    pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !Self {
94	        var header = Self{};
95	        const saved_field_id = reader.last_field_id;
96	        reader.resetFieldTracking();
97	
98	        while (try reader.readFieldHeader()) |field| {
99	            switch (field.field_id) {
100	                1 => header.num_values = try reader.readI32(),
101	                2 => header.num_nulls = try reader.readI32(),
102	                3 => header.num_rows = try reader.readI32(),
103	                4 => header.encoding = try Encoding.fromInt(try reader.readI32()),
104	                5 => header.definition_levels_byte_length = try reader.readI32(),
105	                6 => header.repetition_levels_byte_length = try reader.readI32(),
