122	
123	    const Self = @This();
124	
125	    pub fn parse(_: std.mem.Allocator, reader: *thrift.CompactReader) !Self {
126	        var header = Self{};
127	        const saved_field_id = reader.last_field_id;
128	        reader.resetFieldTracking();
129	
130	        while (try reader.readFieldHeader()) |field| {
131	            switch (field.field_id) {
132	                1 => header.num_values = try reader.readI32(),
133	                2 => header.encoding = try Encoding.fromInt(try reader.readI32()),
