145	        const saved = writer.saveFieldId();
146	        writer.resetFieldTracking();
147	
148	        try writer.writeFieldHeader(1, .i32);
149	        try writer.writeI32(self.num_values);
150	
151	        try writer.writeFieldHeader(2, .i32);
152	        try writer.writeI32(@intFromEnum(self.encoding));
