163	/// Page header
164	pub const PageHeader = struct {
165	    type_: PageType = .data_page,
166	    uncompressed_page_size: i32 = 0,
167	    compressed_page_size: i32 = 0,
168	    crc: ?i32 = null,
169	    data_page_header: ?DataPageHeader = null,
170	    dictionary_page_header: ?DictionaryPageHeader = null,
171	    data_page_header_v2: ?DataPageHeaderV2 = null,
172	
173	    const Self = @This();
174	
175	    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
176	        if (self.data_page_header) |*dph| dph.deinit(allocator);
177	        if (self.data_page_header_v2) |*dph| dph.deinit(allocator);
178	        self.* = .{};
179	    }
180	
181	    pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !Self {
182	        var header = Self{};
183	        const saved_field_id = reader.last_field_id;
184	        reader.resetFieldTracking();
185	
186	        while (try reader.readFieldHeader()) |field| {
187	            switch (field.field_id) {
188	                1 => header.type_ = try PageType.fromInt(try reader.readI32()),
189	                2 => header.uncompressed_page_size = try reader.readI32(),
190	                3 => header.compressed_page_size = try reader.readI32(),
191	                4 => header.crc = try reader.readI32(),
192	                5 => header.data_page_header = try DataPageHeader.parse(allocator, reader),
193	                7 => header.dictionary_page_header = try DictionaryPageHeader.parse(allocator, reader),
194	                8 => header.data_page_header_v2 = try DataPageHeaderV2.parse(allocator, reader),
195	                else => try reader.skip(field.field_type),
196	            }
197	        }
198	
199	        reader.last_field_id = saved_field_id;
200	        return header;
201	    }
202	
203	    /// Serialize to Thrift Compact Protocol
204	    pub fn serialize(self: *const Self, writer: *thrift.CompactWriter) !void {
205	        const saved = writer.saveFieldId();
206	        writer.resetFieldTracking();
207	
208	        try writer.writeFieldHeader(1, .i32);
209	        try writer.writeI32(@intFromEnum(self.type_));
210	
211	        try writer.writeFieldHeader(2, .i32);
212	        try writer.writeI32(self.uncompressed_page_size);
213	
214	        try writer.writeFieldHeader(3, .i32);
215	        try writer.writeI32(self.compressed_page_size);
216	
217	        if (self.crc) |c| {
218	            try writer.writeFieldHeader(4, .i32);
219	            try writer.writeI32(c);
220	        }
221	
222	        if (self.data_page_header) |*dph| {
223	            try writer.writeFieldHeader(5, .struct_);
224	            try dph.serialize(writer);
225	        }
226	
227	        if (self.dictionary_page_header) |*dph| {
228	            try writer.writeFieldHeader(7, .struct_);
229	            try dph.serialize(writer);
230	        }
231	
232	        try writer.writeStructEnd();
233	        writer.restoreFieldId(saved);
234	    }
235	};
