1	//! File metadata - the root structure in the Parquet footer
2	
3	const std = @import("std");
4	const safe = @import("../safe.zig");
5	const thrift = @import("../thrift/mod.zig");
6	const schema_mod = @import("schema.zig");
7	const row_group_mod = @import("row_group.zig");
8	
9	pub const SchemaElement = schema_mod.SchemaElement;
10	pub const RowGroup = row_group_mod.RowGroup;
11	pub const KeyValue = row_group_mod.KeyValue;
12	
13	/// File metadata - the root structure in the footer
14	pub const FileMetaData = struct {
15	    version: i32 = 0,
16	    schema: []SchemaElement = &.{},
17	    num_rows: i64 = 0,
18	    row_groups: []RowGroup = &.{},
19	    key_value_metadata: ?[]KeyValue = null,
20	    created_by: ?[]const u8 = null,
21	
22	    const Self = @This();
23	
24	    pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !Self {
25	        var meta = Self{};
26	        reader.resetFieldTracking();
27	
28	        while (try reader.readFieldHeader()) |field| {
29	            switch (field.field_id) {
30	                1 => meta.version = try reader.readI32(),
31	                2 => {
32	                    const list_header = try reader.readListHeader();
33	                    var schema_list = try allocator.alloc(SchemaElement, list_header.size);
34	                    for (0..list_header.size) |i| {
35	                        schema_list[i] = try SchemaElement.parse(allocator, reader);
36	                    }
37	                    meta.schema = schema_list;
38	                },
39	                3 => meta.num_rows = try reader.readI64(),
40	                4 => {
41	                    const list_header = try reader.readListHeader();
42	                    var row_groups_list = try allocator.alloc(RowGroup, list_header.size);
43	                    for (0..list_header.size) |i| {
44	                        row_groups_list[i] = try RowGroup.parse(allocator, reader);
45	                    }
46	                    meta.row_groups = row_groups_list;
47	                },
48	                5 => {
49	                    const list_header = try reader.readListHeader();
50	                    var kvs = try allocator.alloc(KeyValue, list_header.size);
51	                    for (0..list_header.size) |i| {
52	                        kvs[i] = try KeyValue.parse(allocator, reader);
53	                    }
54	                    meta.key_value_metadata = kvs;
55	                },
56	                6 => meta.created_by = try allocator.dupe(u8, try reader.readString()),
57	                else => try reader.skip(field.field_type),
58	            }
59	        }
60	
61	        return meta;
62	    }
63	
64	    /// Serialize to Thrift Compact Protocol
65	    pub fn serialize(self: *const Self, writer: *thrift.CompactWriter) !void {
66	        writer.resetFieldTracking();
67	
68	        try writer.writeFieldHeader(1, .i32);
69	        try writer.writeI32(self.version);
70	
71	        try writer.writeFieldHeader(2, .list);
72	        try writer.writeListHeader(.struct_, safe.castTo(u32, self.schema.len) catch return error.IntegerOverflow);
73	        for (self.schema) |*elem| {
74	            try elem.serialize(writer);
75	        }
76	
77	        try writer.writeFieldHeader(3, .i64);
78	        try writer.writeI64(self.num_rows);
79	
80	        try writer.writeFieldHeader(4, .list);
81	        try writer.writeListHeader(.struct_, safe.castTo(u32, self.row_groups.len) catch return error.IntegerOverflow);
82	        for (self.row_groups) |*rg| {
83	            try rg.serialize(writer);
84	        }
85	
86	        if (self.key_value_metadata) |kvs| {
87	            try writer.writeFieldHeader(5, .list);
88	            try writer.writeListHeader(.struct_, safe.castTo(u32, kvs.len) catch return error.IntegerOverflow);
89	            for (kvs) |*kv| {
90	                try kv.serialize(writer);
91	            }
92	        }
93	
94	        if (self.created_by) |cb| {
95	            try writer.writeFieldHeader(6, .binary);
96	            try writer.writeString(cb);
97	        }
98	
99	        try writer.writeStructEnd();
100	    }
101	};
