1	//! Public Reader API - convenience constructors for file/buffer backends.
2	//!
3	//! These standalone functions create io/ adapters, heap-allocate them,
4	//! and delegate to the core transport-neutral constructors.
5	
6	const std = @import("std");
7	const FileReader = @import("../../io/file_reader.zig").FileReader;
8	const BufferReader = @import("../../io/buffer_reader.zig").BufferReader;
9	const core_dynamic = @import("../../core/dynamic_reader.zig");
10	const seekable_reader = @import("../../core/seekable_reader.zig");
11	const parquet_reader = @import("../../core/parquet_reader.zig");
12	
13	pub const SeekableReader = seekable_reader.SeekableReader;
14	pub const DynamicReader = core_dynamic.DynamicReader;
15	pub const DynamicReaderError = core_dynamic.DynamicReaderError;
16	pub const DynamicReaderOptions = core_dynamic.DynamicReaderOptions;
17	pub const BackendCleanup = parquet_reader.BackendCleanup;
18	
19	// -- DynamicReader convenience constructors --
20	
21	/// Open a Parquet file for schema-agnostic reading. Returns a `DynamicReader`
22	/// that can read any file without knowing the schema at compile time.
23	/// Call `deinit()` when done; the caller retains ownership of `file`.
24	pub fn openFileDynamic(allocator: std.mem.Allocator, file: std.Io.File, io: std.Io, options: DynamicReaderOptions) DynamicReaderError!DynamicReader {
25	    const fr = allocator.create(FileReader) catch return error.OutOfMemory;
26	    errdefer allocator.destroy(fr);
27	    fr.* = FileReader.init(file, io) catch return error.Unseekable;
28	    var reader = try DynamicReader.initFromSeekable(allocator, fr.reader(), options);
29	    reader._backend_cleanup = .{
30	        .ptr = @ptrCast(fr),
31	        .deinit_fn = &fileReaderCleanup,
32	    };
33	    return reader;
34	}
35	
36	/// Open a Parquet file from an in-memory buffer for schema-agnostic reading.
37	/// The caller must ensure `data` outlives the returned `DynamicReader`.
38	pub fn openBufferDynamic(allocator: std.mem.Allocator, data: []const u8, options: DynamicReaderOptions) DynamicReaderError!DynamicReader {
39	    const br = allocator.create(BufferReader) catch return error.OutOfMemory;
40	    errdefer allocator.destroy(br);
41	    br.* = BufferReader.init(data);
42	    var reader = try DynamicReader.initFromSeekable(allocator, br.reader(), options);
43	    reader._backend_cleanup = .{
44	        .ptr = @ptrCast(br),
45	        .deinit_fn = &bufferReaderCleanup,
46	    };
47	    return reader;
48	}
49	
50	// -- Cleanup callbacks --
51	
52	fn fileReaderCleanup(ptr: *anyopaque, allocator: std.mem.Allocator) void {
53	    const fr: *FileReader = @ptrCast(@alignCast(ptr));
54	    allocator.destroy(fr);
55	}
56	
57	fn bufferReaderCleanup(ptr: *anyopaque, allocator: std.mem.Allocator) void {
58	    const br: *BufferReader = @ptrCast(@alignCast(ptr));
59	    allocator.destroy(br);
60	}
